/* DAWAH X — ahmad, অধ্যায় 7 · খণ্ড 7 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][7]=[[1201,1201,"","আমি আমার বাবার কাছে ব্যাজটা পেয়েছি, আমি তোমার জন্য গুজব করার চেয়ে ভাল। আমরা জানতাম সে কোথায় তার লোকদের বিয়ে করেছে আর আমরা তার নারীসুলভ কথা বলছি না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْحَسَنِ بْنِ عَلِيٍّ ‏ ‏إِنَّ ‏ ‏الشِّيعَةَ ‏ ‏يَزْعُمُونَ أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَرْجِعُ قَالَ ‏ ‏كَذَبَ أُولَئِكَ الْكَذَّابُونَ لَوْ عَلِمْنَا ذَاكَ مَا تَزَوَّجَ نِسَاؤُهُ وَلَا قَسَمْنَا مِيرَاثَهُ ‏","","",""],[1202,1202,"","আমার কী হয়েছে, সেই সম্বন্ধে আমরা ঈশ্বর সম্বন্ধে কথা বলেছিলাম । সে আর বন্ধু নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي قَدْ عَفَوْتُ لَكُمْ عَنْ الْخَيْلِ ‏ ‏وَالرَّقِيقِ ‏ ‏وَلَا ‏ ‏صَدَقَةَ ‏ ‏فِيهِمَا ‏","","",""],[1203,1203,"","আমরা ঈশ্বরের সঙ্গে আমার কথা বলেছিলাম, সিংহাসনে বজ্‌জের মাধ্যমে সিংহাসনের ভাগ্য নিয়ে আমরা কথা বলেছিলাম । পাঠকেরা তার জীবনের দশ বছরের মধ্যে এটা প্রকাশ করবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عُثْمَانَ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ أَبُو عُمَرَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ زَاذَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَرَأَ الْقُرْآنَ ‏ ‏فَاسْتَظْهَرَهُ ‏ ‏شُفِّعَ ‏ ‏فِي عَشَرَةٍ مِنْ أَهْلِ بَيْتِهِ قَدْ وَجَبَتْ لَهُمْ النَّارُ ‏","","",""],[1204,1204,"","আমার বাবা আমার বাবার প্রতি ভালবাসা সম্বন্ধে কথা বলেছিলেন । আর অ্যাপার্টমেন্টে কয়েক মিনিট।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِشْكَابٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عُبَيْدَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَفَوْتُ عَنْ الْخَيْلِ ‏ ‏وَالرَّقِيقِ ‏ ‏فِي ‏ ‏الصَّدَقَةِ ‏","","",""],[1205,1205,"","আমরা ইশ্বরের সাথে কথা বলেছি যে তারা যা করেছে তা নিয়ে আমি আমার বাবার কাছে দু:খিত, ঈশ্বরের দোহাই, আমি আমার বিবেক অনুযায়ী বেনের জন্য আমার বাবার প্রতি আমার ভালোবাসার জন্য দুঃখিত। বেটাকে ছবি বা কুকুর দিয়ে এসব ছবি দিয়ে থাকতে দেয়া যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلْمٍ خَلِيلُ بْنُ سَلْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّا لَا نَدْخُلُ بَيْتًا فِيهِ صُورَةٌ أَوْ كَلْبٌ وَكَانَ الْكَلْبُ ‏ ‏لِلْحَسَنِ ‏ ‏فِي الْبَيْتِ ‏","","",""],[1206,1206,"","আমি আমার প্রভুর কাছে আমার প্রভুর কাছে প্রতিজ্ঞা করেছিলাম, আপনার প্রভু ঈশ্বরের কাছে করা তাঁর প্রতিজ্ঞা রক্ষা করেছেন । ( খ) কেন আমাদের ঈশ্বরের কাছে প্রার্থনা করা উচিত?","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ أَبُو مَعْمَرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ عُبَادٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَلِيٍّ ‏ ‏أَرَأَيْتَ مَسِيرَكَ هَذَا ‏ ‏عَهْدٌ ‏ ‏عَهِدَهُ ‏ ‏إِلَيْكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْ رَأْيٌ رَأَيْتَهُ قَالَ مَا تُرِيدُ إِلَى هَذَا قُلْتُ دِينَنَا دِينَنَا قَالَ ‏ ‏مَا ‏ ‏عَهِدَ ‏ ‏إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ شَيْئًا وَلَكِنْ رَأْيٌ رَأَيْتُهُ ‏","","",""],[1207,1207,"","আমরা ঈশ্বরের অনুগ্রহ নিয়ে বাইরে বের হবার চেষ্টা করছিলাম, ঈশ্বরের অনুগ্রহ নিয়ে আমরা তাঁর সাথে বাইরে বের হচ্ছি। মানুষ জানে যে এটা বহন করবে। লড়াই শুরু।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِلْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏رُمْحٌ فَكُنَّا ‏ ‏إِذَا خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ خَرَجَ بِهِ مَعَهُ فَيَرْكُزُهُ فَيَمُرُّ النَّاسُ عَلَيْهِ فَيَحْمِلُونَهُ فَقُلْتُ لَئِنْ أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأُخْبِرَنَّهُ فَقَالَ إِنَّكَ إِنْ فَعَلْتَ لَمْ تَرْفَعْ ‏ ‏ضَالَّةً ‏","","",""],[1208,1208,"","আমরা আমার বাবার কথা বলেছিলাম সে বলেছে সে আমাকে খুন করার চেষ্টা করছে, ৩ সেকেন্ড পরে সে তার আলো পান করে আর সে বলল যে সে ঈশ্বরের অনুগ্রহ পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏تَوَضَّأَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏ثَلَاثًا ثَلَاثًا ثُمَّ شَرِبَ ‏ ‏فَضْلَ ‏ ‏وَضُوئِهِ ثُمَّ قَالَ هَكَذَا ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏","","",""],[1209,1209,"","আমরা একটি দুর্বল ছেলে সম্পর্কে কথা বলেছি, স্বতস্ফূর্তভাবে ২ বছর আগে বাবার বাবাকে খুন করেছি। আমি তাদের খুঁজে পেয়েছি একটা অন্ত্যেষ্টিক্রিয়ার অনুষ্ঠানে যেটা আমার মনে হয় ঈশ্বরের কাছে হতে পারে। আমার নিজের মধ্যে, আমি আপনাদের ভবিষ্যদ্বাণীর জন্য সব খবর দিচ্ছি আমি এর এক চতুর্থাংশ অর্জনের চেষ্টা করছি, সে গোপন ভাবে আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي حَفْصَةَ ‏ ‏قَالَ ‏ ‏بَلَغَنِي عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُلَيْلٍ ‏ ‏فَغَدَوْتُ إِلَيْهِ فَوَجَدْتُهُمْ فِي جَنَازَةٍ ‏ ‏فَحَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُلَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏أُعْطِيَ كُلُّ نَبِيٍّ سَبْعَةَ ‏ ‏نُجَبَاءَ ‏ ‏وَأُعْطِيَ نَبِيُّكُمْ أَرْبَعَةَ عَشَرَ نَجِيبًا مِنْهُمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏وَعَمَّارُ بْنُ يَاسِرٍ ‏","","",""],[1210,1210,"","আমি আমার বাবার সঙ্গে এত গরম সময় কাটানোর কথা বলেছিলাম । ঈশ্বরের কাছে আমরা মিটিং না করার চেষ্টা করছি, চুরি না করা, খুন না করা, কাউকে খুন না করা, কাউকে কেউ বলে আমি কিছু বলিনি যে কি ভুল আছে। আমি বলেছি, লোকটি যা বলেছে তা তার কানে আছে। আর একজন বললো বিষটা বাকি আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ النُّعْمَانِ ‏ ‏قَالَ ‏ ‏وَكَانَ رَجُلَ صِدْقٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَسْتَشْرِفَ ‏ ‏الْعَيْنَ وَالْأُذُنَ وَأَنْ لَا نُضَحِّيَ بِعَوْرَاءَ وَلَا ‏ ‏مُقَابَلَةٍ ‏ ‏وَلَا ‏ ‏مُدَابَرَةٍ ‏ ‏وَلَا ‏ ‏شَرْقَاءَ ‏ ‏وَلَا ‏ ‏خَرْقَاءَ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏فَقُلْتُ ‏ ‏لِأَبِي إِسْحَاقَ ‏ ‏أَذَكَرَ ‏ ‏عَضْبَاءَ ‏ ‏قَالَ لَا قُلْتُ مَا ‏ ‏الْمُقَابَلَةُ ‏ ‏قَالَ ‏ ‏هِيَ الَّتِي يُقْطَعُ طَرَفُ أُذُنِهَا قُلْتُ ‏ ‏فَالْمُدَابَرَةُ ‏ ‏قَالَ الَّتِي يُقْطَعُ مُؤَخَّرُ الْأُذُنِ قُلْتُ مَا ‏ ‏الشَّرْقَاءُ ‏ ‏قَالَ الَّتِي يُشَقُّ أُذُنُهَا قُلْتُ فَمَا ‏ ‏الْخَرْقَاءُ ‏ ‏قَالَ الَّتِي تَخْرِقُ أُذُنَهَا السِّمَةُ ‏","","",""],[1211,1211,"","আমরা আমার ভাইয়ের চেয়েও ভাল, আমাদের ভাই বলে দুই ছেলে, আমার বাবা ঈশ্বরের চেয়ে ভালো। সে আমাকে ঈশ্বরের কাছে প্রার্থনা করতে বলেছে, সে আল্লাহ্‌র উপর পাপ করেছে। তার জন্য প্রার্থনা করে ও মরসিদের জয় করতে বলে তিন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تَحْبِسُوا لُحُومَ ‏ ‏الْأَضَاحِيِّ ‏ ‏بَعْدَ ثَلَاثٍ ‏","","",""],[1212,1212,"","আমরা একটি প্রান্তরে শপথ নিয়ে কথা বলেছি, আমি তার জন্য আমার পরিতৃপ্তিয় বাস করব যে সে বলেছে যে সে যে লজ্জা করবে তাকে ক্ষমা করে দেবে। ঈশ্বর আদেশ দিয়েছেন এবং আত্মসমর্পণ করেছেন। আমি ঈশ্বরের কাছে প্রার্থনা করছি, ঈশ্বর যেন তিনি শপথ করে থাকেন। আমি আমার এই বিষয়টি নিয়ে প্রার্থনা করি, আমি আমার এই বিষয়টি নিয়ে প্রার্থনা করি যে, আমি আমার জীবনের জন্য প্রার্থনা করছি। আমি আমার জীবনের জন্য প্রার্থনা করছি। আমি আমার এই বিষয়টি নিয়ে আমার কাছে প্রার্থনা করছি। আমি যদি আমার মনে করি, আমি সত্যিই করছি, আমি সত্যিই চিন্তা করি, আমি যেন আমার জীবনের জন্য আমার মনের কথা বলি, আমি আমার মনের কথা বলি, আমি যেন আমি আমার সাথে কথা বলি, আমি আমার মনের কথা বলি, আমি আমার মনের কথা বলি, আমি যেন আমি আমার মনের কথা বলি। আমি আমার মনের কথা বলি, আমি আমার মনে রাখি, আমি আমার জীবনের জন্য আমার মনের কথা বলি, আমি যেন আমি আমার ঈশ্বর আমাকে ক্ষমা করে, আমি আমার কাছে ক্ষমা প্রার্থনা করি। (হাততালি) আদেশ করলাম তিন দিনের এক রাত।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَتْ سَلْ ‏ ‏عَلِيًّا ‏ ‏فَهُوَ أَعْلَمُ بِهَذَا مِنِّي هُوَ كَانَ يُسَافِرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ وَلِلْمُسَافِرِ ثَلَاثَةُ أَيَّامٍ وَلَيَالِيهِنَّ ‏","","",""],[1213,1213,"","আমরা ঈশ্বরের কথা বলেছিলাম, আমাদের জয়ের সময় আমি একজন রাজধানীর মানুষ হিসেবে নির্ধারিত ছিলাম। এটা দেখতে শিখল আর সে এটা দিয়ে নরকে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ بَكَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ سُلَيْمَانَ يَعْنِي أَبَا عُمَرَ الْقَارِئَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ زَاذَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ ضَمْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَعَلَّمَ الْقُرْآنَ ‏ ‏فَاسْتَظْهَرَهُ ‏ ‏وَحَفِظَهُ أَدْخَلَهُ اللَّهُ الْجَنَّةَ وَشَفَّعَهُ فِي عَشَرَةٍ مِنْ أَهْلِ بَيْتِهِ كُلُّهُمْ قَدْ وَجَبَتْ لَهُمْ النَّارُ ‏","","",""],[1214,1214,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি, বাবা, কিন্তু বাবা এত ক্লান্ত হয়ে পড়ে। ভালো হয়, আমি এটা করতে চাই। আমি যখন তাকে বলি যে, তিনি আমাকে শাস্তি দিচ্ছেন, তখন আমি তাকে বলি, যেন আমি তাকে বলি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ الْمُحَارِبِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي الْحَسْنَاءِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُضَحِّيَ عَنْهُ بِكَبْشَيْنِ فَأَنَا أُحِبُّ أَنْ أَفْعَلَهُ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ الْمُحَارِبِيُّ ‏ ‏فِي حَدِيثِهِ ضَحَّى عَنْهُ بِكَبْشَيْنِ وَاحِدٌ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْآخَرُ عَنْهُ فَقِيلَ لَهُ فَقَالَ إِنَّهُ أَمَرَنِي فَلَا أَدَعُهُ أَبَدًا ‏","","",""],[1215,1215,"","ডিনারের কথা বলেছিলাম, ঈশ্বর আমার কাছে প্রার্থনা করার পর বললেন যে তিনি শপথ নেবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحْرِزُ بْنُ عَوْنِ بْنِ أَبِي عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاضِيًا فَقَالَ ‏ ‏إِذَا جَاءَكَ الْخَصْمَانِ فَلَا تَقْضِ عَلَى أَحَدِهِمَا حَتَّى تَسْمَعَ مِنْ الْآخَرِ فَإِنَّهُ يَبِينُ لَكَ ‏ ‏الْقَضَاءُ ‏","","",""],[1216,1216,"","আমরা ঈশ্বরের বাবার সাথে আমার কথা বলেছি, কিন্তু আমি আমার ছেলের বিচার করার চেষ্টা করেছি। আমি আমার হৃদয় জয় করেছি । আশীর্বাদ করো, ঈশ্বর তোমার কাছে আসবে। আমি যখন বৃদ্ধ ছিলাম, তখন খারাপ হয়ে গেলাম, আর যখন আমি আমার ক্লাসে কিছু করেছি আর তাদের মধ্যে কিছু বিক্রি করেছি, আমি যা করেছি তা আল্লাহ্‌র কাছে বিক্রি করেছি। ঈশ্বর বলেছিলেন যে, আমার ছেলে যখন শপথ করে, তখন ঈশ্বর তাকে শপথটা গ্রহণ করতে বলেন । আমরা কিছু বিষয় নিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏وَحَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَكِيمٍ الْأَوْدِيُّ ‏ ‏وَحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ الْوَرَكَانِيُّ ‏ ‏وَحَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ يَحْيَى رَحْمَوَيْهِ ‏ ‏وَحَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ زُرَارَةَ الْحَضْرَمِيُّ ‏ ‏وَحَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو الضَّبِّيُّ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَعَثَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏قَاضِيًا فَقُلْتُ تَبْعَثُنِي إِلَى قَوْمٍ وَأَنَا ‏ ‏حَدَثُ ‏ ‏السِّنِّ وَلَا عِلْمَ لِي بِالْقَضَاءِ فَوَضَعَ يَدَهُ عَلَى صَدْرِي فَقَالَ ‏ ‏ثَبَّتَكَ اللَّهُ وَسَدَّدَكَ إِذَا جَاءَكَ الْخَصْمَانِ فَلَا تَقْضِ لِلْأَوَّلِ حَتَّى تَسْمَعَ مِنْ الْآخَرِ فَإِنَّهُ ‏ ‏أَجْدَرُ ‏ ‏أَنْ يَبِينَ لَكَ ‏ ‏الْقَضَاءُ ‏ ‏قَالَ ‏ ‏فَمَا زِلْتُ قَاضِيًا ‏ ‏وَهَذَا لَفْظُ حَدِيثِ ‏ ‏دَاوُدَ بْنِ عَمْرٍو الضَّبِّيِّ ‏ ‏وَبَعْضُهُمْ أَتَمُّ كَلَامًا مِنْ بَعْضٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ لُوَيْنٌ ‏ ‏وَحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَعَثَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاضِيًا إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَذَكَرَ الْحَدِيثَ قَالَ إِنَّ اللَّهَ مُثَبِّتٌ قَلْبَكَ وَهَادٍ فُؤَادَكَ فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏لُوَيْنٌ ‏ ‏وَحَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ مَعْنَاهُ ‏","","",""],[1217,1217,"","আমরা ঈশ্বরের হাতে কথা বলেছিলাম যখন আমরা জায়গা খুঁজে পেতে সক্ষম হয়েছি, আমি দুঃখিত, ছেলের জন্য আমি তার সাথে কিছু একটা করতে ভয় পাচ্ছি। আমি বলছি, আমি বলছি, আমরা আল্লাহ্‌র ক্ষমতা নিয়ে কথা বলেছি। আমি যখন ঐ জায়গাটা খুঁজে পেয়েছি, তখন আমরা এই জায়গাটি খুঁজে পেয়েছি। আমি আমার ছেলে, আমি দুঃখিত। আমি তার সাথে একটা খারাপ কিছু করার জন্য। আমি দুঃখিত। আমি বলতে চাই, আমি আমার কাছে ক্ষমা চাইছি, আমি যদি আমার ছেলে আমাকে ভুল করে দেয়। আমি তার সাথে সাথে একটা কথা বলি, আমি যদি আমার ছেলে হয়, আমি তাকে ভুল করে ফেলি, আমি সত্যিই দুঃখিত। আমি সত্যিই দুঃখিত। আমি জানি, আমি কি তাকে সাহায্য করতে পারি। আমি কি করবো? তুমি সে আমার সাথে যা করেছে তা হল, সে এটা উদ্ধার করতে চায়... ...সে যেভাবে সবকিছু করে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏السَّكَنُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ بْنُ سَوَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَشْوَعَ ‏ ‏عَنْ ‏ ‏حَنَشٍ الْكِنَانِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ بَعَثَ عَامِلَ شُرْطَتِهِ فَقَالَ لَهُ أَتَدْرِي عَلَى مَا أَبْعَثُكَ عَلَى مَا بَعَثَنِي عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَنْحِتَ كُلَّ ‏ ‏يَعْنِي صُورَةً وَأَنْ أُسَوِّيَ كُلَّ قَبْرٍ ‏","","",""],[1218,1218,"","ঈশ্বর আমাকে বলেছিলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং জিজ্ঞেস করেছেন যে, আমি যদি ব্যয় করি, তা হলে তিনি আমাকে সাহায্য করবেন । আপনি প্রথম যে দিন মিথ্যা বলবেন, তা আপনি শুনতে পাবেন আর অন্য জন বলেন, আপনি কেমনভাবে পড়ে যান ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏تَقَاضَى ‏ ‏إِلَيْكَ رَجُلَانِ فَلَا تَقْضِ لِلْأَوَّلِ حَتَّى تَسْمَعَ مَا يَقُولُ الْآخَرُ فَإِنَّكَ سَوْفَ ‏ ‏تَرَى كَيْفَ تَقْضِي ‏","","",""],[1219,1219,"","আমি আমার এই ত্যাগের জন্য আমার পরিতৃপ্তি দেখেছি, যেমনটা আমি বলেছি, এটা আমার ইচ্ছা নয়, আমি ব্যাখ্যা করছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي الْحَسْنَاءِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُضَحِّي بِكَبْشَيْنِ فَقُلْتُ لَهُ مَا هَذَا فَقَالَ ‏ ‏أَوْصَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُضَحِّيَ عَنْهُ ‏","","",""],[1220,1220,"","আমরা ইশ্বরের সাথে কথা বলেছি, উনি আমার সাথে কথা বলেছিলেন, আর বাবা ভেবেছিলেন আমরা একটু সিংহাসনের সামনে বসে আছি। তার মনের কথা বলে, সূর্য কখনো বলে নি আমার যা আছে চলে যেতে হবে বা চলে যেতে হবে, ঈশ্বর তোমার জিহ্বা প্রমাণ করে দিয়েছেন... ...আর সে তোমাকে চুমু দেয়ার হুমকি দিচ্ছে...","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ حَمَّادٍ ‏ ‏عَنْ ‏ ‏أَسْبَاطِ بْنِ نَصْرٍ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ بَعَثَهُ ‏ ‏بِبَرَاءَةٌ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ إِنِّي لَسْتُ ‏ ‏بِاللَّسِنِ ‏ ‏وَلَا بِالْخَطِيبِ قَالَ مَا بُدٌّ أَنْ أَذْهَبَ بِهَا أَنَا أَوْ تَذْهَبَ بِهَا أَنْتَ قَالَ فَإِنْ كَانَ وَلَا بُدَّ فَسَأَذْهَبُ أَنَا قَالَ ‏ ‏فَانْطَلِقْ فَإِنَّ اللَّهَ يُثَبِّتُ لِسَانَكَ ‏ ‏وَيَهْدِي قَلْبَكَ قَالَ ثُمَّ وَضَعَ يَدَهُ عَلَى فَمِهِ ‏","","",""],[1221,1221,"","আমরা একটা বিশেষ আবেগ নিয়ে কথা বলেছি যা আমরা পেয়েছি একটি ছেলে একজন আগন্তুকের নামে খুঁজে পাওয়ার জন্য। ঈশ্বর তার কাছে প্রার্থনা করার জন্য অনুরোধ করেছেন। ঈশ্বর তাদের কবর ও ঘরের মধ্যে ভরে দিয়েছিলেন এবং তাদের সবাইকে একেবারে রঞ্জিত করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏عَاصِمَ بْنَ بَهْدَلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زِرًّا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏شَغَلُونَا عَنْ صَلَاةِ الْوُسْطَى حَتَّى ‏ ‏آبَتِ ‏ ‏الشَّمْسُ مَلَأَ اللَّهُ قُبُورَهُمْ وَبُيُوتَهُمْ وَبُطُونَهُمْ نَارًا ‏","","",""],[1222,1222,"","আমরা একটা নির্দিষ্ট আবেগ নিয়ে কথা বলেছি যা আমাদের আত্মীয়ের মৃতদেহ শোনার কিছু বিপদ নিয়ে এসেছে, ঈশ্বর তাকে আত্মসমর্পণ করেছেন আর তার এজেন্সির কাছে ঈশ্বরের ইচ্ছার কথা বলেছে। এর ফলে, অসফলতা কমে যায়, আর দরদীর শেষ করে ফেলে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَيْهِ وَكَاتِبَهُ ‏ ‏وَالْوَاشِمَةَ ‏ ‏وَالْمُتَوَشِّمَةَ ‏ ‏وَالْمُحِلَّ ‏ ‏وَالْمُحَلَّلَ ‏ ‏لَهُ وَمَانِعَ ‏ ‏الصَّدَقَةِ ‏ ‏وَنَهَى عَنْ ‏ ‏النَّوْحِ ‏","","",""],[1223,1223,"","আমরা একটা নির্দিষ্ট আবেগ নিয়ে কথা বলেছি যা আমরা অনুসন্ধান করেছি। ঈশ্বর বলেছেন, আমার এক ঘন্টা সময় আছে তাকে উদ্ধার করতে আর আল্লাহকে আমার কাছে অনুরোধ করেছেন, তিনি আমার জন্য কাজ করেছেন। ঈশ্বরের কাছে প্রার্থনা করে... ...আমি তার কাছে প্রার্থনা করেছি, আর কামনায় প্রলাপ করতে চাই না, আমি দেখি এর চেয়ে ভালো আর কি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ نُجَيٍّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَتْ لِي سَاعَةٌ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ يَنْفَعُنِي اللَّهُ عَزَّ وَجَلَّ بِمَا شَاءَ أَنْ يَنْفَعَنِي بِهَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ صُورَةٌ وَلَا كَلْبٌ وَلَا ‏ ‏جُنُبٌ ‏ ‏قَالَ فَنَظَرْتُ فَإِذَا ‏ ‏جِرْوٌ ‏ ‏لِلْحَسَنِ بْنِ عَلِيٍّ ‏ ‏تَحْتَ السَّرِيرِ فَأَخْرَجْتُهُ ‏","","",""],[1224,1224,"","আমরা একটা আবেগ নিয়ে কথা বলেছি, আমরা কিছু ভালো কিছুর জন্য চেষ্টা করেছি, সে বলল তার জন্য আমার শেষ প্রার্থনা করা এবং সে রিংটিকে লাইনে রাখার জন্য আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَضَعَ الْخَاتَمَ فِي الْوُسْطَى ‏","","",""],[1225,1225,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যে আমরা আমার ঈশ্বর সম্পর্কে একটা দর্শন পেয়েছি, যে তিনি তার সম্পর্কে শুনেছেন, তার পিপাসার্ত। তিনি তাকে হাত দিতে পেয়েছেন এবং তিনি মিথ্যা বলবেন না। সে আমার কাছে মিথ্যা বলে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَخْطُبُ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْذِبُوا عَلَيَّ فَإِنَّهُ مَنْ يَكْذِبْ عَلَيَّ ‏ ‏يَلِجْ ‏ ‏النَّارَ ‏","","",""],[1226,1226,"","আমরা ঈশ্বরের ক্ষমতা নিয়ে কথা বলেছি, আমাদের সাথে কথা হয়েছে, একবার কথা বলেছি। আমি আমার সাহস শুনেছি যে তিনি আমার কথা শুনবেন। শত শত বছর ধরে কৌতুক আর কানের কথা শুনতে পাবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جُرَيَّ بْنَ كُلَيْبٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏عَضْبَاءِ ‏ ‏الْقَرْنِ وَالْأُذُنِ ‏","","",""],[1227,1227,"","আমরা ঈশ্বরের সাথে আমার বাবার সাথে কথা বলেছি, আর তারপর আমরা কথা বললাম আমরা কতটা সুখী। ঈশ্বরের কাছে বলতে হবে যে তিনি ঈশ্বরের ইচ্ছাই করেছেন এবং তিনি বলেছেন যে তিনি যেন তা করেছেন। উৎসর্গ করা হয়েছে, এবং অনুমতি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏جُرَيِّ بْنِ كُلَيْبٍ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُضَحَّى ‏ ‏بِأَعْضَبِ ‏ ‏الْقَرْنِ وَالْأُذُنِ ‏","","",""],[1228,1228,"","আমার বাবার উত্তম জীবন সম্বন্ধে ঈশ্বরের সঙ্গে কথা বলার জন্য আমি জগতের জীবনের জীবন সম্বন্ধে কথা বলেছিলাম । আমাকে জিজ্ঞেস করতে বলা হয়েছিল, সে আমাকে জিজ্ঞেস করে, সে বলে, আমি তোমার কর্তৃত্ব ও তোমার বিশ্বাস থেকে তোমাকে রক্ষা করছি। তোমার এই সাহস আর তোমার দু'জনের শ্বাস নিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ الْحَجَّاجِ النَّاجِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَمْرٍو الْفَزَارِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي آخِرِ وِتْرِهِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ وَمُعَافَاتِكَ مِنْ عُقُوبَتِكَ وَأَعُوذُ بِكَ مِنْكَ لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ ‏","","",""],[1229,1229,"","আমি যদি যেতে চাই, তাহলে তিনি তোমাকে ঈশ্বর তে যেতে বলেছেন। তোমার বাবা আর তোমার বাবাকে বলতে চাই আমি দুঃখিত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْأَزْدِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ عَبْدِ الْمَلِكِ بْنِ مُسْلِمِ بْنِ سَلَّامٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ ظَبْيَانَ ‏ ‏عَنْ ‏ ‏حُكَيْمِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا أَرَادَ سَفَرًا قَالَ ‏ ‏اللَّهُمَّ بِكَ ‏ ‏أَصُولُ ‏ ‏وَبِكَ ‏ ‏أَحُولُ ‏ ‏وَبِكَ أَسِيرُ ‏","","",""],[1230,1230,"","আমরা ঈশ্বরের সাথে কথা বলেছি, আমরা ঈশ্বরের সাথে কথা বলতে চাই, এমনকি আল্লাহ্‌র সাথে কথা বলতেও তিনি কেন ১০ বার ঈশ্বরের অনুগ্রহে আঘাত করেছেন। বাবা তার জন্য এটা পড়ার জন্য মহান আশীর্বাদ বোধ করছি তিনি আমাকে বলবেন আপনার বাবা তাকে হত্যা করার জন্য তার কাছে বড় হয়েছেন, তিনি এটা পড়ুন এটা পাহাড়ের মধ্যে জয়ের জন্য, আমি তার কাছ থেকে বই নিয়ে চলে গেলাম, সে চলে গেল, সে বলবে, প্রভু, সে এমন কিছু করেছে যা সে বলেছিল কিন্তু আমি তাকে খুন করতে পারব না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُلَيْمَانَ لُوَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ عَشْرُ آيَاتٍ مِنْ ‏ ‏بَرَاءَةٌ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَبَعَثَهُ بِهَا لِيَقْرَأَهَا عَلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏ثُمَّ دَعَانِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي ‏ ‏أَدْرِكْ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَحَيْثُمَا لَحِقْتَهُ فَخُذْ الْكِتَابَ مِنْهُ فَاذْهَبْ بِهِ إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فَاقْرَأْهُ عَلَيْهِمْ فَلَحِقْتُهُ ‏ ‏بِالْجُحْفَةِ ‏ ‏فَأَخَذْتُ الْكِتَابَ مِنْهُ وَرَجَعَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ نَزَلَ فِيَّ شَيْءٌ قَالَ لَا وَلَكِنَّ ‏ ‏جِبْرِيلَ ‏ ‏جَاءَنِي فَقَالَ ‏ ‏لَنْ يُؤَدِّيَ عَنْكَ إِلَّا أَنْتَ أَوْ رَجُلٌ مِنْكَ ‏","","",""],[1231,1231,"","আমরা একটা আবেগ নিয়ে কথা বলেছি... ...যে দুটো কঠিন রীতির কথা... ...সবকিছুকে আরো রোমাঞ্চকর করে তুলেছে, তার কাছে আমার ঈশ্বরের কাছে আছে সে যা করতে চায় তা করতে। এই শহর সবচেয়ে সাম্প্রতিক ঘটনাগুলোর মধ্যে একটা । মানুষ একত্র হবে এটা আশা না যে এটা একটা ভাল মৃত্যু আর ভালো নাম। শান্তি তাকে ঈশ্বরের অভিশাপ দিয়েছে আর মানুষ শুনেছে যে সে তার মেনে নেবে না। ( আদিপুস্তক ১: ২৭) কিন্তু, যিহোবা তাঁর ইচ্ছা মেনে নেননি ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِعَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّ رَسُولَكُمْ كَانَ يَخُصُّكُمْ بِشَيْءٍ دُونَ النَّاسِ عَامَّةً قَالَ مَا خَصَّنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ لَمْ يَخُصَّ بِهِ النَّاسَ إِلَّا بِشَيْءٍ فِي ‏ ‏قِرَابِ ‏ ‏سَيْفِي هَذَا فَأَخْرَجَ صَحِيفَةً فِيهَا شَيْءٌ مِنْ أَسْنَانِ الْإِبِلِ وَفِيهَا أَنَّ ‏ ‏الْمَدِينَةَ ‏ ‏حَرَمٌ ‏ ‏مِنْ بَيْنِ ‏ ‏ثَوْرٍ ‏ ‏إِلَى ‏ ‏عَائِرٍ ‏ ‏مَنْ ‏ ‏أَحْدَثَ ‏ ‏فِيهَا ‏ ‏حَدَثًا ‏ ‏أَوْ ‏ ‏آوَى ‏ ‏مُحْدِثًا ‏ ‏فَإِنَّ عَلَيْهِ لَعْنَةَ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يُقْبَلُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏ ‏وَذِمَّةُ ‏ ‏الْمُسْلِمِينَ وَاحِدَةٌ فَمَنْ ‏ ‏أَخْفَرَ ‏ ‏مُسْلِمًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يُقْبَلُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏ ‏وَمَنْ ‏ ‏تَوَلَّى ‏ ‏مَوْلًى ‏ ‏بِغَيْرِ إِذْنِهِمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يُقْبَلُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏صَرْفٌ ‏ ‏وَلَا ‏ ‏عَدْلٌ ‏","","",""],[1232,1232,"","আমরা আমার ভাইয়ের আবেগ নিয়ে কথা বলেছি, আমরা কিছু সমস্যার কথা বলেছি, ঈশ্বরের কাছে প্রার্থনা করতে হবে যে তিনি বজ্রপাতে জিতবেন। সূর্য কবর দিয়ে ভরে যায়, মৃত্যু আর তাদের মৃত্যু দিয়ে। কবরকে বলা হয় শুনে ফেলে বলা হয়, তারা আগুন, আমি জানি না কি করতে হবে, কি করতে হবে, কি করতে হবে, কি করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ شَكَلٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ يَوْمَ الْأَحْزَابِ ‏ ‏حَبَسُونَا عَنْ صَلَاةِ الْوُسْطَى صَلَاةِ الْعَصْرِ حَتَّى غَرَبَتْ الشَّمْسُ مَلَأَ اللَّهُ قُبُورَهُمْ وَبُيُوتَهُمْ ‏ ‏أَوْ قُبُورَهُمْ وَبُطُونَهُمْ ‏ ‏نَارًا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏مَلَأَ اللَّهُ قُبُورَهُمْ وَبُيُوتَهُمْ ‏ ‏أَوْ قُبُورَهُمْ وَبُطُونَهُمْ ‏ ‏نَارًا لَا أَدْرِي أَفِي الْحَدِيثِ هُوَ أَمْ لَيْسَ فِي الْحَدِيثِ أَشُكُّ فِيهِ ‏","","",""],[1233,1233,"","আমরা ইশ্বরের সাথে কথা বলেছি, আমরা যা করেছি তার থেকে ভালো যাজক হওয়ার জন্য। হয়তো ভগবানের কাছে প্রার্থনা করব, হে প্রভু, যদি আমাদের প্রার্থনা করার জন্য বিশ্বস্ত রাজকুমার হয়। সব পথ না যায়, রিং এর ভালোর জন্য তারা এসেছে, আমি তার চেয়ে ভালো কিছু খুঁজে বের করতে যাচ্ছি। আমার বাবা - মা ঈশ্বরকে রক্ষা করত । মানুষ হিসাবে তার যে মৃত ্ যু হয় , সে ব ্ যক ্ তি থেকে নিবৃত ্ ত থাকে । ঈশ্বর আমাদের কাছে তাঁর কাছে প্রার্থনা করেছেন এবং তিনি বলতে ব্যর্থ হয়েছেন যে, তিনি আসলে তা করেননি । চমৎকার।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ قَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَازِنٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ ‏ ‏انْعَتْ ‏ ‏لَنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صِفْهُ لَنَا فَقَالَ كَانَ ‏ ‏لَيْسَ ‏ ‏بِالذَّاهِبِ ‏ ‏طُولًا وَفَوْقَ ‏ ‏الرَّبْعَةِ ‏ ‏إِذَا جَاءَ مَعَ الْقَوْمِ ‏ ‏غَمَرَهُمْ ‏ ‏أَبْيَضَ شَدِيدَ الْوَضَحِ ضَخْمَ الْهَامَةِ ‏ ‏أَغَرَّ ‏ ‏أَبْلَجَ ‏ ‏هَدِبَ ‏ ‏الْأَشْفَارِ ‏ ‏شَثْنَ ‏ ‏الْكَفَّيْنِ وَالْقَدَمَيْنِ إِذَا مَشَى ‏ ‏يَتَقَلَّعُ ‏ ‏كَأَنَّمَا يَنْحَدِرُ فِي ‏ ‏صَبَبٍ ‏ ‏كَأَنَّ الْعَرَقَ فِي وَجْهِهِ اللُّؤْلُؤُ لَمْ أَرَ قَبْلَهُ وَلَا بَعْدَهُ مِثْلَهُ بِأَبِي وَأُمِّي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ قَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَازِنٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قِيلَ لَهُ ‏ ‏انْعَتْ ‏ ‏لَنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ لَيْسَ ‏ ‏بِالذَّاهِبِ ‏ ‏طُولًا فَذَكَرَ مِثْلَهُ سَوَاءً ‏","","",""],[1234,1234,"","আমরা ঈশ্বরের ব্যাপারে কথা বলেছি, আমরা তোমার সাথে কথা বলেছি। আমার লর্ড বলেছে, তিনি ঈশ্বরের কাছে গিয়েছেন। আমি যদি তাকে কেটে ফেলি, তাহলে আমি সাহায্য করতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دَاوُدَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ عَلَى ‏ ‏الْكَعْبَةِ ‏ ‏أَصْنَامٌ فَذَهَبْتُ لِأَحْمِلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهَا فَلَمْ أَسْتَطِعْ ‏ ‏فَحَمَلَنِي فَجَعَلْتُ أَقْطَعُهَا وَلَوْ شِئْتُ لَنِلْتُ السَّمَاءَ ‏","","",""],[1235,1235,"","আমরা ঈশ্বর সম্বন্ধে কথা বলেছিলাম, যখন আমরা কোনো দেওয়াল সম্বন্ধে কথা বলেছিলাম । তাদের বিজ্ঞান হচ্ছে এমন এক ব্যক্তি, যে হাতের ঈর্ষা করে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ بْنُ سَوَّارٍ ‏ ‏حَدَّثَنِي ‏ ‏نُعَيْمُ بْنُ حَكِيمٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مَرْيَمَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ قَوْمًا ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الْإِسْلَامِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏طُوبَى ‏ ‏لِمَنْ قَتَلَهُمْ وَقَتَلُوهُ عَلَامَتُهُمْ رَجُلٌ ‏ ‏مُخْدَجُ ‏ ‏الْيَدِ ‏","","",""],[1236,1236,"","আমরা ইশ্বরের সাথে কথা বলেছি, আমরা কথা বলেছি, ঈশ্বরের কাছে সন্তুষ্ট থাকার জন্য, আমার বাবা... ...ঈশ্বরকে পড়তে হবে, আর সে তাকে মেরে ফেলবে... সে আমাকে মার খাওয়ার আগ পর্যন্ত যেতে দেয় নি। সে আমাকে ছেড়ে না দিয়ে আমাকে মেরে ফেলে। সে আমাকে তার হাত ধরে ধরে রাখতে চায়। ঈশ্বর হয়তো আমার বাবার সঙ্গে কথা বলেছিলেন কিন্তু আমার বাবার কোনো প্রয়োজন নেই । তাকে শাস্তি দিয়ে, লর্ড তাকে প্রহার করছে, সে এই ঘটনার কথা উল্লেখ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دَاوُدَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ امْرَأَةَ ‏ ‏الْوَلِيدِ بْنِ عُقْبَةَ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏الْوَلِيدَ ‏ ‏يَضْرِبُهَا ‏ ‏وَقَالَ ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏فِي حَدِيثِهِ ‏ ‏تَشْكُوهُ ‏ ‏قَالَ قُولِي لَهُ قَدْ أَجَارَنِي ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏فَلَمْ تَلْبَثْ إِلَّا يَسِيرًا حَتَّى رَجَعَتْ فَقَالَتْ مَا زَادَنِي إِلَّا ضَرْبًا فَأَخَذَ ‏ ‏هُدْبَةً ‏ ‏مِنْ ثَوْبِهِ فَدَفَعَهَا إِلَيْهَا وَقَالَ قُولِي لَهُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَجَارَنِي فَلَمْ تَلْبَثْ إِلَّا يَسِيرًا حَتَّى رَجَعَتْ فَقَالَتْ مَا زَادَنِي إِلَّا ضَرْبًا فَرَفَعَ يَدَيْهِ وَقَالَ ‏ ‏اللَّهُمَّ عَلَيْكَ ‏ ‏الْوَلِيدَ ‏ ‏أَثِمَ ‏ ‏بِي مَرَّتَيْنِ ‏ ‏وَهَذَا لَفْظُ حَدِيثِ ‏ ‏الْقَوَارِيرِيِّ ‏ ‏وَمَعْنَاهُمَا وَاحِدٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو خَيْثَمَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏أَنْبَأَنَا ‏ ‏نُعَيْمُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّ امْرَأَةَ ‏ ‏الْوَلِيدِ بْنِ عُقْبَةَ ‏ ‏جَاءَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَشْتَكِي ‏ ‏الْوَلِيدَ ‏ ‏أَنَّهُ يَضْرِبُهَا ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[1237,1237,"","আমরা কথা বলেছি বাধ্য হতে বাধ্য হয়ে কিছু সমস্যার সম্মুখীন হতে। লর্ড তার জন্য প্রার্থনা করবেন এবং তিনি আত্মসমর্পণ করবেন যে তিনি সূর্য শপথ থেকে কিছু মাংসের সাথে জড়িত ছিলেন। প্রাচীরটি এত দূরের সূর্যকে তাদের কবর এবং তাদের দুঃখ বা দুঃখ দিয়ে পূর্ণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَوْمَ الْأَحْزَابِ عَلَى ‏ ‏فُرْضَةٍ ‏ ‏مِنْ ‏ ‏فُرَضِ ‏ ‏الْخَنْدَقِ ‏ ‏فَقَالَ ‏ ‏شَغَلُونَا عَنْ صَلَاةِ الْوُسْطَى حَتَّى غَرَبَتْ الشَّمْسُ مَلَأَ اللَّهُ قُبُورَهُمْ وَبُيُوتَهُمْ ‏ ‏أَوْ بُطُونَهُمْ وَبُيُوتَهُمْ ‏ ‏نَارًا ‏","","",""],[1238,1238,"","আমরা আমার বাবাকে কৌতুক করার চেষ্টা করেছি। আল্লাহ কি আমার জন্য খুশি হয়েছে? ঈশ্বরকে জিজ্ঞেস করার উদ্দেশ্য কি তার শান্তি ফিরিয়ে আনার জন্য এসেছে এবং তার কাছে কিছু বিশেষ কিছু জমা দিয়েছে? যা কিছু মানুষ জানত না তা ভুল পথে যেতে পারে। ঈশ্বর তার ছেলেকে অভিশাপ দিয়েছেন এবং ঈশ্বর অভিশাপ দিয়েছেন। ঈশ্বর.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ أَبِي بَزَّةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏هَلْ خَصَّكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ فَقَالَ مَا خَصَّنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ لَمْ يَعُمَّ بِهِ النَّاسَ كَافَّةً إِلَّا مَا كَانَ فِي ‏ ‏قِرَابِ ‏ ‏سَيْفِي هَذَا قَالَ فَأَخْرَجَ صَحِيفَةً فِيهَا مَكْتُوبٌ ‏ ‏لَعَنَ اللَّهُ مَنْ ذَبَحَ لِغَيْرِ اللَّهِ لَعَنَ اللَّهُ مَنْ سَرَقَ ‏ ‏مَنَارَ ‏ ‏الْأَرْضِ وَلَعَنَ اللَّهُ مَنْ لَعَنَ وَالِدَهُ وَلَعَنَ اللَّهُ مَنْ ‏ ‏آوَى ‏ ‏مُحْدِثًا ‏","","",""],[1239,1239,"","আমরা কামনার কথা বলেছি যে আমার বাবা ভালো আছেন, ঈশ্বর তাকে তার পালনকর ্ তার কাছে যেতে বলেছেন আমরা কীভাবে সূর্য স্পর্শ না হওয়া পর্যন্ত শক্তি চেয়ে প্রার্থনা করতাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ الْأَحْزَابِ ‏ ‏اللَّهُمَّ امْلَأْ بُيُوتَهُمْ وَقُبُورَهُمْ نَارًا كَمَا شَغَلُونَا عَنْ صَلَاةِ الْوُسْطَى حَتَّى ‏ ‏آبَتْ ‏ ‏الشَّمْسُ ‏","","",""],[1240,1240,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...আমি কতবার শুনেছি, আমার বাবা তার জন্য প্রার্থনা করেছে, আর আমি এক ঘন্টার মধ্যে তার কাছে প্রার্থনা করবো. জলদস্যুরা বলে সে তাকে আঘাত করবে না... ...আর বলবে আমরা কিভাবে তাকে এটা করতে বলেছি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُجَيَّةَ بْنَ عَدِيٍّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَسَأَلَهُ رَجُلٌ عَنْ الْبَقَرَةِ فَقَالَ عَنْ سَبْعَةٍ وَسَأَلَهُ عَنْ الْأَعْرَجِ فَقَالَ إِذَا بَلَغَتْ ‏ ‏الْمَنْسَكَ ‏ ‏وَسُئِلَ عَنْ الْقَرَنِ فَقَالَ لَا يَضُرُّهُ وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَسْتَشْرِفَ ‏ ‏الْعَيْنَ وَالْأُذُنَ ‏","","",""],[1241,1241,"","আমরা একটা জয় করেছি এবং আমাদের দুঃখ প্রকাশ করে আমাদের বাপ্তিস্মের অর্থ ছেড়ে দিয়েছি। ঈশ্বর এটা মানা করেছেন, যখন তারা ভেবেছিল যে হঠাৎ করে তারা এতো অবাক হবে। তুমি অন্যদের সাথে কথা বলতে, যতক্ষণ না তারা মারা যায়, ততক্ষণ পর্যন্ত তারা আমাকে বলেছিল সে আমাকে খুন করেছে. আমার এক তৃতীয়াংশ পৃথিবী তাদের মধ্যে প্রায় অর্ধ ডজন রক্ত ভরতে চেষ্টা করে। ঈশ্বর, যাকে আমি প্রভুর জয় করলাম, সে আমাকে বলতে চাই যে আমি তোমাকে হারাতে রাজি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏حَنَشِ بْنِ الْمُعْتَمِرِ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كَانَ ‏ ‏بِالْيَمَنِ ‏ ‏فَاحْتَفَرُوا ‏ ‏زُبْيَةً ‏ ‏لِلْأَسَدِ فَجَاءَ حَتَّى وَقَعَ فِيهَا رَجُلٌ وَتَعَلَّقَ بِآخَرَ وَتَعَلَّقَ الْآخَرُ بِآخَرَ وَتَعَلَّقَ الْآخَرُ بِآخَرَ حَتَّى صَارُوا أَرْبَعَةً فَجَرَحَهُمْ الْأَسَدُ فِيهَا فَمِنْهُمْ مَنْ مَاتَ فِيهَا وَمِنْهُمْ مَنْ أُخْرِجَ فَمَاتَ قَالَ فَتَنَازَعُوا فِي ذَلِكَ حَتَّى أَخَذُوا السِّلَاحَ قَالَ فَأَتَاهُمْ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ وَيْلَكُمْ تَقْتُلُونَ مِائَتَيْ إِنْسَانٍ فِي شَأْنِ أَرْبَعَةِ أَنَاسِيَّ تَعَالَوْا أَقْضِ بَيْنَكُمْ بِقَضَاءٍ فَإِنْ رَضِيتُمْ بِهِ وَإِلَّا فَارْتَفِعُوا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَقَضَى لِلْأَوَّلِ رُبُعَ ‏ ‏دِيَةٍ ‏ ‏وَلِلثَّانِي ثُلُثَ ‏ ‏دِيَةٍ ‏ ‏وَلِلثَّالِثِ نِصْفَ ‏ ‏دِيَةٍ ‏ ‏وَلِلرَّابِعِ ‏ ‏الدِّيَةَ ‏ ‏كَامِلَةً قَالَ فَرَضِيَ بَعْضُهُمْ وَكَرِهَ بَعْضُهُمْ وَجَعَلَ ‏ ‏الدِّيَةَ ‏ ‏عَلَى قَبَائِلِ الَّذِينَ ازْدَحَمُوا قَالَ فَارْتَفَعُوا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَحْسَبُهُ قَالَ كَانَ مُتَّكِئًا ‏ ‏فَاحْتَبَى ‏ ‏قَالَ ‏ ‏سَأَقْضِي بَيْنَكُمْ بِقَضَاءٍ قَالَ فَأُخْبِرَ أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَضَى بِكَذَا وَكَذَا قَالَ ‏ ‏فَأَمْضَى ‏ ‏قَضَاءَهُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏سَأَقْضِي بَيْنَكُمْ ‏","","",""],[1242,1242,"","আমি যে - কবিদের কথা বলেছি, তাদের মধ্যে একজন আমার সম্বন্ধে কথা বলেছি । আমি তার মক্কেল ছিলাম আর তিনি বলেছিলেন যে, তিনি অতীতে ফিরে আসার পর তিনি আবারও ফিরে এসেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏حَجَّاحُ بْنُ الشَّاعِرِ ‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ ‏ ‏حَدَّثَنِي ‏ ‏نُعَيْمُ بْنُ حَكِيمٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مَرْيَمَ ‏ ‏وَرَجُلٌ مِنْ جُلَسَاءِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏غَدِيرِ خُمٍّ ‏ ‏مَنْ كُنْتُ ‏ ‏مَوْلَاهُ ‏ ‏فَعَلِيٌّ ‏ ‏مَوْلَاهُ ‏ ‏قَالَ ‏ ‏فَزَادَ النَّاسُ بَعْدُ وَالِ مَنْ ‏ ‏وَالَاهُ ‏ ‏وَعَادِ مَنْ عَادَاهُ ‏","","",""],[1243,1243,"","আমরা একটা ছেলের কথা বলেছিলাম কিন্তু আমরা একটা স্বপ্নের বিষয়ে কথা বলেছিলাম । আমরা ঈশ্বরের কাছে প্রার্থনা করতে আদেশ করেছি... ...এবং তাকে শয়তানের কাছে পৌঁছে দিতে চাই.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏سَلَمَةُ بْنُ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏حُجَيَّةَ بْنِ عَدِيٍّ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سُئِلَ عَنْ الْبَقَرَةِ فَقَالَ عَنْ سَبْعَةٍ وَسُئِلَ عَنْ الْمَكْسُورَةِ الْقَرْنِ فَقَالَ لَا بَأْسَ وَسُئِلَ عَنْ الْعَرَجِ فَقَالَ مَا بَلَغَتْ ‏ ‏الْمَنْسَكَ ‏ ‏ثُمَّ قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَسْتَشْرِفَ ‏ ‏الْعَيْنَيْنِ وَالْأُذُنَيْنِ ‏","","",""],[1244,1244,"","আমি যখন তাদের সঙ্গে কথা বলি, তখন আমি তাদের সঙ্গে কথা বলি । শিল্পী যা বলেছেন, তা ঠিক, বাবা, তুমি যা বলবে, ঈশ্বর, আমরা মারা যাব না। আপনি তো বলেছিলেন, ওসিরা যা বলেছে, তা সবই বলার আছে। আর তারপর আমি তোমাকে মারতে ভয় পাই, সে ছিল ঈশ্বরের অনুগ্রহের কন্যা, ঈশ্বর তাকে শিখিয়েছিলেন আর আমার সবচেয়ে মূল্যবান হাত থেকে সে জন্ম নিয়েছে তিনি বলেছিলেন, ঈশ্বর যেন তা করতে বলেন । সে আমাকে বলে যে, ঈশ্বর তার কাছে ক্ষমা প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করেছেন এবং তার দাসদের উদ্ধার করেছেন এবং তাকে আর হত্যা করা হয়নি। আমি চাই আপনি মারা যান নি। তোমার জন্য কি ভালো, যে তোমার পালক দিয়ে চলে গেছে, তিন বার, আর দু বার। সে তাকে ২ বার বলে যে, সে ঈশ্বর এবং তাঁর নির্দেশনাতে সন্তুষ্ট ছিল। আমার মতো দুইবার।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏الْعَبَّاسُ بْنُ الْوَلِيدِ النَّرْسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْوَرْدِ ‏ ‏عَنِ ‏ ‏ابْنِ أَعْبُدَ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا ‏ ‏ابْنَ أَعْبُدَ ‏ ‏هَلْ تَدْرِي مَا حَقُّ الطَّعَامِ قَالَ قُلْتُ وَمَا حَقُّهُ يَا ‏ ‏ابْنَ أَبِي طَالِبٍ ‏ ‏قَالَ تَقُولُ بِسْمِ اللَّهِ اللَّهُمَّ بَارِكْ لَنَا فِيمَا رَزَقْتَنَا قَالَ ‏ ‏وَتَدْرِي مَا شُكْرُهُ إِذَا فَرَغْتَ قَالَ قُلْتُ وَمَا شُكْرُهُ قَالَ تَقُولُ الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا ثُمَّ قَالَ أَلَا أُخْبِرُكَ عَنِّي وَعَنْ ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏كَانَتْ ابْنَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ مِنْ أَكْرَمِ أَهْلِهِ عَلَيْهِ وَكَانَتْ زَوْجَتِي ‏ ‏فَجَرَتْ ‏ ‏بِالرَّحَى ‏ ‏حَتَّى ‏ ‏أَثَّرَ ‏ ‏الرَّحَى ‏ ‏بِيَدِهَا وَأَسْقَتْ بِالْقِرْبَةِ حَتَّى أَثَّرَتْ ‏ ‏الْقِرْبَةُ ‏ ‏بِنَحْرِهَا ‏ ‏وَقَمَّتْ ‏ ‏الْبَيْتَ حَتَّى اغْبَرَّتْ ثِيَابُهَا وَأَوْقَدَتْ تَحْتَ الْقِدْرِ حَتَّى ‏ ‏دَنِسَتْ ‏ ‏ثِيَابُهَا فَأَصَابَهَا مِنْ ذَلِكَ ضَرَرٌ فَقُدِمَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَبْيٍ ‏ ‏أَوْ خَدَمٍ ‏ ‏قَالَ فَقُلْتُ لَهَا انْطَلِقِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْأَلِيهِ خَادِمًا ‏ ‏يَقِيكِ ‏ ‏حَرَّ ‏ ‏مَا أَنْتِ فِيهِ فَانْطَلَقَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدَتْ عِنْدَهُ خَدَمًا ‏ ‏أَوْ خُدَّامًا ‏ ‏فَرَجَعَتْ وَلَمْ تَسْأَلْهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ أَلَا أَدُلُّكِ عَلَى مَا هُوَ خَيْرٌ لَكِ مِنْ خَادِمٍ ‏ ‏إِذَا أَوَيْتِ إِلَى فِرَاشِكِ سَبِّحِي ثَلَاثًا وَثَلَاثِينَ وَاحْمَدِي ثَلَاثًا وَثَلَاثِينَ وَكَبِّرِي أَرْبَعًا وَثَلَاثِينَ قَالَ فَأَخْرَجَتْ رَأْسَهَا فَقَالَتْ رَضِيتُ عَنْ اللَّهِ وَرَسُولِهِ مَرَّتَيْنِ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏ابْنِ عُلَيَّةَ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏أَوْ ‏ ‏نَحْوَهُ ‏","","",""],[1245,1245,"","সেই সময়ে আমরা তাদের সঙ্গে সেই সময় কাটানোর জন্য কথা বলেছিলাম । তাদের কাছে যখন তারা তাদের কবর ভর্তি করে অথবা তাদের নিজেদের রক্ত দিয়ে ভর্তি করে, তখন আমি প্রার্থনা করছি চোর প্রার্থনা করে","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏قَالَ ‏ ‏كُنَّا نَرَى أَنَّ صَلَاةَ الْوُسْطَى صَلَاةُ الصُّبْحِ قَالَ فَحَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُمْ يَوْمَ الْأَحْزَابِ اقْتَتَلُوا وَحَبَسُونَا عَنْ صَلَاةِ الْعَصْرِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ امْلَأْ قُبُورَهُمْ نَارًا ‏ ‏أَوْ امْلَأْ بُطُونَهُمْ نَارًا ‏ ‏كَمَا حَبَسُونَا عَنْ صَلَاةِ الْوُسْطَى قَالَ فَعَرَفْنَا يَوْمَئِذٍ أَنَّ صَلَاةَ الْوُسْطَى صَلَاةُ الْعَصْرِ ‏","","",""],[1246,1246,"","আমরা কথা বলেছি, কিভাবে আমি তার থেকে ভালো কিছু করতে বলেছিলাম। আমি প্রভু এর জন্য প্রার্থনা করেন এবং তার কাছে প্রার্থনা করেন, আমি তাকে আদেশ করছি তার উপর ভরসা রাখার জন্য। আমি তাকে আদেশ দিচ্ছি, যেন আমি তার উপর আস্থা রাখি। আমি আমার বিশ্বাস রাখতে পারি। আমি আমার জীবনের সব কিছু নিয়ে কথা বলি, আমি জানি, আমি জানি, আমি তোমার কাছে এর জন্য, আমি আমার প্রার্থনা করছি। আমি আমার কাছে এটা একটা সহজ এবং আমার কাছে ক্ষমা প্রার্থনা করি। আমি আমার কাছে এর চেয়ে অনেক বেশি গুরুত্বপূর্ণ। আমি চাই। আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি তোমার কাছে এটা একটা জিনিস আছে। আমি তোমার জন্য। আমি কি করি? আমি তোমার কাছে এটা একটা ভাল উপায় আছে? আমি কি না? আমি জানি না? আমি কি করি? আমি জানি না যে, আমি এটা আমার বাবা-মাজিকতালি। আমি কি করে না? আমি এটা করতে পারি? আমি কি করে না? আমি জানি না? মহিলা.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ إِلَيْهِ ‏ ‏حُلَّةً ‏ ‏سِيَرَاءَ ‏ ‏فَلَبِسَهَا وَخَرَجَ عَلَى الْقَوْمِ فَعَرَفَ الْغَضَبَ فِي وَجْهِهِ ‏ ‏فَأَمَرَهُ أَنْ يُشَقِّقَهَا بَيْنَ نِسَائِهِ ‏","","",""],[1247,1247,"","আমরা কথা বলেছিলাম আপনি একবার রা'র পরিবারের উচ্ছেদের কথা শুনেছেন, সে দিন তিনি মানুষের দেয়ালে ফিরে আসেন যখন তিনি সবচেয়ে বড় মানুষ ছিলেন। পানি চলে গেছে, সে তাকে দেখেছে আর তারপর সে নিজের শপথ নিয়েছে আর বলেছে যে সে তার প্রাণ হারিয়েছে। ঈশ্বর সেটা করেছেন আর এটা সে করবে আর যে এটা করে নি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النَّزَّالَ بْنَ سَبْرَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏صَلَّى الظُّهْرَ ثُمَّ قَعَدَ لِحَوَائِجِ النَّاسِ فَلَمَّا حَضَرَتْ الْعَصْرُ ‏ ‏أُتِيَ ‏ ‏بِتَوْرٍ ‏ ‏مِنْ مَاءٍ فَأَخَذَ مِنْهُ كَفًّا فَمَسَحَ وَجْهَهُ وَذِرَاعَيْهِ وَرَأْسَهُ وَرِجْلَيْهِ ثُمَّ أَخَذَ ‏ ‏فَضْلَهُ ‏ ‏فَشَرِبَ قَائِمًا وَقَالَ إِنَّ نَاسًا يَكْرَهُونَ هَذَا وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ وَهَذَا وُضُوءُ مَنْ لَمْ ‏ ‏يُحْدِثْ ‏","","",""],[1248,1248,"","আমরা একজন দাসীর কথা বলেছিলাম যার আমাকে থাকার জন্য দোষ দেয়া হয়নি। তারপর তাকে এটা দেওয়া হয়নি। সে তাকে ঈশ্বরের বই নিয়ে এসেছে এবং তাকে বছরের মধ্যে হেঁটেছে। ঈশ্বরের দয়া।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لِشَرَاحَةَ ‏ ‏لَعَلَّكِ اسْتُكْرِهْتِ لَعَلَّ زَوْجَكِ أَتَاكِ لَعَلَّكِ قَالَتْ لَا فَلَمَّا وَضَعَتْ جَلَدَهَا ثُمَّ ‏ ‏رَجَمَهَا ‏ ‏فَقِيلَ لَهُ لِمَ جَلَدْتَهَا ثُمَّ رَجَمْتَهَا قَالَ ‏ ‏جَلَدْتُهَا بِكِتَابِ اللَّهِ وَرَجَمْتُهَا بِسُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1249,1249,"","ঈশ্বরের অনুগ্রহ লাভ করার দ্বারা আমাদের একজন অতিথিকে রক্ষা করা হয়েছে । যিনি শিক ্ ষা দিয়েছেন উপদেশ ও যাতে তাঁকে শিক ্ ষা দেন ,","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ فُضَيْلُ بْنُ الْحُسَيْنِ ‏ ‏وَحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدِ بْنِ حِسَابٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خِيَارُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ ‏","","",""],[1250,1250,"","আমার বাবা আমার বাবার আনুগত্যের উপর শাসন করেছেন। আমার বাবা এমন একজন মানুষ যিনি তার জীবন হারিয়েছে। আমি আমার ফোন করেছি। আমি জানি কে, আমি আল্লাহ্‌র কথা বলেছি। আমি জানি, আমার বাবা আল্লাহ্‌র কথা যখন কথা বলেছি, আমার বাবার কাছে এটা নিয়ে কথা বলেছি, আমার বাবার কাছে এমন একজন লোক আছে যে তার জীবন হারিয়েছে। আমি জানি, আমি জানি, আমি জানি, আমি কে সে জানে। আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি। আমি, আমি আত্মসমর্পণ করতে চাই যদি তোমার এত ভালো ইচ্ছা থাকে... ...সে বলল যে আমি তোমার কাছে তোমার অনুগ্রহ গচ্ছিত করছি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏سَيَّارٍ أَبِي الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَجُلٌ فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ إِنِّي عَجَزْتُ عَنْ ‏ ‏مُكَاتَبَتِي ‏ ‏فَأَعِنِّي فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَا أُعَلِّمُكَ كَلِمَاتٍ ‏ ‏عَلَّمَنِيهِنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ عَلَيْكَ مِثْلُ جَبَلِ ‏ ‏صِيرٍ ‏ ‏دَنَانِيرَ لَأَدَّاهُ اللَّهُ عَنْكَ قُلْتُ بَلَى قَالَ قُلْ ‏ ‏اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ ‏","","",""],[1251,1251,"","আমরা ঈশ্বরের সঙ্গে কথা বলেছিলাম, আমার বাবার একজন আরোগ্যকারী হিসেবে এবং তিনি আমার বাবার জন্মের বিষয়ে ক্লান্ত ছিলেন । লর্ডের প্রার্থনা জয় করুন, ঈশ্বর আমার মাকে তার ক্রিস্টালে আশীর্বাদ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏وَمُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏وَرَوْحُ بْنُ عَبْدِ الْمُؤْمِنِ الْمُقْرِئُ ‏ ‏وَحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدِ بْنِ حِسَابٍ ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏","","",""],[1252,1252,"","বাবা একজন মাউস, যিনি আমার বাবার সঙ্গে কথা বলেছিলেন, তিনি হলেন ঈশ্বরের দ্বারা আমার বাবার সঙ্গে তার সম্পর্ক । যারা লোক নয় , তারা সবাই ই তো সবচে ্ ঘকাল । এরা তারাই যারা... ...যারা এই তারা... ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তাদের কাছে প্রার্থনা করেছেন, আমাকে হুমকি দিয়েছেন এবং আমাকে লর্ডের কাছে স্মরণ করিয়ে দিন, আপনাকে আমার আংটির মধ্যে আমার বাবা হতে হবে আমার মনে হয় বাবার বাবাই হচ্ছেন সেই ব্যক্তি যে কিনা তার মনগড়ামি করেছে। আর যাজক বলেন যে, এই ওষুধটা তাকে করতে বাধ্য করবে। আমি যে - ছেলেদের দেখি, তারা ছিল সেই ছেলে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بُرْدَةَ بْنُ أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏أَبِي مُوسَى ‏ ‏فَأَتَانَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَامَ عَلَى ‏ ‏أَبِي مُوسَى ‏ ‏فَأَمَرَهُ بِأَمْرٍ مِنْ أَمْرِ النَّاسِ قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ ‏ ‏اللَّهُمَّ اهْدِنِي ‏ ‏وَسَدِّدْنِي ‏ ‏وَاذْكُرْ بِالْهُدَى هِدَايَتَكَ الطَّرِيقَ وَاذْكُرْ بِالسَّدَادِ ‏ ‏تَسْدِيدَ ‏ ‏السَّهْمِ ‏ ‏وَنَهَانِي أَنْ أَجْعَلَ خَاتَمِي فِي هَذِهِ وَأَهْوَى ‏ ‏أَبُو بُرْدَةَ ‏ ‏إِلَى السَّبَّابَةِ ‏ ‏أَوْ الْوُسْطَى ‏ ‏قَالَ ‏ ‏عَاصِمٌ ‏ ‏أَنَا الَّذِي اشْتَبَهَ عَلَيَّ أَيَّتَهُمَا عَنَى ‏ ‏وَنَهَانِي عَنْ ‏ ‏الْمِيثَرَةِ ‏ ‏وَالْقَسِّيَّةِ ‏ ‏قَالَ ‏ ‏أَبُو بُرْدَةَ ‏ ‏فَقُلْتُ لِأَمِيرِ الْمُؤْمِنِينَ مَا ‏ ‏الْمِيثَرَةُ ‏ ‏وَمَا ‏ ‏الْقَسِّيَّةُ ‏ ‏قَالَ ‏ ‏أَمَّا ‏ ‏الْمِيثَرَةُ ‏ ‏شَيْءٌ كَانَتْ تَصْنَعُهُ النِّسَاءُ لِبُعُولَتِهِنَّ يَجْعَلُونَهُ عَلَى ‏ ‏رِحَالِهِمْ ‏ ‏وَأَمَّا ‏ ‏الْقَسِّيُّ ‏ ‏فَثِيَابٌ كَانَتْ تَأْتِينَا مِنْ ‏ ‏الشَّامِ ‏ ‏أَوْ ‏ ‏الْيَمَنِ ‏ ‏شَكَّ ‏ ‏عَاصِمٌ ‏ ‏فِيهَا حَرِيرٌ فِيهَا أَمْثَالُ ‏ ‏الْأُتْرُجِّ ‏ ‏قَالَ ‏ ‏أَبُو بُرْدَةَ ‏ ‏فَلَمَّا رَأَيْتُ ‏ ‏السَّبَنِيَّ عَرَفْتُ أَنَّهَا هِيَ ‏","","",""],[1253,1253,"","আমরা ইশ্বরের সাথে কথা বলেছি, আমরা তার সাথে কথা বলেছি। আমি একটা সুখী ছেলের অভিশাপ ব্যবহার করতে পারি। আমি এটার জন্য ঈশ্বরের দয়া চাই, আমি কিছু রঙ পরে আসবো... ... যাতে তুমি বিখ্যাত ছিলে...","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمِنْهَالِ ‏ ‏أَخُو ‏ ‏حَجَّاجٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ ‏ ‏لِعَلِيٍّ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ أَيُّ شَهْرٍ تَأْمُرُنِي أَنْ أَصُومَ بَعْدَ رَمَضَانَ فَقَالَ مَا سَمِعْتُ أَحَدًا سَأَلَ عَنْ هَذَا بَعْدَ رَجُلٍ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ شَهْرٍ تَأْمُرُنِي أَنْ أَصُومَ بَعْدَ رَمَضَانَ فَقَالَ ‏ ‏إِنْ كُنْتَ صَائِمًا شَهْرًا بَعْدَ رَمَضَانَ فَصُمْ الْمُحَرَّمَ فَإِنَّهُ شَهْرُ اللَّهِ وَفِيهِ يَوْمٌ تَابَ عَلَى قَوْمٍ وَيَتُوبُ فِيهِ عَلَى قَوْمٍ ‏","","",""],[1254,1254,"","আমরা যমজদের ব্যাপারে কথা বলেছি, আমি এর জন্য আমার ভালবাসা ত্যাগ করতে ক্লান্ত, সে বলল ঈশ্বর তার কাছে প্রার্থনা করুক আর তোমার মাকে তার গর্বে আশীর্বাদ করুক।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عَبْدِ الْمُؤْمِنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏و حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏","","",""],[1255,1255,"","আমরা বাবার অমরত্বের হার নিয়ে কথা বলেছিলাম, সে আমার উপর ঝুলিয়ে রেখেছে, তার কাছে কিছুটা গন্ধ আছে, আমরা রান্নার জন্য মজা করছি, ফক্স তার হাত কেটে দিয়েছে তিন সেকেন্ড পরে সে তার হাত তিন ফুট বালতির মধ্যে চেপে ধরে, তারপর তিন সেকেন্ড মুখ ধুয়ে, তারপর সে তার ডান হাত তুলে নেয় এবং তারপর সে তার ডান হাত তুলে নেয়। একটা হাত তাকে দিয়ে সে তার ডান পা ধুইয়ে দিল আর সে তাকে ঘুমের মধ্যে নিয়ে আসল আর সে বলল যে সে স্বপ্ন তৈরি করতে গোপন ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أُرَاهُ ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَدْ صَلَّى فَدَعَا بِطَهُورٍ فَقُلْنَا مَا يَصْنَعُ ‏ ‏بِالطَّهُورِ ‏ ‏وَقَدْ صَلَّى مَا يُرِيدُ إِلَّا أَنْ يُعَلِّمَنَا فَأُتِيَ ‏ ‏بِطَسْتٍ ‏ ‏وَإِنَاءٍ ‏ ‏فَرَفَعَ الْإِنَاءَ فَصَبَّ عَلَى يَدِهِ فَغَسَلَهَا ثَلَاثًا ثُمَّ غَمَسَ يَدَهُ فِي الْإِنَاءِ فَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا ثُمَّ تَمَضْمَضَ ‏ ‏وَتَنَثَّرَ ‏ ‏مِنْ الْكَفِّ الَّذِي أَخَذَ مِنْهُ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ يَدَهُ الْيُمْنَى ثَلَاثًا وَيَدَهُ الشِّمَالَ ثَلَاثًا ثُمَّ جَعَلَ يَدَهُ فِي الْمَاءِ فَمَسَحَ بِرَأْسِهِ مَرَّةً وَاحِدَةً ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى ثَلَاثًا وَرِجْلَهُ الشِّمَالَ ثَلَاثًا ثُمَّ قَالَ مَنْ سَرَّهُ أَنْ يَعْلَمَ طُهُورَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهُوَ هَذَا ‏","","",""],[1256,1256,"","আমি তার মাংস এবং তার মানুষ এবং তার কাছে প্রার্থনা করি, আমি তার কাছে প্রার্থনা করি যেন তিনি ঈশ্বরের কাছে আমার সন্তুষ্ট হন। আমি ঈশ্বরের কাছে প্রার্থনা করি যেন তিনি আমাকে উদ্ধার করেন । আমরা তাকে দিচ্ছি","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏أَنْبَأَنَا ‏ ‏زُهَيْرُ بْنُ مُعَاوِيَةَ أَبُو خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَقُومَ عَلَى ‏ ‏بُدْنِهِ ‏ ‏وَأَنْ أَتَصَدَّقَ بِلُحُومِهَا وَجُلُودِهَا وَأَجِلَّتِهَا وَأَنْ لَا أُعْطِيَ الْجَازِرَ مِنْهَا قَالَ نَحْنُ ‏ ‏نُعْطِيهِ مِنْ عِنْدِنَا ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ هَذَا إِلَّا أَنَّهُ لَمْ يَقُلْ نَحْنُ ‏ ‏نُعْطِيهِ مِنْ عِنْدِنَا ‏","","",""],[1257,1257,"","বাবার হাতে আমাদের বাবার কিছু শান্তি নিয়ে কথা বলেছিলাম, তাকে ঈশ্বরের ইচ্ছা জানতে হবে আর তিনি ঈশ্বরকে ভালবাসতে পারবেন। সে সূর্য মিস করে নাই কিংবা বলেছিল, সবকিছু সে ছুঁয়ে না যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَنْبَأَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ السَّلْمَانِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ الْأَحْزَابِ ‏ ‏مَلَأَ اللَّهُ بُيُوتَهُمْ وَقُبُورَهُمْ نَارًا كَمَا حَبَسُونَا عَنْ الصَّلَاةِ الْوُسْطَى حَتَّى غَابَتْ الشَّمْسُ ‏ ‏أَوْ قَالَ حَتَّى ‏ ‏آبَتْ ‏ ‏الشَّمْسُ إِحْدَى الْكَلِمَتَيْنِ ‏","","",""],[1258,1258,"","আমি তার জীবন দিয়ে ওকে শেষ করে দিয়েছি। হাত, তারা ফিরে আসছে, আমরা চাই ঈশ্বর তার কৃত কথা শুনতে তিনি বলেছিলেন আপনি ঈশ্বরের দয়া এবং শান্তি শুনতে বলা হয়েছে. তিনি এই sphuting হবে. তিনি হবে. তিনি হবে. এবং তিনি হবে. তিনি হবে. এমনকি তার প্রতি ভালবাসাও বাড়িয়ে সে এটা করেছে, সে এসে বলল সে জানে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ الْجَنْبِيِّ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أُتِيَ بِامْرَأَةٍ قَدْ زَنَتْ فَأَمَرَ بِرَجْمِهَا فَذَهَبُوا بِهَا لِيَرْجُمُوهَا فَلَقِيَهُمْ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ مَا هَذِهِ قَالُوا زَنَتْ فَأَمَرَ ‏ ‏عُمَرُ ‏ ‏بِرَجْمِهَا فَانْتَزَعَهَا ‏ ‏عَلِيٌّ ‏ ‏مِنْ أَيْدِيهِمْ وَرَدَّهُمْ فَرَجَعُوا إِلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ مَا رَدَّكُمْ قَالُوا رَدَّنَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ مَا فَعَلَ هَذَا ‏ ‏عَلِيٌّ ‏ ‏إِلَّا لِشَيْءٍ قَدْ عَلِمَهُ فَأَرْسَلَ إِلَى ‏ ‏عَلِيٍّ ‏ ‏فَجَاءَ وَهُوَ شِبْهُ الْمُغْضَبِ فَقَالَ مَا لَكَ رَدَدْتَ هَؤُلَاءِ قَالَ أَمَا سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ عَنْ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنْ الصَّغِيرِ حَتَّى يَكْبَرَ وَعَنْ الْمُبْتَلَى حَتَّى يَعْقِلَ قَالَ بَلَى قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَإِنَّ هَذِهِ مُبْتَلَاةُ بَنِي فُلَانٍ فَلَعَلَّهُ أَتَاهَا وَهُوَ بِهَا فَقَالَ ‏ ‏عُمَرُ ‏ ‏لَا أَدْرِي قَالَ وَأَنَا لَا أَدْرِي فَلَمْ يَرْجُمْهَا ‏","","",""],[1259,1259,"","আমরা একটা মেয়ের কথা বলেছিলাম, যিনি কয়েকভাবে সাঁতার কাটতে গিয়ে তার সবচেয়ে ভাল ছেলের কথা বলেছিলেন । তার কাছে এবং তার জন্য ঈশ্বর আপনার মাকে তার গর্বে আশীর্বাদ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏و حَدَّثَنِي ‏ ‏رَوْحُ بْنُ عَبْدِ الْمُؤْمِنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏","","",""],[1260,1260,"","আমরা ঈশ্বরের হাতে কথা বলেছি যে আমরা একজন জেডিকে খুঁজে পেয়েছি। আমি আমার বাবার কাছে কৃতজ্ঞ হতে পারি যে তার জন্য ঈশ্বরের কাছে প্রার্থনা করেছে। আমি কোরআন পড়েছি এবং সে একজন মানুষ। আমি একটি ছেলে যে কিনা তার বাবার কাছে প্রার্থনা করেছি, সে ছিল আমার বাবা। আমি তাকে একটা প্রশ্ন করি, আমি তাকে খুঁজে পেয়েছি। আমি আমার বাবার কাছে প্রার্থনা করছি, আমি তাকে খুঁজে পেয়েছি। আমি আমার বাবার কাছে প্রার্থনা করছি, আমি তাকে খুঁজে পেয়েছি। লঙ্কার বলছে তুমি যদি ফিরে যাও তাহলে আমি তোমাকে খুঁজে বের করব.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَفَعَهُ أَنَّهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَقْرَأَ الْقُرْآنَ وَهُوَ رَاكِعٌ وَقَالَ إِذَا رَكَعْتُمْ فَعَظِّمُوا اللَّهَ وَإِذَا سَجَدْتُمْ فَادْعُوا ‏ ‏فَقَمِنٌ ‏ ‏أَنْ يُسْتَجَابَ لَكُمْ ‏","","",""],[1261,1261,"","আমরা আমার বাবার কথা বলেছিলাম, একজন রক্ষকের ছেলে যে তোমাকে কখনো বলেনি আমরা কিছু সময় পাঠ করার চেষ্টা করেছি আর শিখেছি যে তোমাকে ঈশ্বরের কাছে যেতে হবে না। সে বলবে তুমি এটা বলবে তার কাছ থেকে \"আমি\" আর হয়তো তুমি 'আমি' খেললে আর \"আমি তোমাকে ভালবাসি\" তাদের মধ্যে হয়তো এমন একজন যে কারো হাতে হাত বা হাত ধরে হাত দিতে চাচ্ছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبِيدَةُ ‏ ‏لَا أُحَدِّثُكَ إِلَّا مَا سَمِعْتُ مِنْهُ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فَحَلَفَ لَنَا ‏ ‏عَبِيدَةُ ‏ ‏ثَلَاثَ مِرَارٍ وَحَلَفَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏لَوْلَا أَنْ ‏ ‏تَبْطَرُوا ‏ ‏لَنَبَّأْتُكُمْ مَا وَعَدَ اللَّهُ الَّذِينَ يَقْتُلُونَهُمْ عَنْ لِسَانِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ ‏ ‏آنْتَ سَمِعْتَهُ مِنْهُ قَالَ إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏إِي وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏فِيهِمْ رَجُلٌ ‏ ‏مُخْدَجُ ‏ ‏الْيَدِ ‏ ‏أَوْ ‏ ‏مَثْدُونُ ‏ ‏الْيَدِ أَحْسَبُهُ قَالَ أَوْ ‏ ‏مُودَنُ ‏ ‏الْيَدِ ‏","","",""],[1262,1262,"","ঈশ্বর প্রভুর সঙ্গে আমার জন্য আশীর্বাদ নিয়ে আসেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مَعْمَرٍ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏","","",""],[1263,1263,"","আমি আমার দুঃখকে নিয়ে ঠাট্টা করতাম । বুদ্ধি খাটাও এবং জাদু না মানলে তারা তাকে দিয়ে ওই অপরাধ দ্বার দিয়ে হামলা করতে নিয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏النُّعْمَانُ بْنُ سَعْدٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَرَأَ هَذِهِ الْآيَةَ ‏ { ‏يَوْمَ نَحْشُرُ الْمُتَّقِينَ إِلَى الرَّحْمَنِ وَفْدًا ‏} ‏قَالَ لَا وَاللَّهِ مَا عَلَى أَرْجُلِهِمْ يُحْشَرُونَ وَلَا يُحْشَرُ الْوَفْدُ عَلَى أَرْجُلِهِمْ وَلَكِنْ ‏ ‏عَلَى ‏ ‏نُوقٍ لَمْ تَرَ الْخَلَائِقُ مِثْلَهَا عَلَيْهَا رَحَائِلُ مِنْ ذَهَبٍ فَيَرْكَبُونَ عَلَيْهَا حَتَّى يَضْرِبُوا أَبْوَابَ الْجَنَّةِ ‏","","",""],[1264,1264,"","আমার বাবা তার মৃত্যুর পর একটা সীল ধরে আছে, আমি তাকে তোমার ছেলেকে বলি নি, যতক্ষণ না সে নরক থেকে বের হয়। আমার বাবা আমাকে জিজ্ঞেস করলো আমি যেন শেষ পর্যন্ত শেষ পর্যন্ত শেষ হয়ে যাই। ওর সাথে কথা বলতে, সে শেষ না হওয়া পর্যন্ত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبَانُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏وَقَفْتُ مَعَ ‏ ‏الْحُسَيْنِ ‏ ‏فَلَمْ أَزَلْ أَسْمَعُهُ يَقُولُ لَبَّيْكَ حَتَّى رَمَى الْجَمْرَةَ فَقُلْتُ يَا ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏مَا هَذَا ‏ ‏الْإِهْلَالُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُهِلُّ ‏ ‏حَتَّى انْتَهَى إِلَى ‏ ‏الْجَمْرَةِ ‏ ‏وَحَدَّثَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهَلَّ حَتَّى انْتَهَى إِلَيْهَا ‏","","",""],[1265,1265,"","আমরা ঈশ্বরের কথা বলেছি, আমি বাবা কেথের কাছ থেকে পালিয়ে এসেছি। লর্ডের দয়ায় প্রার্থনা করেছেন। আমি বলি, তার পরে কয়েক মাস ধরে আমি তাকে ধরে রাখব। ঈশ্বরের অনুগ্রহে তিনি বিখ্যাত, আর তার আনুগত্য এক সময়ে শেষ হয়ে যাবে যখন সে দ্বিতীয় বিশ্বযুদ্ধের সময় মারা যাবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرٌ أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِشَهْرٍ أَصُومُهُ بَعْدَ رَمَضَانَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كُنْتَ صَائِمًا شَهْرًا بَعْدَ رَمَضَانَ فَصُمْ الْمُحَرَّمَ فَإِنَّهُ شَهْرُ اللَّهِ وَفِيهِ يَوْمٌ تَابَ فِيهِ عَلَى قَوْمٍ وَيُتَابُ فِيهِ عَلَى آخَرِينَ ‏","","",""],[1266,1266,"","আমরা তোমাকে ঈশ্বরের স্বপ্নের কথা বলেছি, ঈশ্বর আমাদের গ্রাম থেকে মানুষকে উদ্ধার করতে এসেছেন, আমরা অবশ্যই তোমার প্রতিবেশী এবং বংশধর। ঋণের ইচ্ছা আর হয়তো এটা বুঝতে আগ্রহী না যে তারা আমাদের জীবন হারিয়েছে। তারা বিশ্বাস করে যে তারা আপনার আর আপনার ছাত্র তার চেহারা পরিবর্তন করে, আর সে আমার দিকে মুখ ফিরিয়ে নেবে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَاءَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُنَاسٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالُوا يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّا جِيرَانُكَ وَحُلَفَاؤُكَ وَإِنَّ نَاسًا مِنْ عَبِيدِنَا قَدْ أَتَوْكَ لَيْسَ بِهِمْ رَغْبَةٌ فِي الدِّينِ وَلَا رَغْبَةٌ فِي الْفِقْهِ إِنَّمَا فَرُّوا مِنْ ضِيَاعِنَا وَأَمْوَالِنَا فَارْدُدْهُمْ إِلَيْنَا فَقَالَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا تَقُولُ قَالَ صَدَقُوا إِنَّهُمْ جِيرَانُكَ قَالَ فَتَغَيَّرَ وَجْهُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏لِعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا تَقُولُ قَالَ صَدَقُوا إِنَّهُمْ لَجِيرَانُكَ وَحُلَفَاؤُكَ فَتَغَيَّرَ وَجْهُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1267,1267,"","আমরা ঈশ্বরের সাথে কথা বলেছি, কিন্তু ছয় বছর ধরে আমি সুখী থাকব এবং আমি বলবো যে প্রভুর অনুগ্রহ এবং প্রভু ঈশ্বরের আলোর মধ্যে সাঁতার কাটতে হবে। তিনি বলেছিলেন তিনি ঈশ্বরের কাছে বলেছিলেন। তার জন্য প্রার্থনা করুন এবং তিনি আশ্বস্ত করতেন যে আমি হলে পড়াতাম এবং যারা পৃথিবীতে ছিল তাদের উপস্থিতি এবং যারা এই প্রশ্ন করার চেষ্টা করেছেন। আসলে তুমি তোমার মুখ থেকে উত্তর দিবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏سَنَةَ سِتٍّ وَعِشْرِينَ وَمِائَتَيْنِ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَأَلَهُ رَجُلٌ ‏ ‏آقْرَأُ فِي الرُّكُوعِ وَالسُّجُودِ فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي نُهِيتُ أَنْ أَقْرَأَ فِي الرُّكُوعِ وَالسُّجُودِ فَإِذَا رَكَعْتُمْ فَعَظِّمُوا اللَّهَ وَإِذَا سَجَدْتُمْ فَاجْتَهِدُوا فِي الْمَسْأَلَةِ ‏ ‏فَقَمِنٌ ‏ ‏أَنْ يُسْتَجَابَ لَكُمْ ‏","","",""],[1268,1268,"","আমরা ঈশ্বরের কথা বলেছিলাম, কিন্তু আমি ঈশ্বরের হাতে শাস্তি পাব না, সে তার জন্য প্রার্থনা করার চেয়ে ভাল ছেলে খুঁজছিলো। আর তার দুঃখ থেকে তাকে দেখে আমি তার জন্য রাতের বেলা রান্না করে রেখেছিলাম আর লোকজন ঘুমিয়ে পড়ত ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبَّادُ بْنُ يَعْقُوبَ الْأَسَدِيُّ أَبُو مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ لَغُرَفًا يُرَى بُطُونُهَا مِنْ ظُهُورِهَا وَظُهُورُهَا مِنْ بُطُونِهَا فَقَالَ أَعْرَابِيٌّ يَا رَسُولَ اللَّهِ لِمَنْ هِيَ قَالَ لِمَنْ ‏ ‏أَطَابَ ‏ ‏الْكَلَامَ وَأَطْعَمَ الطَّعَامَ وَصَلَّى لِلَّهِ بِاللَّيْلِ وَالنَّاسُ نِيَامٌ ‏","","",""],[1269,1269,"","একদিন শুরু করার পর থেকে আমি ঈশ্বরের সঙ্গে কথা বলেছিলাম । ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমার মায়ের কাছে আপনার আশীর্বাদ চান ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏رَوْحُ بْنُ عَبْدِ الْمُؤْمِنِ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏و حَدَّثَنِي ‏ ‏عَبَّادُ بْنُ يَعْقُوبَ الْأَسَدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لِأُمَّتِي فِي ‏ ‏بُكُورِهَا ‏","","",""],[1270,1270,"","আমরা একটা স্বপ্নের কথা বলেছিলাম, তিনি কত কিছু করেছেন, তার জন্য আমাদের ঈশ্বরকে খুশি করার নির্দেশ দেয়া হয়েছে যে তিনি চলে গেছেন। আমি জানি তিনি কে আর ঈশ্বর হবেন। আমাকে খুন করেছে বলে সে আমাকে খুন করেছে, তারপর তুমি আমাকে এটা করতে বলো না আর সব করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَبُعٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ وَالَّذِي ‏ ‏فَلَقَ ‏ ‏الْحَبَّةَ ‏ ‏وَبَرَأَ ‏ ‏النَّسَمَةَ ‏ ‏لَتُخْضَبَنَّ هَذِهِ مِنْ هَذِهِ قَالَ قَالَ النَّاسُ فَأَعْلِمْنَا مَنْ هُوَ وَاللَّهِ ‏ ‏لَنُبِيرَنَّ ‏ ‏عِتْرَتَهُ ‏ ‏قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏بِاللَّهِ أَنْ يُقْتَلَ غَيْرُ قَاتِلِي قَالُوا إِنْ كُنْتَ قَدْ عَلِمْتَ ذَلِكَ اسْتَخْلِفْ إِذًا قَالَ لَا وَلَكِنْ أَكِلُكُمْ إِلَى مَا وَكَلَكُمْ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1271,1271,"","আমরা দুটো বিষয় নিয়ে কথা বলেছি যেগুলো ঈশ্বরের প্রতি আমার ভালবাসার অঙ্গীকার করতে হবে। আমরা আমার প্রভুকে পাপ করেছি তার জন্য বলছি, আমি আপনার সর্বোচ্চদের উপর ভরসা করি, আমি আমার মাকে জিজ্ঞাসা করছি। আমি আমার মায়ের কাছে অনুরোধ করছি, আমি আমার জীবনের উপর ভরসা রাখতে। আমি আমার জীবনের সবচেয়ে বড় অংশ হতে পারি। আমি আমার জীবনের উপর ভরসা রাখতে পারি। আমি আমার জীবনের প্রকৃত অর্থ এই বিষয়ে আমার জীবনের উপর ভিত্তি করে। আমি আমার সৃষ্টিকর্তাকে বিশ্বাস করতে হবে। আমি আমার কাছে এটা করতে হবে। আমি আমার সিদ্ধান্ত অনুযায়ী কাজ করতে হবে। আমি আমার কাছে এটা করতে পারি। আমি যদি আমি আমার বাবা-মাকে জিজ্ঞাসা করি, আমি আমার কাছে একটা প্রশ্ন করি। আমি যদি আমার বাবা-মা নেই, আমি আমার মা-মা'র কাছে একটা প্রশ্ন করি। আমি যদি আমার বাবা-মা'র কাছে একটা প্রশ্ন করে, আমি যদি আমার মা না থাকে তবে আমি আমার মা-ই করি, আমি আমার কাছে একটা প্রশ্ন করি। আমি যদি আমার কাছে ফিরে আসি। আমি আমার মা-ই বলি, আমি আমার কাছে একটা প্রশ্ন করি, আমি যদি আমার বাবা-মা'র কথা বলি, আমি যদি আমি আমার মা-কে বলি, আমি আমার কাছে জিজ্ঞেস করি, আমি আমার বাবা-মা-মা। আমি তাকে সাহায্য করবো, তার আছে যে তাকে হারিয়েছে, তাই সে একটা ভয়ঙ্কর আত্মা দিয়ে করেছে, আমি ভয় পাচ্ছি যে সে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَنْبَأَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ يَا أَيُّهَا النَّاسُ أَقِيمُوا عَلَى ‏ ‏أَرِقَّائِكُمْ ‏ ‏الْحُدُودَ ‏ ‏مَنْ ‏ ‏أُحْصِنَ ‏ ‏مِنْهُمْ وَمَنْ لَمْ ‏ ‏يُحْصَنْ ‏ ‏فَإِنَّ أَمَةً لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَنَتْ فَأَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏أُقِيمَ عَلَيْهَا ‏ ‏الْحَدَّ ‏ ‏فَأَتَيْتُهَا فَإِذَا هِيَ حَدِيثُ عَهْدٍ بِنِفَاسٍ فَخَشِيتُ إِنْ أَنَا جَلَدْتُهَا أَنْ تَمُوتَ فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ أَحْسَنْتَ ‏","","",""],[1272,1272,"","আমি আমার বাবাকে বলেছিলাম যে, তিনি একটা ছেলেকে আঘাত করেছেন । তুমি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَقُلْتُ إِنَّكَ تَبْعَثُنِي إِلَى قَوْمٍ وَهُمْ ‏ ‏أَسَنُّ ‏ ‏مِنِّي لِأَقْضِيَ بَيْنَهُمْ فَقَالَ ‏ ‏اذْهَبْ فَإِنَّ اللَّهَ ‏ ‏سَيَهْدِي قَلْبَكَ وَيُثَبِّتُ لِسَانَكَ ‏","","",""],[1273,1273,"","বাবা, আমি ঈশ্বরের সাথে কথা বলেছি, কিন্তু বাবা আমাকে সাহায্য করার চেষ্টা করেছে। আমি দুঃখিত, কে আমরা আমার সাথে কথা বলেছি আমাকে সাহায্য করার চেষ্টা করতে, আমি তার কাছে আমার পরিতৃপ্তি চাই বলতে চাই... সে বলল, যদি লোকটির মধ্যে যাওয়ার একটি ছবি থাকে, সে বলল, \"তাহলে তাকে উজ্জ্বলতম আত্মার সাথে দেখা করতে দাও।\"","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ سُوقًا مَا فِيهَا بَيْعٌ وَلَا شِرَاءٌ إِلَّا الصُّوَرُ مِنْ النِّسَاءِ وَالرِّجَالِ فَإِذَا اشْتَهَى الرَّجُلُ صُورَةً دَخَلَ فِيهَا وَإِنَّ فِيهَا لَمَجْمَعًا لِلْحُورِ الْعِينِ يَرْفَعْنَ أَصْوَاتًا لَمْ يَرَ الْخَلَائِقُ مِثْلَهَا يَقُلْنَ نَحْنُ الْخَالِدَاتُ فَلَا ‏ ‏نَبِيدُ ‏ ‏وَنَحْنُ الرَّاضِيَاتُ فَلَا نَسْخَطُ وَنَحْنُ النَّاعِمَاتُ فَلَا نَبْؤُسُ فَطُوبَى لِمَنْ كَانَ لَنَا وَكُنَّا لَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرٌ أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ سُوقًا فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ فَإِذَا اشْتَهَى الرَّجُلُ صُورَةً دَخَلَهَا قَالَ وَفِيهَا مُجْتَمَعُ الْحُورِ الْعِينِ يَرْفَعْنَ أَصْوَاتًا ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[1274,1274,"","ঈশ্বর আমার সাথে কথা বলেছেন, কিন্তু আমার ছেলে একজন যাজকের সাথে জীবিত আছে, যে ঈশ্বরের কাছে আমার সন্তুষ্ট আছে, আর তারপর সে ভুলে গেছে। তারপর তিনি বলেন, ঈশ্বরের প্রার্থনা ও আত্মসমর্পণের জন্য তার গোপন তথ্য ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبَانَ الْبَلْخِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ ‏ ‏تَوَضَّأَ ثَلَاثًا ثَلَاثًا ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ شَرِبَ ‏ ‏فَضْلَ ‏ ‏وَضُوئِهِ ثُمَّ قَالَ مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْيَنْظُرْ إِلَى هَذَا ‏","","",""],[1275,1275,"","ঈশ্বর ঈশ্বরের কাছে প্রার্থনা করেছেন এবং সেই সময়ের শেষে গরু এর সঙ্গে যেতে সিদ্ধান্ত নেবে । তাহলে এখানের সবকিছু ঠিক আছে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ غَفَلَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ فِي آخِرِ الزَّمَانِ قَوْمٌ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الْإِسْلَامِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏قِتَالُهُمْ حَقٌّ عَلَى كُلِّ مُسْلِمٍ ‏","","",""],[1276,1276,"","আমরা আমাদের অতিথি হয়ে কিভাবে আমার জীবন বাঁচাতে চেষ্টা করেছি সে সম্পর্কে কথা বলেছি। ঈশ্বর আমাদের সব থেকে ভালো কিছু করতে বলেছেন, আমাদের কাছ থেকে আমি এর শক্তি পাই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ الْمُضَرِّبِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا احْمَرَّ ‏ ‏الْبَأْسُ ‏ ‏وَلَقِيَ الْقَوْمُ الْقَوْمَ اتَّقَيْنَا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا يَكُونُ مِنَّا أَحَدٌ ‏ ‏أَدْنَى ‏ ‏مِنْ الْقَوْمِ مِنْهُ ‏","","",""],[1277,1277,"","আমরা দুই বছরের জীবন ধারণের জন্য বেঁচে থাকার জন্য বেঁচে থাকার জন্য বেঁচে থাকার চেষ্টা করেছি, ঈশ্বর আমার কাছে এটা বলার জন্য আমাকে দিয়েছেন যে, সে ঈশ্বরের দোহাই ধরে আছে। আমি তাদের কাছে শপথ করে বলছি, মানুষ অন্ধকার হয়ে যাবে। আর তারপর ডিনার শুরু হয় যখন আমি তখন থেকে। আটকে ছিল এবং এরপর সে মারা গিয়েছিল । এই হচ্ছে সেই মুক্তি যে তার মুক্তির জন্য এবং তারপর সে একটা কাজ পেয়েছে। এমন কিছু যা আমি আল্লাহ্‌কে মুগ্ধ করতে পেরেছি যাতে তার লজ্জা পাওয়া যায়, যাতে তুমি লজ্জিত হতে পারো তোমার জন্য লজ্জিত হতে পারো। মামা, খেলতে হবে, প্রভু, আপনার চাচাতো ভাই তোমাকে কখনোই আলিঙ্গন করতে হয়নি। আমি একজন যুবক এবং প্রেমিক দেখলাম। আমি এমন একজন লোক যে আগে আমি এই কথা বলতে পারতাম না। অথবা যখন কোন ছোট খুন হয়, তখন তোমার ক্ষমতা তোমাকে জয় করতে পারবে না,","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏فَقَالَ ‏ ‏هَذَا الْمَوْقِفُ ‏ ‏وَعَرَفَةُ ‏ ‏كُلُّهَا مَوْقِفٌ ثُمَّ ‏ ‏أَرْدَفَ ‏ ‏أُسَامَةَ ‏ ‏فَجَعَلَ ‏ ‏يُعْنِقُ ‏ ‏عَلَى نَاقَتِهِ وَالنَّاسُ يَضْرِبُونَ الْإِبِلَ يَمِينًا وَشِمَالًا لَا يَلْتَفِتُ إِلَيْهِمْ وَيَقُولُ السَّكِينَةَ أَيُّهَا النَّاسُ وَدَفَعَ حِينَ غَابَتْ الشَّمْسُ فَأَتَى ‏ ‏جَمْعًا ‏ ‏فَصَلَّى بِهَا الصَّلَاتَيْنِ ‏ ‏يَعْنِي الْمَغْرِبَ وَالْعِشَاءَ ‏ ‏ثُمَّ بَاتَ بِهَا فَلَمَّا أَصْبَحَ وَقَفَ عَلَى ‏ ‏قُزَحَ ‏ ‏فَقَالَ هَذَا ‏ ‏قُزَحُ ‏ ‏وَهُوَ الْمَوْقِفُ ‏ ‏وَجَمْعٌ ‏ ‏كُلُّهَا مَوْقِفٌ قَالَ ثُمَّ سَارَ فَلَمَّا أَتَى ‏ ‏مُحَسِّرًا ‏ ‏قَرَعَهَا ‏ ‏فَخَبَّتْ ‏ ‏حَتَّى ‏ ‏جَازَ ‏ ‏الْوَادِيَ ‏ ‏ثُمَّ حَبَسَهَا ‏ ‏وَأَرْدَفَ ‏ ‏الْفَضْلَ ‏ ‏ثُمَّ سَارَ حَتَّى أَتَى ‏ ‏الْجَمْرَةَ ‏ ‏فَرَمَاهَا ثُمَّ أَتَى ‏ ‏الْمَنْحَرَ ‏ ‏فَقَالَ هَذَا ‏ ‏الْمَنْحَرُ ‏ ‏وَمِنًى ‏ ‏كُلُّهَا مَنْحَرٌ ثُمَّ أَتَتْهُ امْرَأَةٌ شَابَّةٌ مِنْ ‏ ‏خَثْعَمَ ‏ ‏فَقَالَتْ إِنَّ أَبِي شَيْخٌ قَدْ ‏ ‏أَفْنَدَ ‏ ‏وَقَدْ أَدْرَكَتْهُ فَرِيضَةُ اللَّهِ فِي الْحَجِّ فَهَلْ يُجْزِئُ أَنْ أَحُجَّ عَنْهُ قَالَ نَعَمْ فَأَدِّي عَنْ أَبِيكِ قَالَ وَلَوَى عُنُقَ ‏ ‏الْفَضْلِ ‏ ‏فَقَالَ لَهُ ‏ ‏الْعَبَّاسُ ‏ ‏يَا رَسُولَ اللَّهِ مَا لَكَ لَوَيْتَ عُنُقَ ابْنِ عَمِّكَ قَالَ رَأَيْتُ شَابًّا وَشَابَّةً فَخِفْتُ الشَّيْطَانَ عَلَيْهِمَا قَالَ وَأَتَاهُ رَجُلٌ فَقَالَ ‏ ‏أَفَضْتُ ‏ ‏قَبْلَ أَنْ أَحْلِقَ قَالَ فَاحْلِقْ أَوْ قَصِّرْ وَلَا ‏ ‏حَرَجَ ‏ ‏قَالَ وَأَتَى ‏ ‏زَمْزَمَ ‏ ‏فَقَالَ يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏سِقَايَتَكُمْ لَوْلَا أَنْ يَغْلِبَكُمْ النَّاسُ عَلَيْهَا ‏ ‏لَنَزَعْتُ ‏","","",""],[1278,1278,"","আমরা হাত দিয়ে কথা বলেছি যে আমরা পৃথিবীর ভালোবাসা শুনতে চাই, আমি সন্তুষ্ট যে আমার সালমকে আমার কাছে নিয়ে গেছে আমাদের দোহাইর জন্য আমাদের অনুগ্রহের আগ পর্যন্ত বেঁচে থাকে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন যেন তিনি আত্মা থেকে কোন প্রাণ সমর্পণ না করেন। আমি আনন্দিত, আমি আমার কথাকে বিশ্বাস করি, আমি গোপনে এর জন্য সাহায্য করব","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ يَعْنِي ابْنَ الْبَرِيدِ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏أَخَذَ بِيَدِي ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَانْطَلَقْنَا نَمْشِي حَتَّى جَلَسْنَا عَلَى شَطِّ الْفُرَاتِ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ نَفْسٍ ‏ ‏مَنْفُوسَةٍ ‏ ‏إِلَّا قَدْ سَبَقَ لَهَا مِنْ اللَّهِ شَقَاءٌ أَوْ سَعَادَةٌ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ فِيمَ إِذًا نَعْمَلُ قَالَ اعْمَلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ ثُمَّ قَرَأَ هَذِهِ الْآيَةَ ‏ { ‏فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى ‏ ‏إِلَى قَوْلِهِ ‏ ‏فَسَنُيَسِّرُهُ ‏ ‏لِلْعُسْرَى ‏ }","","",""],[1279,1279,"","শত্রু যে - জীবন আমি দেখেছিলাম, তা আমি দেখেছিলাম আর তারপর তাকে কিছুটা পরে ফোন করেছিলাম । তিনি তৃতীয় বার ধরা পড়েছিলেন এবং তিন বার মারা গিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ الْوَادِعِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَالَ فِي ‏ ‏الرَّحَبَةِ ‏ ‏ثُمَّ دَعَا بِمَاءٍ ‏ ‏فَتَوَضَّأَ فَغَسَلَ كَفَّيْهِ ثَلَاثًا وَتَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَغَسَلَ قَدَمَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ كَالَّذِي رَأَيْتُمُونِي فَعَلْتُ ‏","","",""],[1280,1280,"","আমি আমার নিজের বাড়িতে বাস করি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিন জন ব্যক্তিকে উদ্ধার করেছেন সময়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرٌ أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ثَلَاثًا ثَلَاثًا ‏","","",""],[1281,1281,"","আমি আমার বাবাকে খুব সহজেই তার সঙ্গে কথা বলতে দেখেছিলাম । তারপর সে তার লাইট পান করে বললো, যখন আমি তোমাকে দেখতে চাই, সে একটা বিভ্রান্ত হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ فَأَنْقَى كَفَّيْهِ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ قَدَمَيْهِ إِلَى الْكَعْبَيْنِ ثُمَّ قَامَ فَشَرِبَ ‏ ‏فَضْلَ ‏ ‏وَضُوئِهِ ثُمَّ قَالَ إِنَّمَا أَرَدْتُ أَنْ أُرِيَكُمْ طُهُورَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1282,1282,"","আমরা ইশ্বরের সাথে কথা বলেছি, কিন্তু আমি খুশি হব আমরা যে আমরা বেশ কয়েকবার তোমাকে জেতার কথা বলেছি. রোগী হয়তো তোমাকে এটা করতে শিখিয়েছে. তার আছে সে- সে-ই আছে, সে জানে সে জানে আমার সাথে কথা বলে আমি মানুষের সাথে যা করছি তা থেকে এবং আমার যোদ্ধা আমাকে পাশ করে গেছে এবং সে বলল, সে বলছে, আমি কি করছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ الْفَزَارِيُّ ‏ ‏عَنِ ‏ ‏الْمُخْتَارِ بْنِ نَافِعٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مَطَرٍ الْبَصْرِيُّ ‏ ‏وَكَانَ قَدْ أَدْرَكَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏اشْتَرَى ثَوْبًا بِثَلَاثَةِ دَرَاهِمَ فَلَمَّا لَبِسَهُ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي رَزَقَنِي مِنْ ‏ ‏الرِّيَاشِ ‏ ‏مَا أَتَجَمَّلُ بِهِ فِي النَّاسِ ‏ ‏وَأُوَارِي بِهِ عَوْرَتِي ثُمَّ قَالَ هَكَذَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏","","",""],[1283,1283,"","আমার বাবা যখন কথা বলতেন, আমার জীবন অপমানের সাথে আমার চেহারার দিকে তাকিয়ে ছিল, সে আমার দিকে তাকিয়ে বলছিল, সে আমার দিকে তাকিয়ে আছে। তিন সেকেন্ড ধরে সে বাকরিকে ফাঁসাচ্ছে আর তারপর তাকে তার কাছে যেতে দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ الْهَمْدَانِيِّ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْيَنْظُرْ إِلَيَّ قَالَ ‏ ‏فَتَوَضَّأَ ثَلَاثًا ثَلَاثًا ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ شَرِبَ ‏ ‏فَضْلَ ‏ ‏وَضُوئِهِ ‏","","",""],[1284,1284,"","তিনি দুই বছর ধরে চলে গিয়েছেন এবং একজন ব্যক্তির জন্য চলে গিয়েছেন । আমার মনে হয় তোমার ব্যাপারে কিছু একটা আছে, সে কিছু একটা বলবে আমি ঈশ্বরের প্রভুর কাছে প্রার্থনা করেছি তার জন্য প্রার্থনা করে আর বলবে যে তাকে শাসন করতে হবে। মানুষ বিক্রি করে আর আমি তাকে আমার ঋণের কথা বলছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُخْتَارُ بْنُ نَافِعٍ التَّمَّارُ ‏ ‏عَنْ ‏ ‏أَبِي مَطَرٍ ‏ ‏أَنَّهُ رَأَى ‏ ‏عَلِيًّا ‏ ‏أَتَى غُلَامًا ‏ ‏حَدَثًا ‏ ‏فَاشْتَرَى مِنْهُ قَمِيصًا بِثَلَاثَةِ دَرَاهِمَ وَلَبِسَهُ إِلَى مَا بَيْنَ ‏ ‏الرُّسْغَيْنِ ‏ ‏إِلَى الْكَعْبَيْنِ يَقُولُ وَلَبِسَهُ الْحَمْدُ لِلَّهِ الَّذِي رَزَقَنِي مِنْ ‏ ‏الرِّيَاشِ ‏ ‏مَا أَتَجَمَّلُ بِهِ فِي النَّاسِ ‏ ‏وَأُوَارِي بِهِ عَوْرَتِي فَقِيلَ هَذَا شَيْءٌ ‏ ‏تَرْوِيهِ عَنْ نَفْسِكَ أَوْ عَنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَذَا شَيْءٌ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُهُ عِنْدَ الْكُسْوَةِ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي رَزَقَنِي مِنْ ‏ ‏الرِّيَاشِ ‏ ‏مَا أَتَجَمَّلُ بِهِ فِي النَّاسِ ‏ ‏وَأُوَارِي بِهِ عَوْرَتِي ‏","","",""],[1285,1285,"","আমরা বাবার এক স্বপ্নের মাধ্যমে একটা দাসের কথা বলেছি, যে আমাদের হয়ে কাজ করছে, ঈশ্বরের গৌরব আমাকে হত্যা করেছে এবং আমার প্রাণকে আলোকিত করেছে। সে বলল, আমার কাছে পানি আছে। আমি কি এটা একটা ধনের সম্পদ। আমি যা চাই তা হল, আমি কি এটা আমার বাবার কাছে একটা জিনিস। আমি জানি? আমি কি জানি না? আমি এটা জানি না যে, আমি এটা করতে পারি না? আমি যদি আমার বাবার আগুনের উপর দিয়ে চলে যাই। আমি এটা একটা বড় ধরনের জিনিস। এবং আমি যদি চাই, আমি এটা করি, আমি শুধু একটা জিনিস। আমি যদি চাই, আমি এটা করি, আমি শুধু একটা জিনিসও করতে চাই, আমি চাই, আমি জানি যে, আমি কি করবো? তিনি তিন বার আতঙ্কের কথা ভুলে গিয়েছিলেন এবং এরপর তাকে মাথায় আসতে বলেছিলেন । ( গীতসংহিতা ১১৯: ১৬৬) ঈশ্বরের কাছে প্রার্থনা করাই ছিল তাঁর জন্য ও তাঁর কাছে প্রার্থনা করার মতো । আত্মসমর্পণ করো.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُخْتَارٌ ‏ ‏عَنْ ‏ ‏أَبِي مَطَرٍ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ جُلُوسٌ مَعَ أَمِيرِ الْمُؤْمِنِينَ ‏ ‏عَلِيٍّ ‏ ‏فِي الْمَسْجِدِ عَلَى بَابِ ‏ ‏الرَّحَبَةِ ‏ ‏جَاءَ رَجُلٌ فَقَالَ أَرِنِي وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عِنْدَ ‏ ‏الزَّوَالِ ‏ ‏فَدَعَا ‏ ‏قَنْبَرًا ‏ ‏فَقَالَ ‏ ‏ائْتِنِي بِكُوزٍ مِنْ مَاءٍ فَغَسَلَ كَفَّيْهِ وَوَجْهَهُ ثَلَاثًا وَتَمَضْمَضَ ثَلَاثًا فَأَدْخَلَ بَعْضَ أَصَابِعِهِ فِي ‏ ‏فِيهِ وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ ذِرَاعَيْهِ ثَلَاثًا وَمَسَحَ رَأْسَهُ وَاحِدَةً فَقَالَ دَاخِلُهُمَا مِنْ الْوَجْهِ وَخَارِجُهُمَا مِنْ الرَّأْسِ وَرِجْلَيْهِ إِلَى الْكَعْبَيْنِ ثَلَاثًا وَلِحْيَتُهُ تَهْطِلُ عَلَى صَدْرِهِ ثُمَّ ‏ ‏حَسَا ‏ ‏حَسْوَةً ‏ ‏بَعْدَ الْوُضُوءِ ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَا كَانَ وُضُوءُ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1286,1286,"","আমরা হাত দিয়ে কথা বলেছি আর অন্ধ নই, ঈশ্বর নিষেধ করেছেন আমি যা শুনেছি তা তিনি দৃঢ়ভাবে আত্মসমর্পণ করেছেন আর তার কাছে আত্মসমর্পণ করেছেন, তিনি বলেছিলেন বাবা তার বাবাকে একটা জন্য ঘুমাচ্ছিলো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏ابْنِ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏مَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْمَعُ أَبَاهُ وَأُمَّهُ لِأَحَدٍ إِلَّا ‏ ‏لِسَعْدٍ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏أَبَوَيْهِ لِأَحَدٍ ‏","","",""],[1287,1287,"","আমরা একটা হাত দিয়ে কথা বলেছি, সে বলেছে, ঈশ্বর, তাকে বিয়ে করতে হবে, সে বলল যে আমার ভাইয়ের মেয়ে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا لَكَ ‏ ‏تَنَوَّقُ ‏ ‏فِي ‏ ‏قُرَيْشٍ ‏ ‏وَلَا تَزَوَّجُ إِلَيْنَا قَالَ وَعِنْدَكَ شَيْءٌ قَالَ قُلْتُ نَعَمْ ‏ ‏ابْنَةُ حَمْزَةَ ‏ ‏قَالَ ‏ ‏تِلْكَ ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ ‏","","",""],[1288,1288,"","বাবার ভালবাসার কথা বলতে গিয়ে বাবা তার সাথে কথা বলেছিলেন। এভাবে নিয়ে যাওয়া হয়েছিল ক্যাম্পে ফিরে যেতে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زُرَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أُهْدِيَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَغْلَةٌ فَرَكِبَهَا فَقَالَ بَعْضُ أَصْحَابِهِ لَوْ اتَّخَذْنَا مِثْلَ هَذَا قَالَ ‏ ‏أَتُرِيدُونَ أَنْ تُنْزُوا الْحَمِيرَ عَلَى الْخَيْلِ إِنَّمَا يَفْعَلُ ذَلِكَ الَّذِينَ لَا يَعْلَمُونَ ‏","","",""],[1289,1289,"","আমি ইশ্বরের সাথে কথা বলেছি, তাঁরা আমাকে এ ব্যাপারে সব থেকে ভালো কথা বলেছে। ঈশ্বর আমার বাবার নিজের কথা বলে বসে আছেন। আমি দেখছি ঈশ্বর কিভাবে প্রার্থনা করেছেন। তার কাছে শপথ নেয়া হবে, তার তিন আর তিন বাক হবে আর সে তিন বার ঘুরে যাবে আর সে এটা বন্ধ করবে. সে তার লোকদের কিছু সময়ের জন্য পরিষ্কার করবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُحَمَّدِ بْنِ بُكَيْرٍ النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ هِلَالٍ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَلَا ‏ ‏أُرِيكُمْ كَيْفَ كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ قُلْنَا بَلَى قَالَ فَأْتُونِي ‏ ‏بِطَسْتٍ ‏ ‏وَتَوْرٍ ‏ ‏مِنْ مَاءٍ ‏ ‏فَغَسَلَ يَدَيْهِ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ ثَلَاثًا وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ‏","","",""],[1290,1290,"","আমরা বাবাকে আমার যা বলার ছিল, তা দেওয়ার বিষয়ে বাবা বলেছিলেন । ছোট ছোটগুলো এমনকি বড় এবং ছায়ার কথা বলছে যতক্ষণ না এটা থেমে যায়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لِعُمَرَ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ أَمَا سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ عَنْ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنْ الصَّغِيرِ حَتَّى يَكْبَرَ وَعَنْ ‏ ‏الْمُبْتَلَى ‏ ‏حَتَّى يَعْقِلَ ‏","","",""],[1291,1291,"","আমার প্রভু শুনেছিলেন যে, তিনি তার বাবার কথা শুনবেন, যিনি তার বাবার কাছে ঈশ্বরের কাছে প্রার্থনা করেছেন । ঈশ্বরের ক্ষতি করার জন্য তাদেরকে দোষ দিও না, আমি প্রভুর মৃত্যুকে দায়ী করছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سَلَمَةَ بْنِ أَبِي الْحُسَامِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ الْأَكْبَرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيتُ أَرْبَعًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنْ أَنْبِيَاءِ اللَّهِ أُعْطِيتُ مَفَاتِيحَ الْأَرْضِ وَسُمِّيتُ ‏ ‏أَحْمَدَ ‏ ‏وَجُعِلَ التُّرَابُ لِي طَهُورًا وَجُعِلَتْ أُمَّتِي خَيْرَ الْأُمَمِ ‏","","",""],[1292,1292,"","বাবার সাথে আমার বাবার কথা বলেছিলাম, সে আমার পরিতৃপ্তির জন্য চলে গেছে, ওর রাজপুত্র, নাকি ওর কথা শুনলেই ওকে ছেড়ে দিয়ে যাবে। তিন জন যুবক জেগে উঠে আর এমনকি হত্যা পর্যন্ত বড় হয়ে উঠে","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لِعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ أَمَا سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ عَنْ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنْ الصَّغِيرِ حَتَّى يَكْبَرَ وَعَنْ ‏ ‏الْمُبْتَلَى ‏ ‏حَتَّى يَعْقِلَ ‏","","",""],[1293,1293,"","ঈশ্বর কোনো মহান ঈশ্বর নন, ঈশ্বর ঈশ্বর । ঈশ্বর হলেন ঈশ্বর ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُعَلِّمُكَ كَلِمَاتٍ إِذَا قُلْتَهُنَّ غُفِرَ لَكَ عَلَى أَنَّهُ مَغْفُورٌ لَكَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ الْعَلِيُّ الْعَظِيمُ لَا إِلَهَ إِلَّا هُوَ الْحَلِيمُ الْكَرِيمُ سُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ الْعَظِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏","","",""],[1294,1294,"","ঈশ্বর ঈশ্বর তাঁর কাছে প্রার্থনা করেন এবং ঈশ্বরের কাছে তাঁর কাছে প্রার্থনা করেন । আবহাওয়ার শেষ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَيْهِ وَكَاتِبَهُ ‏ ‏وَالْمُحِلَّ ‏ ‏وَالْمُحَلَّلَ ‏ ‏لَهُ ‏ ‏وَالْوَاشِمَةَ ‏ ‏وَالْمُسْتَوْشِمَةَ ‏ ‏وَمَانِعَ ‏ ‏الصَّدَقَةِ ‏ ‏وَنَهَى عَنْ ‏ ‏النَّوْحِ ‏","","",""],[1295,1295,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং জিজ্ঞেস করেছিলেন যে, কে তাঁর শাস্তির অযোগ্যতা করেছে । ঋণ শোধ করে, খোদা তাকে চিনেন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَذْنَبَ فِي الدُّنْيَا ذَنْبًا فَعُوقِبَ بِهِ فَاللَّهُ أَعْدَلُ مِنْ أَنْ ‏ ‏يُثَنِّيَ ‏ ‏عُقُوبَتَهُ عَلَى عَبْدِهِ وَمَنْ أَذْنَبَ ذَنْبًا فِي الدُّنْيَا فَسَتَرَ اللَّهُ عَلَيْهِ وَعَفَا عَنْهُ فَاللَّهُ أَكْرَمُ مِنْ أَنْ يَعُودَ فِي شَيْءٍ قَدْ عَفَا عَنْهُ ‏","","",""],[1296,1296,"","রাজা স্লাইড বেনের কাছে একটা গোপন রহস্য আছে, যার মাধ্যমে তিনি তার অভিজাত দৃষ্টির সামনে আমাদের প্রার্থনাকে প্রকাশ করেন । না, সে প্রেমে বসেছে, পরে আমরা যে রাগে পড়ে গেছে, সে বাইরে বের হয়ে যায় আর তাকে খুন করতে চায় আর আমি ভগবানের কাছে প্রার্থনা করতে দেখেছি... ...যেটা সে আমার মতোই করেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِسْمَاعِيلَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏النَّزَّالِ بْنِ سَبْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّيْنَا مَعَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏الظُّهْرَ فَانْطَلَقَ إِلَى مَجْلِسٍ لَهُ يَجْلِسُهُ فِي ‏ ‏الرَّحَبَةِ ‏ ‏فَقَعَدَ وَقَعَدْنَا حَوْلَهُ ثُمَّ حَضَرَتْ الْعَصْرُ فَأُتِيَ بِإِنَاءٍ ‏ ‏فَأَخَذَ مِنْهُ كَفًّا فَتَمَضْمَضَ وَاسْتَنْشَقَ وَمَسَحَ بِوَجْهِهِ وَذِرَاعَيْهِ وَمَسَحَ بِرَأْسِهِ وَمَسَحَ بِرِجْلَيْهِ ثُمَّ قَامَ فَشَرِبَ ‏ ‏فَضْلَ ‏ ‏إِنَائِهِ ثُمَّ قَالَ إِنِّي حُدِّثْتُ أَنَّ رِجَالًا يَكْرَهُونَ أَنْ يَشْرَبَ أَحَدُهُمْ وَهُوَ قَائِمٌ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ كَمَا فَعَلْتُ ‏","","",""],[1297,1297,"","বেনের রাজধানী সম্পর্কে আমরা কথা বলেছি... ...আমার প্রাণের অধিকারীর গর্ভের অধিকারীর কথা, সে আমাকে তার প্রভুর সাথে দেখা করতে দেখেছে... আমি একে অপরের ভালোবাসার রাজধানী সম্পর্কে জানতে সাহায্য করার চেষ্টা করছি।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ لَقَدْ رَأَيْتُنِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنِّي لَأَرْبُطُ الْحَجَرَ عَلَى بَطْنِي مِنْ الْجُوعِ وَإِنَّ ‏ ‏صَدَقَتِي ‏ ‏الْيَوْمَ لَأَرْبَعُونَ أَلْفًا ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَذَكَرَ الْحَدِيثَ وَقَالَ فِيهِ وَإِنَّ ‏ ‏صَدَقَةَ ‏ ‏مَالِي لَتَبْلُغُ أَرْبَعِينَ أَلْفَ دِينَارٍ ‏","","",""],[1298,1298,"","আমরা পর্দার মাংসের বাপ্তিস্ম মুছে ফেলার চেষ্টা করেছি। আমার প্রিয় বাবা আমাকে বলেছে যে, তিনি আমাকে ঈশ্বরের আনন্দ দিয়েছেন, তিনি আমাকে ঈশ্বরের দোহাইর দিকে তাকান এবং না. তোমার জন্য নয়.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُتْبِعْ النَّظَرَ النَّظَرَ فَإِنَّ الْأُولَى لَكَ وَلَيْسَتْ لَكَ الْأَخِيرَةُ ‏","","",""],[1299,1299,"","আমরা অন্য যেকোনো সময়ের চেয়ে ভালো জীবন পাবার কথা বলেছি। আমার প্রভু বললেন, কেন মঙ্গলভাব তার নিজের জন্য আর নিজের জন্য তার নিজের জন্য নিজের জন্য... তিনি আমাকে আদেশ দিয়েছেন, আমি বলি, আমাকে আমার নাম গাইতে আদেশ করা হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا وُلِدَ ‏ ‏الْحَسَنُ ‏ ‏سَمَّاهُ ‏ ‏حَمْزَةَ ‏ ‏فَلَمَّا وُلِدَ ‏ ‏الْحُسَيْنُ ‏ ‏سَمَّاهُ بِعَمِّهِ ‏ ‏جَعْفَرٍ ‏ ‏قَالَ فَدَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنِّي أُمِرْتُ أَنْ أُغَيِّرَ اسْمَ هَذَيْنِ فَقُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ فَسَمَّاهُمَا ‏ ‏حَسَنًا ‏ ‏وَحُسَيْنًا ‏","","",""],[1300,1300,"","আমরা আমার বাবার কথা বলেছিলাম কাঠবিড়ালীর পর এক দৈত্য শিকারীর কথা। ঈশ্বর তাকে ঈশ্বরের অনুগ্রহের জন্য একত্র করতে বলেছেন অথবা আল্লাহ তাকে উদ্ধার করেছেন। ছাত্ররা সবাই নেকড়ে খেতে যাচ্ছে আর সে যে বিরতি নিয়েছে তা পান করে রাখে। সে রান্না করতো যেন তার স্পর্শ না হয়ে আর বন্যা ডেকে তাকে বলে, \"আমি বলছি, আমাকে অবশ্যই মানুষ করতে হবে।\" জনসম্মুখে এবং দেখতে চাই কে আমি আমার ভাই এবং আমার ভাই হবে হবে যে কেউ বলবে যে আমি আর আমি করব. তার হাতে গুলি লেগেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِي صَادِقٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ نَاجِذٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فِيهِمْ ‏ ‏رَهْطٌ ‏ ‏كُلُّهُمْ يَأْكُلُ ‏ ‏الْجَذَعَةَ ‏ ‏وَيَشْرَبُ ‏ ‏الْفَرَقَ ‏ ‏قَالَ فَصَنَعَ لَهُمْ ‏ ‏مُدًّا ‏ ‏مِنْ طَعَامٍ فَأَكَلُوا حَتَّى شَبِعُوا قَالَ وَبَقِيَ الطَّعَامُ كَمَا هُوَ كَأَنَّهُ لَمْ يُمَسَّ ثُمَّ دَعَا ‏ ‏بِغُمَرٍ ‏ ‏فَشَرِبُوا حَتَّى رَوَوْا وَبَقِيَ الشَّرَابُ كَأَنَّهُ لَمْ يُمَسَّ ‏ ‏أَوْ لَمْ يُشْرَبْ ‏ ‏فَقَالَ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏إِنِّي بُعِثْتُ لَكُمْ خَاصَّةً وَإِلَى النَّاسِ بِعَامَّةٍ وَقَدْ رَأَيْتُمْ مِنْ هَذِهِ الْآيَةِ مَا رَأَيْتُمْ فَأَيُّكُمْ يُبَايِعُنِي عَلَى أَنْ يَكُونَ أَخِي وَصَاحِبِي قَالَ فَلَمْ يَقُمْ إِلَيْهِ أَحَدٌ قَالَ فَقُمْتُ إِلَيْهِ وَكُنْتُ أَصْغَرَ الْقَوْمِ قَالَ فَقَالَ اجْلِسْ قَالَ ثَلَاثَ مَرَّاتٍ كُلُّ ذَلِكَ أَقُومُ إِلَيْهِ فَيَقُولُ لِي اجْلِسْ حَتَّى كَانَ فِي الثَّالِثَةِ ضَرَبَ بِيَدِهِ عَلَى يَدِي ‏","","",""],[1301,1301,"","সেই সময়ে, আমরা আমাদের পরিবারের সঙ্গে বাইবেল অধ্যয়ন শুরু করেছিলাম । তাকে আত্মসমর্পণ এবং আত্মসমর্পণ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏النَّزَّالِ بْنِ سَبْرَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ ‏ ‏شَرِبَ وَهُوَ قَائِمٌ ثُمَّ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1302,1302,"","আমরা ওকে বাঁচানোর জন্য আমাদের বাপ্তিস্মের কথা বলেছি। আমার বাবার ছাত্র যে তাকে বলেছে, সে তোমাকে খুঁজে বের করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏يَا ‏ ‏عَلِيُّ ‏ ‏إِنَّ لَكَ كَنْزًا مِنْ الْجَنَّةِ وَإِنَّكَ ذُو قَرْنَيْهَا فَلَا تُتْبِعْ النَّظْرَةَ النَّظْرَةَ فَإِنَّمَا لَكَ الْأُولَى وَلَيْسَتْ لَكَ الْآخِرَةُ ‏","","",""],[1303,1303,"","আমরা ঈশ্বরের প্রতিজ্ঞার দ্বারা বাপ্তাইজিত হয়েছি, আমার বাবা, ঈশ্বরের মঙ্গলের জন্য। আমার বাবা ঈশ্বরের কাছে আমার সন্তুষ্ট ছিলেন। তিনি বলেছিলেন, কেন আমরা ঈশ্বরের ইচ্ছা ছেড়ে দেব। আমি আদেশ করেছিলাম, আমি তাকে গোপনে মুক্ত করে দিলাম... ...আর সে শপথ করে বলে যে সে একজন মানুষ আর জন্ম নিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا نَحَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُدْنَهُ ‏ ‏نَحَرَ ‏ ‏بِيَدِهِ ثَلَاثِينَ وَأَمَرَنِي فَنَحَرْتُ سَائِرَهَا وَقَالَ اقْسِمْ لُحُومَهَا بَيْنَ النَّاسِ وَجُلُودَهَا ‏ ‏وَجِلَالَهَا ‏ ‏وَلَا تُعْطِيَنَّ جَازِرًا مِنْهَا شَيْئًا ‏","","",""],[1304,1304,"","আমরা আমার বাবা একটি আগুনের রাজধানীর কথা বলেছি যেটা শুনে ঈশ্বর বলেছেন যে আল্লাহ আমাকে ঈশ্বরের প্রার্থনা করতে বলেছেন যাতে আমি তাকে নদী থেকে আত্মসমর্পণ করতে বলেছি এটা বলা হয়ে থাকে যে সূর্য যদি এখান থেকে এখানে থেকে আসে, তাহলে আমাদের একটি শুভ বিকেল আছে এবং ভোরের আগে আমি চলে যাচ্ছি। ভাববাদীর সন্তানদের কাছে রাজ্যগুলোর নম্র আচরণ করুন এবং তাদেরকে জগতের রাজাদের বিশ্বস্ত ও বুদ্ধিমান্‌তাদের কাছ থেকে বিক্রি করে দিন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَاصِمَ بْنَ ضَمْرَةَ ‏ ‏يَقُولُ ‏ ‏سَأَلْنَا ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ النَّهَارِ فَقَالَ إِنَّكُمْ لَا تُطِيقُونَ ذَلِكَ قُلْنَا مَنْ أَطَاقَ مِنَّا ذَلِكَ قَالَ ‏ ‏إِذَا كَانَتْ الشَّمْسُ مِنْ هَاهُنَا كَهَيْئَتِهَا مِنْ هَاهُنَا عِنْدَ الْعَصْرِ صَلَّى رَكْعَتَيْنِ وَإِذَا كَانَتْ الشَّمْسُ مِنْ هَاهُنَا كَهَيْئَتِهَا مِنْ هَاهُنَا عِنْدَ الظُّهْرِ صَلَّى أَرْبَعًا وَيُصَلِّي قَبْلَ الظُّهْرِ أَرْبَعًا وَبَعْدَهَا رَكْعَتَيْنِ وَقَبْلَ الْعَصْرِ أَرْبَعًا وَيَفْصِلُ بَيْنَ كُلِّ رَكْعَتَيْنِ بِالتَّسْلِيمِ عَلَى الْمَلَائِكَةِ الْمُقَرَّبِينَ وَالنَّبِيِّينَ وَمَنْ تَبِعَهُمْ مِنْ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ ‏","","",""],[1305,1305,"","আমার বাবা আমার বাবাকে খুঁজে পাওয়ার মাধ্যমে হয়তো আমার মন বাঁচিয়েছিল । লর্ড পরাজিত হয়ে গেল যাতে তার মা বিজয় দ্বারা ভালবাসা পায়। আমার অপমানের জন্য যে আমাকে বিশ্বাস করতে পারবে না, সেই চমৎকার ব্যক্তি।","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجُ بْنُ يُونُسَ أَبُو الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَفْصٍ الْأَبَّارُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ حَصِيرَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَادِقٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ نَاجِذٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيكَ مَثَلٌ مِنْ ‏ ‏عِيسَى ‏ ‏أَبْغَضَتْهُ ‏ ‏الْيَهُودُ ‏ ‏حَتَّى بَهَتُوا أُمَّهُ وَأَحَبَّتْهُ ‏ ‏النَّصَارَى ‏ ‏حَتَّى أَنْزَلُوهُ بِالْمَنْزِلَةِ الَّتِي لَيْسَ بِهِ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏يَهْلِكُ فِيَّ رَجُلَانِ مُحِبٌّ مُفْرِطٌ ‏ ‏يُقَرِّظُنِي ‏ ‏بِمَا لَيْسَ فِيَّ وَمُبْغِضٌ يَحْمِلُهُ ‏ ‏شَنَآنِي ‏ ‏عَلَى أَنْ ‏ ‏يَبْهَتَنِي ‏","","",""],[1306,1306,"","শয়তান আমার বাবার একজন রাজার জন্য আমার বাবার বিচার করছে । তার জন্য লর্ডের ভালো পালনকর আছে তার জন্য ঈশ্বরকে বিদায় জানানো। আমি তাকে সরিয়ে দিলাম। তার মা তাকে এমন বিজয় থেকে মুক্ত করতে পছন্দ করবে যেন তার জয়ে না হয়। দুই প্রেমিক আমাকে কি মনে করে? আমি নিজের হাতে নই, কিন্তু ঈশ্বরের বই আর তার ভালোর জন্য তার সবকিছু করতে হবে, যখন আমি তোমাকে পছন্দ করি আর ঘৃণা করি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو مُحَمَّدٍ سُفْيَانُ بْنُ وَكِيعِ بْنِ الْجَرَّاحِ بْنِ مَلِيحٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو غَيْلَانَ الشَّيْبَانِيُّ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ حَصِيرَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَادِقٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ نَاجِدٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ فِيكَ مِنْ ‏ ‏عِيسَى ‏ ‏مَثَلًا أَبْغَضَتْهُ ‏ ‏يَهُودُ ‏ ‏حَتَّى ‏ ‏بَهَتُوا ‏ ‏أُمَّهُ وَأَحَبَّتْهُ ‏ ‏النَّصَارَى ‏ ‏حَتَّى أَنْزَلُوهُ بِالْمَنْزِلِ الَّذِي لَيْسَ بِهِ ‏ ‏أَلَا وَإِنَّهُ يَهْلِكُ فِيَّ اثْنَانِ مُحِبٌّ ‏ ‏يُقَرِّظُنِي ‏ ‏بِمَا لَيْسَ فِيَّ وَمُبْغِضٌ يَحْمِلُهُ ‏ ‏شَنَآنِي ‏ ‏عَلَى أَنْ ‏ ‏يَبْهَتَنِي ‏ ‏أَلَا إِنِّي لَسْتُ بِنَبِيٍّ وَلَا يُوحَى إِلَيَّ وَلَكِنِّي أَعْمَلُ بِكِتَابِ اللَّهِ وَسُنَّةِ نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا اسْتَطَعْتُ فَمَا أَمَرْتُكُمْ مِنْ طَاعَةِ اللَّهِ فَحَقٌّ عَلَيْكُمْ طَاعَتِي فِيمَا أَحْبَبْتُمْ وَكَرِهْتُمْ ‏","","",""],[1307,1307,"","আমার বাবা বলেছিলেন যে, তার জন্য ঈশ্বরের কাছে আমার অনুগ্রহ রয়েছে । ঈশ্বরকে খুশি করার জন্য, আমার বাবা, আর তাকে জিজ্ঞেস করুন যে সে পবিত্র স্থান থেকে সরে গেছে কে এখানে না আসবে। হাত থেকে বাঁচা, এটা তার নিজের, তারপর আমি তাকে খুন করার চেষ্টা করেছি, আমি ঈশ্বরের ছেলের কথা বলেছিলাম আমার ঈশ্বরত্ব নিয়ে। যদি তার কাছে এমন একজন লোক থাকে যে কিনা কিনা এই ব্যঙ্গাত্মক লোকদের সাথে যাবে। আল্লাহ আমাকে এসে তাকে জীবিত রাখার জন্য ক্ষমা প্রার্থনা করেছেন। তুমি তো এটা করেছ এবং আমি বলছি, আল্লাহ বলে এটা ঘটবে। তারা কোরআনকে আকাশে বয়ে নিয়ে যাওয়ার সময় মোটা থেকে তাদের উপর থেকে নিক্ষেপ না করে বরং সেগুলো পাঠ করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو خَيْثَمَةَ زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ مَالِكٍ الْمُزَنِيُّ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ ‏ ‏إِنِّي دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَيْسَ عِنْدَهُ أَحَدٌ إِلَّا ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَقَالَ يَا ‏ ‏ابْنَ أَبِي طَالِبٍ ‏ ‏كَيْفَ أَنْتَ وَقَوْمَ كَذَا وَكَذَا قَالَ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏قَوْمٌ يَخْرُجُونَ مِنْ الْمَشْرِقِ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ ‏ ‏مُرُوقَ ‏ ‏السَّهْمِ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏فَمِنْهُمْ رَجُلٌ ‏ ‏مُخْدَجُ ‏ ‏الْيَدِ كَأَنَّ يَدَيْهِ ثَدْيُ حَبَشِيَّةٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ أَبُو مَعْمَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِذْ دَخَلَ عَلَيْهِ رَجُلٌ عَلَيْهِ ثِيَابُ السَّفَرِ فَاسْتَأْذَنَ عَلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ يُكَلِّمُ النَّاسَ فَشُغِلَ عَنْهُ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنِّي دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَقَالَ لِي كَيْفَ أَنْتَ وَقَوْمَ كَذَا وَكَذَا فَقُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ ثُمَّ عَادَ فَقُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَقَالَ قَوْمٌ يَخْرُجُونَ مِنْ قِبَلِ الْمَشْرِقِ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏فِيهِمْ رَجُلٌ ‏ ‏مُخْدَجُ ‏ ‏الْيَدِ كَأَنَّ يَدَهُ ثَدْيُ حَبَشِيَّةٍ ‏ ‏أَنْشُدُكُمْ ‏ ‏بِاللَّهِ هَلْ أَخْبَرْتُكُمْ أَنَّ فِيهِمْ فَذَكَرَ الْحَدِيثَ بِطُولِهِ ‏","","",""],[1308,1308,"","আমরা ঈশ্বরের সঙ্গে কথা বলেছিলাম, আমি দুই হারামীর ছেলে ছিলাম, যারা আমার বাবার কথা বলেছিল । তিনি তিন বার উল্লেখ করেছিলেন অথবা তিন বার উল্লেখ করেছিলেন । তার বিশ্বস্ত রাজকুমারের শেষ অংশ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سُفْيَانُ بْنُ وَكِيعِ بْنِ الْجَرَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ الْوَادِعِيِّ ‏ ‏عَنْ ‏ ‏عَمْرٍو ذِي مُرٍّ ‏ ‏قَالَ ‏ ‏أَبْصَرْنَا ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ فَغَسَلَ يَدَيْهِ وَمَضْمَضَ وَاسْتَنْشَقَ ‏ ‏قَالَ وَأَنَا أَشُكُّ فِي الْمَضْمَضَةِ ‏ ‏وَالِاسْتِنْشَاقِ ثَلَاثًا ذَكَرَهَا أَمْ لَا ‏ ‏وَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا كُلَّ وَاحِدَةٍ مِنْهُمَا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ‏ ‏قَالَ ‏ ‏أَحَدُهُمَا ثُمَّ أَخَذَ ‏ ‏غَرْفَةً ‏ ‏فَمَسَحَ بِهَا رَأْسَهُ ‏ ‏ثُمَّ قَامَ فَشَرِبَ ‏ ‏فَضْلَ ‏ ‏وَضُوئِهِ ثُمَّ قَالَ هَكَذَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏آخِرُ مُسْنَدِ أَمِيرِ الْمُؤْمِنِينَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[1309,1309,"","আমরা একটি সময়ের জন্য একে অপরের সাথে কথা বলেছি যখন আমার বাবা তার উপর দোয়া করতে ক্লান্ত হয়ে পড়েন এবং বলেন আল্লাহ যেন আল্লাহ আমার সহায় হন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ ‏ ‏وَعَبْدُ الْجَبَّارِ بْنُ وَرْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ قَالَ ‏ ‏طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏نِعْمَ أَهْلُ الْبَيْتِ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَأَبُو عَبْدِ اللَّهِ ‏ ‏وَأُمُّ عَبْدِ اللَّهِ ‏","","",""],[1310,1310,"","আমরা বাবার মেয়ের সবচেয়ে ভালো কথা বলেছি, ঈশ্বর ঈশ্বরের অনুগ্রহের কথা বলতে পারেন না, কিন্তু তিনি কিছু উদ্ধার করবেন। আমার বাবার ছেলের পাহাড় কেটে গেছে, পিট, আল্লাহ আর আমার বাবা হয়তো ঈশ্বর হতে পারে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ ‏ ‏وَعَبْدُ الْجَبَّارِ بْنُ الْوَرْدِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ قَالَ ‏ ‏طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏لَا أُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا إِلَّا أَنِّي سَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ ‏ ‏عَمْرَو بْنَ الْعَاصِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مِنْ ‏ ‏صَالِحِي ‏ ‏قُرَيْشٍ ‏ ‏قَالَ ‏ ‏وَزَادَ ‏ ‏عَبْدُ الْجَبَّارِ بْنُ وَرْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏قَالَ ‏ ‏نِعْمَ أَهْلُ الْبَيْتِ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَأَبُو عَبْدِ اللَّهِ ‏ ‏وَأُمُّ عَبْدِ اللَّهِ ‏","","",""],[1311,1311,"","আমরা ঈশ্বরের মহিমায় আমার সাথে যা ঘটেছে তার জন্য আমরা বাপ্তাইজিত হয়েছি। তার বাবার ইচ্ছা ছিল সে যেন তার মৃত্যুর উপর দয়া করে থাকে, সে বলেছিল আমরা নাকি গৌরবের সাথে আছি। ঈশ্বরের প্রেম, তার কাছে অনেক লম্বা, ধূসর স্বাদ আছে, আমাদের মধ্যে যে কিনা আমাদের চেয়ে দ্রুত এগিয়ে এসেছে, আমি এটা তার কাছে প্রার্থনা করি এবং তিনি তার কাছে পৌঁছে দেন","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَنَحْنُ حُرُمٌ فَأُهْدِيَ لَهُ طَيْرٌ ‏ ‏وَطَلْحَةُ ‏ ‏رَاقِدٌ فَمِنَّا مَنْ أَكَلَ وَمِنَّا مَنْ ‏ ‏تَوَرَّعَ ‏ ‏فَلَمْ يَأْكُلْ فَلَمَّا اسْتَيْقَظَ ‏ ‏طَلْحَةُ ‏ ‏وَفَّقَ مَنْ أَكَلَهُ وَقَالَ ‏ ‏أَكَلْنَاهُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1312,1312,"","আমরা সারাজীবন ধরে তার বাবার পেইন্টার হওয়ার কথা বলেছি, ঈশ্বর, তারপর বল তোমার ভাই, একবার তোমার কাজিনকে দিয়ে দিবে, কখনো বলবে না ঈশ্বর এটা করেছেন আর তাই করবে না। তিনি বলেন, যদি তার থাকার প্রয়োজন হয়, তাহলে তাকে তার মৃত্যু হতে হবে না ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏عُمَرُ ‏ ‏طَلْحَةَ بْنَ عُبَيْدِ اللَّهِ ‏ ‏ثَقِيلًا فَقَالَ مَا لَكَ يَا أَبَا فُلَانٍ لَعَلَّكَ سَاءَتْكَ ‏ ‏إِمْرَةُ ‏ ‏ابْنِ عَمِّكَ يَا أَبَا فُلَانٍ قَالَ لَا إِلَّا أَنِّي سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا مَا مَنَعَنِي أَنْ أَسْأَلَهُ عَنْهُ إِلَّا الْقُدْرَةُ عَلَيْهِ حَتَّى مَاتَ سَمِعْتُهُ يَقُولُ إِنِّي لَأَعْلَمُ كَلِمَةً لَا يَقُولُهَا عَبْدٌ عِنْدَ مَوْتِهِ إِلَّا أَشْرَقَ لَهَا لَوْنُهُ وَنَفَّسَ اللَّهُ عَنْهُ ‏ ‏كُرْبَتَهُ ‏ ‏قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنِّي لَأَعْلَمُ مَا هِيَ قَالَ وَمَا هِيَ قَالَ تَعْلَمُ كَلِمَةً أَعْظَمَ مِنْ كَلِمَةٍ أَمَرَ بِهَا عَمَّهُ عِنْدَ الْمَوْتِ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ قَالَ ‏ ‏طَلْحَةُ ‏ ‏صَدَقْتَ هِيَ وَاللَّهِ هِيَ ‏","","",""],[1313,1313,"","আমরা শুনানির বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ قَالَ ‏ ‏قَيْسٌ ‏ ‏رَأَيْتُ ‏ ‏طَلْحَةَ ‏ ‏يَدُهُ شَلَّاءُ وَقَى بِهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏","","",""],[1314,1314,"","আমরা আমার উপহারের কথা বলেছিলাম যে আমরা একটা ক্র্যাডেল নিয়ে যাব, আমার বাবার সাথে ঈশ্বর তাকে তোমার মত করে পার হতে দেখেছে, বাবা, তোমার কাজিনের মানে বাবা না বলে এবং সে আমার বাবাও আমার বাবার মত। তার কথা শুনে আমি বলব যে আমার নিজের মৃত্যু হয়েছে। এমনকি এই ওষুধটিও মারা গেছে। ঈশ্বরের আছে, আমি যা করছি তা কি?","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَآهُ كَئِيبًا فَقَالَ مَا لَكَ يَا ‏ ‏أَبَا مُحَمَّدٍ ‏ ‏كَئِيبًا لَعَلَّهُ سَاءَتْكَ ‏ ‏إِمْرَةُ ‏ ‏ابْنِ عَمِّكَ ‏ ‏يَعْنِي ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَ لَا وَأَثْنَى عَلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَلَكِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ كَلِمَةٌ لَا يَقُولُهَا عَبْدٌ عِنْدَ مَوْتِهِ إِلَّا فَرَّجَ اللَّهُ عَنْهُ كُرْبَتَهُ وَأَشْرَقَ لَوْنُهُ فَمَا مَنَعَنِي أَنْ أَسْأَلَهُ عَنْهَا إِلَّا الْقُدْرَةُ عَلَيْهَا حَتَّى مَاتَ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنِّي لَأَعْلَمُهَا فَقَالَ لَهُ ‏ ‏طَلْحَةُ ‏ ‏وَمَا هِيَ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏هَلْ تَعْلَمُ كَلِمَةً هِيَ أَعْظَمَ مِنْ كَلِمَةٍ أَمَرَ بِهَا عَمَّهُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ ‏ ‏طَلْحَةُ ‏ ‏هِيَ وَاللَّهِ هِيَ ‏","","",""],[1315,1315,"","আমরা ইশ্বরের সাথে কথা বলেছি, কিন্তু আমি অসভ্য ভালুক হিসেবে ক্লান্ত। একজন লোক বলে যে তার বাবা আছে যে আমাকে তার জীবনের জন্য ঈশ্বরের কাছে দিতে পারবে। আমাদের মধ্যে ঈর্ষা আছে। আমরা আপনার ঈর্ষার আগুন পেয়েছি। যে ঘটনাগুলো আমরা কখনো দেখি নি, সে ঈশ্বরের অনুগ্রহের ব্যাপারে কিছুই শুনেনি। সে আমাকে বলেছে চলে গেছে, এমনকি সে মুক্ত হয়ে গেছে এবং বলে আমরা তাকে হারিয়ে ফেলেছি। আমরা ভয় পাচ্ছি সে আগে আমরা যাওয়ার আগে এবং তারপর আমরা আগে চলে যাই। সাক্ষীরা ঈশ্বরের কাছে বলেছে, এটা আমাদের ভাইদের কবর।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مَعْنٍ الْغِفَارِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏دَاوُدُ بْنُ خَالِدِ بْنِ دِينَارٍ ‏ ‏أَنَّهُ ‏ ‏مَرَّ هُوَ وَرَجُلٌ يُقَالُ لَهُ ‏ ‏أَبُو يُوسُفَ ‏ ‏مِنْ ‏ ‏بَنِي تَيْمٍ ‏ ‏عَلَى ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ قَالَ لَهُ ‏ ‏أَبُو يُوسُفَ ‏ ‏إِنَّا لَنَجِدُ عِنْدَ غَيْرِكَ مِنْ الْحَدِيثِ مَا لَا نَجِدُهُ عِنْدَكَ فَقَالَ أَمَا إِنَّ عِنْدِي حَدِيثًا كَثِيرًا وَلَكِنَّ ‏ ‏رَبِيعَةَ بْنَ الْهُدَيْرِ ‏ ‏قَالَ ‏ ‏وَكَانَ يَلْزَمُ ‏ ‏طَلْحَةَ بْنَ عُبَيْدِ اللَّهِ ‏ ‏إِنَّهُ لَمْ يَسْمَعْ ‏ ‏طَلْحَةَ ‏ ‏يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا قَطُّ غَيْرَ حَدِيثٍ وَاحِدٍ ‏ ‏قَالَ ‏ ‏رَبِيعَةُ بْنُ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏قُلْتُ لَهُ وَمَا هُوَ ‏ ‏قَالَ قَالَ لِي ‏ ‏طَلْحَةُ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏أَشْرَفْنَا ‏ ‏عَلَى ‏ ‏حَرَّةِ وَاقِمٍ ‏ ‏قَالَ فَدَنَوْنَا مِنْهَا فَإِذَا قُبُورٌ ‏ ‏بِمَحْنِيَّةٍ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ قُبُورُ إِخْوَانِنَا هَذِهِ قَالَ ‏ ‏قُبُورُ أَصْحَابِنَا ثُمَّ خَرَجْنَا حَتَّى إِذَا جِئْنَا قُبُورَ الشُّهَدَاءِ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ قُبُورُ إِخْوَانِنَا ‏","","",""],[1316,1316,"","আমরা তোমার বিষের দাসের কথা বলেছি... ...তার বাবার একটা টাকোরের সাথে... ...যে বলেছে আমরা আমার বাবার ভদ্র। আমরা তোমাকে প্রার্থনা করতে বলছি। তাকে পেয়ে গেছে, সে শেষ খুন করবে, সে কখনো বলতে পারবে না, সে একবার করে।","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي وَالدَّوَابُّ تَمُرُّ بَيْنَ أَيْدِينَا فَذَكَرْنَا ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مِثْلُ ‏ ‏مُؤْخِرَةِ الرَّحْلِ ‏ ‏تَكُونُ بَيْنَ يَدَيْ أَحَدِكُمْ ثُمَّ لَا يَضُرُّهُ مَا مَرَّ عَلَيْهِ ‏ ‏وَقَالَ ‏ ‏عُمَرُ ‏ ‏مَرَّةً بَيْنَ يَدَيْهِ ‏","","",""],[1317,1317,"","আমরা একটি হাত দিয়ে কথা বলেছি যে আমরা পৃথিবীর সবচেয়ে মূল্যবান একটি দাড়ির উপর একটি সম্মান সঙ্গে কথা করেছি। ঈশ্বরের অনুগ্রহে সে তার পালকগুলো মারা গেল, আর তাকে ঈশ্বরের হাতে যেতে বলা হয়েছিল যে সে তার বিছানায় মারা গেছে, এটা ঈশ্বরের অনুগ্রহের জন্য, তাকে করতে হবে এবং সে মারা যাবে। ঈশ্বর তাকে তা করতে বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏نَزَلَ ‏ ‏رَجُلَانِ مِنْ أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏عَلَى ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏فَقُتِلَ أَحَدُهُمَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ مَكَثَ الْآخَرُ بَعْدَهُ سَنَةً ثُمَّ مَاتَ عَلَى فِرَاشِهِ فَأُرِيَ ‏ ‏طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏أَنَّ الَّذِي مَاتَ عَلَى فِرَاشِهِ دَخَلَ الْجَنَّةَ قَبْلَ الْآخَرِ بِحِينٍ فَذَكَرَ ذَلِكَ ‏ ‏طَلْحَةُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمْ مَكَثَ فِي الْأَرْضِ بَعْدَهُ قَالَ حَوْلًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى أَلْفًا وَثَمَانِ مِائَةِ صَلَاةٍ وَصَامَ رَمَضَانَ ‏","","",""],[1318,1318,"","আমরা আমার উপহারের ব্যাপারে কথা বলেছি যে তার বাবার সাথে তার ভালোবাসা আছে। আমি ঈশ্বরের সাথে লড়াই করছি। নীরব বলার সময়, সে বলেছিল তারা তাকে মারতে চায় না, সে বলছে আমি তাকে হারাতে চাই না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏طَلْحَةَ بْنَ عُبَيْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏جَاءَ ‏ ‏أَعْرَابِيٌّ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَا الْإِسْلَامُ قَالَ ‏ ‏خَمْسُ صَلَوَاتٍ فِي يَوْمٍ وَلَيْلَةٍ قَالَ هَلْ عَلَيَّ غَيْرُهُنَّ قَالَ لَا وَسَأَلَهُ عَنْ الصَّوْمِ فَقَالَ صِيَامُ رَمَضَانَ قَالَ هَلْ عَلَيَّ غَيْرُهُ قَالَ لَا قَالَ وَذَكَرَ الزَّكَاةَ قَالَ هَلْ عَلَيَّ غَيْرُهَا قَالَ لَا قَالَ وَاللَّهِ لَا أَزِيدُ عَلَيْهِنَّ وَلَا أَنْقُصُ مِنْهُنَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَفْلَحَ إِنْ صَدَقَ ‏","","",""],[1319,1319,"","আমরা দুই বছর ধরে আমার টাকার কথা বলেছি আপনার টাকা অথবা আমি ঈশ্বরের আশীর্বাদ বলে যে মঙ্গলভাব এবং আনন্দের আনন্দ পালনকর্তার উপর বর্তায় অবতীর্ণ হয়েছে প্রভুর অনুগ্রহের সাথে এটা হবে... ...আর যদি সে তাকে বলে আমরা তাকে যেতে না দেই, সে বলবে আমরা তাকে যেতে দেব না।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسٍ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏لِعَبْدِ الرَّحْمَنِ ‏ ‏وَطَلْحَةَ ‏ ‏وَالزُّبَيْرِ ‏ ‏وَسَعْدٍ ‏ ‏نَشَدْتُكُمْ ‏ ‏بِاللَّهِ الَّذِي تَقُومُ بِهِ السَّمَاءُ وَالْأَرْضُ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً الَّذِي بِإِذْنِهِ تَقُومُ ‏ ‏أَعَلِمْتُمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّا لَا نُورَثُ مَا تَرَكْنَا ‏ ‏صَدَقَةٌ ‏ ‏قَالُوا اللَّهُمَّ نَعَمْ ‏","","",""],[1320,1320,"","আমরা এক সুখী অপরাধীর ছেলে যে আমার সাথে দয়া করে কথা বলেছে, তার বাবা বলেছিলেন আমরা একজন ভালো প্রভুর গৌরব নিয়ে এসেছি এবং আমাদের যুদ্ধ আছে যার স্বাদ আছে। তুমি যখন উঠে যেতে, তখন তুমি দ্রুত উঠে এসে, আর আমি রাজী হয়েছো যে আমি লর্ডের বার্তাবাহকের সাথে খেতে যাই আর বলে যে এটা করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏وَنَحْنُ حُرُمٌ فَأُهْدِيَ لَهُ طَيْرٌ ‏ ‏وَطَلْحَةُ ‏ ‏رَاقِدٌ فَمِنَّا مَنْ أَكَلَ وَمِنَّا مَنْ ‏ ‏تَوَرَّعَ ‏ ‏فَلَمَّا اسْتَيْقَظَ ‏ ‏طَلْحَةُ ‏ ‏وَفَّقَ مَنْ أَكَلَهُ وَقَالَ ‏ ‏أَكَلْنَاهُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1321,1321,"","আমরা দুই বছর ধরে তোমাকে বিষ প্রয়োগ করেছি... ...তার বাবার আদেশে মুসা বেনের সাথে যুদ্ধ করে। আমরা যে ভ্রমণকারীদের কথা বলেছি, আমরা আর আমাদের অনেকে খুশি যে পৃথিবীর কত মানুষ আছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَسْتُرُ الْمُصَلِّيَ قَالَ ‏ ‏مِثْلُ ‏ ‏آخِرَةِ الرَّحْلِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[1322,1322,"","আমরা মুসার মৃত্যুর কথা বলেছি, বাবার মৃত্যুর সমাধান করার চেষ্টা করছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার শক্তির জন্য তাকে আত্মসমর্পণ করবেন। যে কেউ একজন সেই-ই যে তাকে অনুসরণ করে আর সে তিনিই সেই ব্যক্তি যিনি হলেন সেই সেই ব্যক্তি, যে-ই বা তিনিই । আমি মনে করি আপনি যা বলছেন, তা ঈশ্বর কি জানেন? এটা করতে হবে, আমার মনে হয় আমি এটা নিয়ে নেব যখন আমি বলবো এটা কি জিনিস।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَوْمٍ فِي رُءُوسِ النَّخْلِ فَقَالَ مَا يَصْنَعُ هَؤُلَاءِ قَالُوا يُلَقِّحُونَهُ يَجْعَلُونَ الذَّكَرَ فِي الْأُنْثَى قَالَ مَا أَظُنُّ ذَلِكَ يُغْنِي شَيْئًا فَأُخْبِرُوا بِذَلِكَ فَتَرَكُوهُ فَأُخْبِرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنْ كَانَ يَنْفَعُهُمْ فَلْيَصْنَعُوهُ فَإِنِّي إِنَّمَا ظَنَنْتُ ظَنًّا فَلَا تُؤَاخِذُونِي بِالظَّنِّ وَلَكِنْ إِذَا أَخْبَرْتُكُمْ عَنْ اللَّهِ عَزَّ وَجَلَّ بِشَيْءٍ فَخُذُوهُ فَإِنِّي لَنْ أَكْذِبَ عَلَى اللَّهِ شَيْئًا ‏","","",""],[1323,1323,"","আমরা একটা দানবের কথা বলেছিলাম, কিন্তু তারপর আমাকে যেতে হবে। আমার বাবা বলেছিলেন, কিভাবে আপনি প্রার্থনা করবেন যে তারা একটা বধির উপত্যকায় পৌঁছেছেন। আপনি ভাল মানুষ। আপনি কি? আমি আপনি একটি দৈত্যের কথা বলতে পারেন, আমি আপনি একটি ভাল কথা বলতে হবে, আমি আপনি একটি ভাল কথা বলতে হবে. আমি আপনি একটি ভাল আপনি একটি কথা বলা আছে. আমি আপনি একটি ভাল আপনি একটি ভাল কথা বলা আছে. আমি আপনি একটি ভাল. আমি আপনি যে আমি যেতে হবে. আমি যেতে হবে. আমি আপনি যে আমি আপনি একটি ভাল. আমি যেতে হবে. আমি আপনি একটি পেয়েছিলাম. আমি যে আছে. আমি আপনি একটি ভাল আপনি একটি পেয়েছিলাম. আমি আপনি একটি পেয়েছিলাম. আমি আপনি যেতে হবে. আমি আপনি কি. আমি আপনি একটি পেয়েছিলাম. আমি আপনি একটি পেয়েছিলাম. আমি আপনি একটি পেয়েছিলাম. আমি আপনি একটি পেয়েছিলাম. আমি আপনি একটি পেয়েছিলাম. আপনি একটি পেয়েছিলাম. আপনি, আমি যে. আমি আপনি একটি পেয়েছিলাম. আপনি একটি পেয়েছিলাম. আপনি একটি পেয়েছিলাম. আমি একটি পেয়েছিলাম. আপনি একটি পেয়েছিলাম. আপনি একটি পেয়েছিলাম. আপনি একটি পেয়েছিলাম. একজন ভাল দাস যে তোমার ভালো বিশ্বাস আছে তাই তাকে... ...এবং আশীর্বাদ করে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَمِّعُ بْنُ يَحْيَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ الصَّلَاةُ عَلَيْكَ قَالَ قُلْ ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ ‏","","",""],[1324,1324,"","আমি কিভাবে একটা কুত্তার ছেলে হয়ে গেছি, আমার বাবার দাদা তার কাছে প্রার্থনা করেছে আর সে বলেছে যে ঈশ্বর কি করেছেন, বিশ্বাস আর শান্তি আর শান্তি। আল্লাহ এবং আল্লাহ এর শান্তি.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ سُفْيَانَ الْمَدَايِنِيُّ ‏ ‏حَدَّثَنِي ‏ ‏بِلَالُ بْنُ يَحْيَى بْنِ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا رَأَى الْهِلَالَ قَالَ ‏ ‏اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْيُمْنِ وَالْإِيمَانِ وَالسَّلَامَةِ وَالْإِسْلَامِ رَبِّي وَرَبُّكَ اللَّهُ ‏","","",""],[1325,1325,"","আমরা তার বাবার ভদ্র আচরণের যুদ্ধে আপনার বিষের সবচেয়ে ভাল কথা বলেছি, তাকে বলতেই হবে যে আপনার একজন শেষ ট্রাভেলার আর তারপর সে এসে পড়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَجْعَلُ أَحَدُكُمْ بَيْنَ يَدَيْهِ مِثْلَ ‏ ‏مُؤْخِرَةِ الرَّحْلِ ‏ ‏ثُمَّ ‏ ‏يُصَلِّي ‏","","",""],[1326,1326,"","আমরা কথা বলেছিলাম যে, মোশি কীভাবে তার প্রেম সম্বন্ধে শুনেছিলেন । তুমি এই বছর জয়ের জন্য লাইনে ছিলে, তুমি বলতে চাচ্ছ যে সে বলছে সে নাকি একটা স্বপ্নের ছেলে হবে। ছেড়ে দাও, কিন্তু আমি তোমাকে কখনোই বলতে দেবো না খোদা, আমি দুঃখিত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مُوسَى بْنَ طَلْحَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَرَرْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَخْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فَرَأَى أَقْوَامًا فِي رُءُوسِ النَّخْلِ يُلَقِّحُونَ النَّخْلَ فَقَالَ مَا يَصْنَعُ هَؤُلَاءِ قَالَ يَأْخُذُونَ مِنْ الذَّكَرِ فَيَحُطُّونَ فِي الْأُنْثَى يُلَقِّحُونَ بِهِ فَقَالَ مَا أَظُنُّ ذَلِكَ يُغْنِي شَيْئًا فَبَلَغَهُمْ فَتَرَكُوهُ وَنَزَلُوا عَنْهَا فَلَمْ تَحْمِلْ تِلْكَ ‏ ‏السَّنَةَ شَيْئًا فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا هُوَ ظَنٌّ ظَنَنْتُهُ إِنْ كَانَ يُغْنِي شَيْئًا فَاصْنَعُوا فَإِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ وَالظَّنُّ يُخْطِئُ وَيُصِيبُ وَلَكِنْ مَا قُلْتُ لَكُمْ قَالَ اللَّهُ عَزَّ وَجَلَّ فَلَنْ أَكْذِبَ عَلَى اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏فَذَكَرَهُ ‏","","",""],[1327,1327,"","আমরা একে অপরের কথা বলেছি, কিন্তু এটা জন্মের একটা গৌরব। আমাদের তাকে ৩ বছরের একটা ছেলে দিতে হবে, যে তার ছেলের মুখ ধরে রেখেছিল। সে বলছে তারা কে? আমার মনে হয় তারা শেষ কাজ করার পর তার দেখাশোনা করবে, আর তারপর সে তার তৃতীয় মৃত্যু দেখতে পাবে। মৃতরা হল তার নারী, আমি তাদের শেষটা দেখে নেবো, আমার মধ্যে ঢোকার জন্য ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন, আমি আত্মসমর্পণ করবো আর আমি তার সেরা কেউ হতে পারব না। এটা ছড়িয়ে দিন আর আপনি আস্তে আস্তে আস্তে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏طَلْحَةُ بْنُ يَحْيَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏أَنَّ ‏ ‏نَفَرًا ‏ ‏مِنْ ‏ ‏بَنِي عُذْرَةَ ‏ ‏ثَلَاثَةً أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمُوا قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏يَكْفِنِيهِمْ قَالَ ‏ ‏طَلْحَةُ ‏ ‏أَنَا قَالَ فَكَانُوا عِنْدَ ‏ ‏طَلْحَةَ ‏ ‏فَبَعَثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْثًا فَخَرَجَ أَحَدُهُمْ فَاسْتُشْهِدَ قَالَ ثُمَّ بَعَثَ بَعْثًا فَخَرَجَ فِيهِمْ آخَرُ فَاسْتُشْهِدَ قَالَ ثُمَّ مَاتَ الثَّالِثُ عَلَى فِرَاشِهِ قَالَ ‏ ‏طَلْحَةُ ‏ ‏فَرَأَيْتُ هَؤُلَاءِ الثَّلَاثَةَ الَّذِينَ كَانُوا عِنْدِي فِي الْجَنَّةِ فَرَأَيْتُ الْمَيِّتَ عَلَى فِرَاشِهِ أَمَامَهُمْ وَرَأَيْتُ الَّذِي اسْتُشْهِدَ أَخِيرًا يَلِيهِ وَرَأَيْتُ الَّذِي اسْتُشْهِدَ أَوَّلَهُمْ آخِرَهُمْ قَالَ فَدَخَلَنِي مِنْ ذَلِكَ قَالَ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا أَنْكَرْتَ مِنْ ذَلِكَ لَيْسَ أَحَدٌ أَفْضَلَ عِنْدَ اللَّهِ مِنْ مُؤْمِنٍ يُعَمَّرُ فِي الْإِسْلَامِ لِتَسْبِيحِهِ وَتَكْبِيرِهِ وَتَهْلِيلِهِ ‏","","",""],[1328,1328,"","আমরা এ নিয়ে কথা বলেছি কিন্তু আমার সাথে মঙ্গলভাব আছে। তাকে আমার পরিতৃপ্তি খুঁজে বের করতে হবে, যারা তার পতাকা জিতেছে তাদের প্রতি সম্মান জানাতে। বলতেই হচ্ছে আমাদের এটা করতে হবে. আপনি বলতে চান আমি বলতে চাই আমি যা শুনতে চাই তা হল আপনি আমার কথা শোনেন নি অথবা আমি ঈশ্বরের নামে কসম করে বলছি, সে আমাকে বলবে না যে আমি শুধু বলি, আমি তাকে বলেছিলাম, তিনি যেন তার বিশ্বাসকে ক্ষমা করেন বা জয় করেন । একটা পন্ড হয়ে একটা প্রাণকে মেরে ফেলে, যা তাকে মেরে ফেলেছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ بْنُ عَبِيدَةَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مُجَبَّرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَشْرَفَ عَلَى الَّذِينَ حَصَرُوهُ فَسَلَّمَ عَلَيْهِمْ فَلَمْ يَرُدُّوا عَلَيْهِ فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَفِي الْقَوْمِ ‏ ‏طَلْحَةُ ‏ ‏قَالَ ‏ ‏طَلْحَةُ ‏ ‏نَعَمْ قَالَ فَإِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ أُسَلِّمُ عَلَى قَوْمٍ أَنْتَ فِيهِمْ فَلَا تَرُدُّونَ قَالَ قَدْ رَدَدْتُ قَالَ مَا هَكَذَا الرَّدُّ أُسْمِعُكَ وَلَا تُسْمِعُنِي يَا ‏ ‏طَلْحَةُ ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ أَسَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُحِلُّ دَمَ الْمُسْلِمِ إِلَّا وَاحِدَةٌ مِنْ ثَلَاثٍ أَنْ يَكْفُرَ بَعْدَ إِيمَانِهِ أَوْ يَزْنِيَ بَعْدَ إِحْصَانِهِ أَوْ يَقْتُلَ نَفْسًا فَيُقْتَلَ بِهَا قَالَ اللَّهُمَّ نَعَمْ فَكَبَّرَ ‏ ‏عُثْمَانُ ‏ ‏فَقَالَ ‏ ‏وَاللَّهِ مَا أَنْكَرْتُ اللَّهَ مُنْذُ عَرَفْتُهُ وَلَا زَنَيْتُ فِي جَاهِلِيَّةٍ وَلَا إِسْلَامٍ وَقَدْ تَرَكْتُهُ فِي الْجَاهِلِيَّةِ تَكَرُّهًا وَفِي الْإِسْلَامِ تَعَفُّفًا وَمَا قَتَلْتُ نَفْسًا يَحِلُّ بِهَا قَتْلِي ‏","","",""],[1329,1329,"","আমরা একটি সুখী দম্পতি লিখতে চেষ্টা করেছি, একটি জীবনী প্রেম দ্বারা বাপ্তাইজিত হওয়া থেকে আমরা এক কুকুরের সন্তান হতে চেয়ে ভাল কাজ করেছি। ঈশ্বর তাকে আশীর্বাদ করেছেন এবং ঈশ্বর তাকে উদ্ধার করেছেন। আমি ছিলাম একজন সুখী দম্পতি। আমি একজন সুখী দম্পতি, যে কিনা জীবনের প্রতি ভালোবাসা অর্জন করেছে। আমি তাকে পেয়েছি। আমি জানি, সে হচ্ছে আমার সন্তান। আমি কি তাকে বিয়ে করব? আমি জানি না, আমি কি তাকে আমি কি করতে পারি? আমি কি করি, আমি জানি না, আমি কি জানি না, আমি এটা একটা সুন্দর কাজ করতে পারি? আমি তার কোম্পানির ব্যাপারে নিশ্চিত, তারপর সে তার মুখ হারিয়ে ফেলে, তারপর তাদের দিকে সে ক্লান্ত হয়ে পড়ে, আর আমি আর আগের মত দেখতে পাই নি, সে আমাকে দেখে, তারপর সে আমার কাছে ফিরে আসল, তুমি ঈশ্বরের কাছে প্রার্থনা করেছিলে তুমি তাকে বলবে আমি তোমার কথা বলতে চাই, প্রভু, তারপর তাকে ঈশ্বরের পথে দেখা হবে। তারা আমাকে বলেছিল যে, তারা যখন মারা গিয়েছিল, তখন তারা ঈশ্বরকে বলেছিল, যখন তিনি মারা গিয়েছিলেন, তখন,","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏أَنَّ رَجُلَيْنِ قَدِمَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ إِسْلَامُهُمَا جَمِيعًا وَكَانَ أَحَدُهُمَا أَشَدَّ اجْتِهَادًا مِنْ صَاحِبِهِ فَغَزَا الْمُجْتَهِدُ مِنْهُمَا فَاسْتُشْهِدَ ثُمَّ مَكَثَ الْآخَرُ بَعْدَهُ سَنَةً ثُمَّ تُوُفِّيَ قَالَ ‏ ‏طَلْحَةُ ‏ ‏فَرَأَيْتُ فِيمَا يَرَى النَّائِمُ كَأَنِّي عِنْدَ بَابِ الْجَنَّةِ إِذَا أَنَا بِهِمَا وَقَدْ خَرَجَ خَارِجٌ مِنْ الْجَنَّةِ فَأَذِنَ لِلَّذِي تُوُفِّيَ الْآخِرَ مِنْهُمَا ثُمَّ خَرَجَ فَأَذِنَ لِلَّذِي اسْتُشْهِدَ ثُمَّ رَجَعَا إِلَيَّ فَقَالَا لِي ارْجِعْ فَإِنَّهُ لَمْ يَأْنِ لَكَ بَعْدُ فَأَصْبَحَ ‏ ‏طَلْحَةُ ‏ ‏يُحَدِّثُ بِهِ النَّاسَ فَعَجِبُوا لِذَلِكَ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مِنْ أَيِّ ذَلِكَ تَعْجَبُونَ قَالُوا يَا رَسُولَ اللَّهِ هَذَا كَانَ أَشَدَّ اجْتِهَادًا ثُمَّ اسْتُشْهِدَ فِي سَبِيلِ اللَّهِ وَدَخَلَ هَذَا الْجَنَّةَ قَبْلَهُ فَقَالَ أَلَيْسَ قَدْ مَكَثَ هَذَا بَعْدَهُ سَنَةً قَالُوا بَلَى وَأَدْرَكَ رَمَضَانَ فَصَامَهُ قَالُوا بَلَى وَصَلَّى كَذَا وَكَذَا سَجْدَةً فِي السَّنَةِ قَالُوا بَلَى قَالَ رَسُولُ اللَّهِ فَلَمَا بَيْنَهُمَا أَبْعَدُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏","","",""],[1330,1330,"","আমার কল্পনার গৌরব এবং তার গৌরবের মধ্যে দিয়ে আমার ভালোবাসা চলে গেছে বলে আমি তার কাছে একটা ছেলে সম্বন্ধে কথা বলেছিলাম । লেখকরা আমার সম্পর্কে গান গায়, যা আদালত বলেছে যে তিনি বলেছেন তিনি বলেছেন তিনি বলেছেন তিনি তাই করেছেন। আমরা লিখেছিলেন যে আমরা আমাদের বন্ধুত্বের উপর নির্ভর করবো না। আমি বলতে চাই যে আমি আমার বাবার সাথে শহরে এসেছি আর আমার বাবা আমার বন্ধু ছিল. কিন্তু আমি আপনার সাথে বসে আপনাকে একটা অনুগ্রহ করে বসবো যদি আমি দয়া করে। সিগার আমাদের সাথে দেখা করা বন্ধ করে দিয়েছে। আমি না হওয়া পর্যন্ত আমাদের লড়াই করতে আমরা শেষ করেছি। ঈশ্বর লিখেছিলেন যে, আমরা যেন কখনও আমাদের বন্ধুদের কাছে যাওয়া না - ও করি, যা আমরা আপনাদের এবং আপনাদের সকলের কাছে বলি । ঈশ্বরের অনুগ্রহে, আমি ঈশ্বরের অনুগ্রহ পেয়েছি, এমন একটা বই দিতে, যা আমরা সমাধান করতে এসেছি। ঈশ্বর তার প্রভুর ক্ষমতা আছে। তিনি বলেছিলেন, তিনি আমাদের ঈশ্বরের কাছে প্রার্থনা করেছিলেন, যেন তিনি আমাকে আত্মসমর্পণ করেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمُ بْنُ أَبِي أُمَيَّةَ أَبُو النَّضْرِ ‏ ‏قَالَ ‏ ‏جَلَسَ إِلَيَّ ‏ ‏شَيْخٌ ‏ ‏مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏فِي مَسْجِدِ ‏ ‏الْبَصْرَةِ ‏ ‏وَمَعَهُ صَحِيفَةٌ لَهُ فِي يَدِهِ ‏ ‏قَالَ وَفِي زَمَانِ ‏ ‏الْحَجَّاجِ ‏ ‏فَقَالَ لِي يَا عَبْدَ اللَّهِ أَتَرَى هَذَا الْكِتَابَ مُغْنِيًا عَنِّي شَيْئًا عِنْدَ هَذَا السُّلْطَانِ قَالَ فَقُلْتُ وَمَا هَذَا الْكِتَابُ قَالَ هَذَا كِتَابٌ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَهُ لَنَا أَنْ لَا ‏ ‏يُتَعَدَّى عَلَيْنَا فِي صَدَقَاتِنَا قَالَ فَقُلْتُ لَا وَاللَّهِ مَا أَظُنُّ أَنْ يُغْنِيَ عَنْكَ شَيْئًا وَكَيْفَ كَانَ شَأْنُ هَذَا الْكِتَابِ قَالَ قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏مَعَ أَبِي وَأَنَا غُلَامٌ شَابٌّ بِإِبِلٍ لَنَا نَبِيعُهَا وَكَانَ أَبِي صَدِيقًا ‏ ‏لِطَلْحَةَ بْنِ عُبَيْدِ اللَّهِ التَّيْمِيِّ ‏ ‏فَنَزَلْنَا عَلَيْهِ فَقَالَ لَهُ أَبِي اخْرُجْ مَعِي فَبِعْ لِي إِبِلِي هَذِهِ قَالَ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏نَهَى أَنْ يَبِيعَ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَكِنْ سَأَخْرُجُ مَعَكَ فَأَجْلِسُ وَتَعْرِضُ إِبِلَكَ فَإِذَا رَضِيتُ مِنْ رَجُلٍ وَفَاءً وَصِدْقًا مِمَّنْ سَاوَمَكَ أَمَرْتُكَ بِبَيْعِهِ قَالَ فَخَرَجْنَا إِلَى السُّوقِ فَوَقَفْنَا ظُهْرَنَا وَجَلَسَ ‏ ‏طَلْحَةُ ‏ ‏قَرِيبًا فَسَاوَمَنَا الرِّجَالُ حَتَّى إِذَا أَعْطَانَا رَجُلٌ مَا ‏ ‏نَرْضَى قَالَ لَهُ أَبِي أُبَايِعُهُ قَالَ نَعَمْ رَضِيتُ لَكُمْ وَفَاءَهُ فَبَايِعُوهُ فَبَايَعْنَاهُ فَلَمَّا قَبَضْنَا مَا لَنَا وَفَرَغْنَا مِنْ حَاجَتِنَا قَالَ أَبِي ‏ ‏لِطَلْحَةَ ‏ ‏خُذْ لَنَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِتَابًا أَنْ لَا ‏ ‏يُتَعَدَّى عَلَيْنَا فِي صَدَقَاتِنَا قَالَ فَقَالَ هَذَا لَكُمْ وَلِكُلِّ مُسْلِمٍ قَالَ عَلَى ذَلِكَ إِنِّي أُحِبُّ أَنْ يَكُونَ عِنْدِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِتَابٌ فَخَرَجَ حَتَّى جَاءَ بِنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ هَذَا الرَّجُلَ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏صَدِيقٌ لَنَا وَقَدْ أَحَبَّ أَنْ تَكْتُبَ لَهُ كِتَابًا لَا ‏ ‏يُتَعَدَّى عَلَيْهِ فِي صَدَقَتِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا لَهُ وَلِكُلِّ مُسْلِمٍ قَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ أُحِبُّ أَنْ يَكُونَ عِنْدِي مِنْكَ كِتَابٌ عَلَى ذَلِكَ قَالَ فَكَتَبَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا الْكِتَابَ ‏ ‏آخِرُ حَدِيثِ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[1331,1331,"","আমরা দুই বছর ধরে কথা বলেছি, সমবেদনার সাথে বসবাস করতে বাধ্য হয়ে বেঁচে থাকার জন্য। ঈশ্বর বলেছেন কেন আমরা পড়ে গেছি আর তারপর আমাকে মেরে ফেলতে হবে। আমরা ঋণ শোধ করেছি, আমরা করেছি, আর যখন আমি নিচে নামলাম, তখন আমি মাখনের ভালোর জন্য ঘুমে ক্লান্ত হয়ে পড়তাম। আমরা এটা চাই এবং যখন এটা পাস করে দেয়, তখন তুমি হবে","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏عَنِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ ‏} ‏قَالَ ‏ ‏الزُّبَيْرُ ‏ ‏أَيْ رَسُولَ اللَّهِ مَعَ خُصُومَتِنَا فِي الدُّنْيَا قَالَ نَعَمْ وَلَمَّا نَزَلَتْ ‏ { ‏ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنْ النَّعِيمِ ‏} ‏قَالَ ‏ ‏الزُّبَيْرُ ‏ ‏أَيْ رَسُولَ اللَّهِ أَيُّ نَعِيمٍ نُسْأَلُ عَنْهُ وَإِنَّمَا ‏ ‏يَعْنِي هُمَا الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ ‏ ‏قَالَ أَمَا إِنَّ ذَلِكَ سَيَكُونُ ‏","","",""],[1332,1332,"","দুই বছর ধরে আমরা আমার টাকা হারানোর কথা বলেছি... ...আমার ভাগ্যের কথা শুনে যে মিথ্যা আর আনন্দের সাথে প্রভুর অনুগ্রহে... সে বলে আমরা তাকে যেতে দেব না। সে বলবে আমরা তাকে যেতে দেব না।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَوْسٍ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏لِعَبْدِ الرَّحْمَنِ ‏ ‏وَطَلْحَةَ ‏ ‏وَالزُّبَيْرِ ‏ ‏وَسَعْدٍ ‏ ‏نَشَدْتُكُمْ ‏ ‏بِاللَّهِ الَّذِي تَقُومُ بِهِ السَّمَاءُ وَالْأَرْضُ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً الَّذِي بِإِذْنِهِ تَقُومُ ‏ ‏أَعَلِمْتُمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّا لَا نُورَثُ مَا تَرَكْنَا ‏ ‏صَدَقَةٌ ‏ ‏قَالَ قَالُوا اللَّهُمَّ نَعَمْ ‏","","",""],[1333,1333,"","আমরা তরুণদের কথা বলেছি, আল্লাহ এসে এসেছেন, তাকে তার মুখে গুলি করে তার মুখ দিয়ে বহন করতে হবে আর তারপর সে হল হলওয়েতে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَحْمِلَ الرَّجُلُ حَبْلًا فَيَحْتَطِبَ بِهِ ثُمَّ يَجِيءَ فَيَضَعَهُ فِي السُّوقِ فَيَبِيعَهُ ثُمَّ يَسْتَغْنِيَ بِهِ فَيُنْفِقَهُ عَلَى نَفْسِهِ خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ أَعْطَوْهُ أَوْ مَنَعُوهُ ‏","","",""],[1334,1334,"","বাবা আমার ব্যাপারে ভালো কাস্টমার পেয়ে আমরা কথা বলেছিলাম, ঈশ্বর তাকে জেনে গেছে আর সে একদিন তার বাবাকেও দিবে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏جَمَعَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَوَيْهِ يَوْمَ ‏ ‏أُحُدٍ ‏","","",""],[1335,1335,"","বাবার সাথে প্রতারণা করার সময় বাবার সাথে কথা বলেছিলাম, আমি আমার বাবার সাথে শান্তি নিয়ে যাচ্ছি... ...ঈশ্বরের কাছে আর এটা নিয়ে যাই যদি সে আমাকে নিতে দেয়। জানো আমার বাবা আমার মাথায় ভয় পেয়ে মারা গেছে আর সে ঈশ্বরের হাতে খুন হয়েছে। এটা বলে যে, আপনার বাবা ও মা রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏أَنْبَأَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏الْخَنْدَقِ ‏ ‏كُنْتُ أَنَا ‏ ‏وَعُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏فِي ‏ ‏الْأُطُمِ ‏ ‏الَّذِي فِيهِ نِسَاءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُطُمِ ‏ ‏حَسَّانَ ‏ ‏فَكَانَ يَرْفَعُنِي وَأَرْفَعُهُ فَإِذَا رَفَعَنِي عَرَفْتُ أَبِي حِينَ يَمُرُّ إِلَى ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏وَكَانَ يُقَاتِلُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏فَقَالَ مَنْ يَأْتِي ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَيُقَاتِلَهُمْ فَقُلْتُ لَهُ حِينَ رَجَعَ يَا ‏ ‏أَبَتِ ‏ ‏تَاللَّهِ إِنْ كُنْتُ لَأَعْرِفُكَ حِينَ تَمُرُّ ذَاهِبًا إِلَى ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَقَالَ يَا بُنَيَّ أَمَا وَاللَّهِ إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَجْمَعُ لِي أَبَوَيْهِ جَمِيعًا ‏ ‏يُفَدِّينِي بِهِمَا يَقُولُ فِدَاكَ أَبِي وَأُمِّي ‏","","",""],[1336,1336,"","আমাদের সময় শেষ হওয়ার পর বাবার সাথে কথা হয়েছে, শুধু একজন মানুষ আছে যে বলে যে তার আত্মা আছে, অথবা সে অনেক ভালো বলছে. ভাইরাস তার উপর নির্ভর করে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏سُلَيْمَانُ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏أَنَّ رَجُلًا حَمَلَ عَلَى فَرَسٍ يُقَالُ لَهَا غَمْرَةُ ‏ ‏أَوْ ‏ ‏غَمْرَاءُ ‏ ‏وَقَالَ فَوَجَدَ فَرَسًا ‏ ‏أَوْ مُهْرًا ‏ ‏يُبَاعُ فَنُسِبَتْ إِلَى تِلْكَ الْفَرَسِ ‏ ‏فَنُهِيَ عَنْهَا ‏","","",""],[1337,1337,"","আমরা আমার বাবার ছেলেকে নিয়ে আগে একটা মাখন হাতে তুলে দিয়েছিলাম। ঈশ্বরের দয়ায় প্রার্থনা করছি, আল্লাহ তা করেছেন, একসাথে, আমরা মৃতদের ঋতু পালন করব, আমি উঠে আসবো, তার জীবন আরো বেশী।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ جُنْدُبٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجُمُعَةَ ثُمَّ نَنْصَرِفُ ‏ ‏فَنَبْتَدِرُ ‏ ‏الْآجَامَ ‏ ‏فَلَا نَجِدُ إِلَّا قَدْرَ مَوْضِعِ أَقْدَامِنَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏الْآجَامُ هِيَ ‏ ‏الْآطَامُ ‏","","",""],[1338,1338,"","আমার বাবার সাথে আমার প্রেমে বাস করা নিয়ে আমরা কথা বলেছি। এটা আমার বাবার জন্য অনেক পুরনো। পর্দার উপর ছায়ার ছবি তোলার নিষেধের সেজন ্ যbrob সহযোগে তার পর্দার আড়ালে রেখে দাও , এই ঋণের পরিস্থিতি কবিদের নয়, যাকে তার হাতে পরাজিত করা হয়েছে, যতক্ষণ না তুমি তোমার ছেলের সাথে সিঁড়ির দিকে যেতে চাও।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏وَأَبُو مُعَاوِيَةَ شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَبَّ ‏ ‏إِلَيْكُمْ دَاءُ الْأُمَمِ قَبْلَكُمْ ‏ ‏الْحَسَدُ ‏ ‏وَالْبَغْضَاءُ وَالْبَغْضَاءُ هِيَ ‏ ‏الْحَالِقَةُ ‏ ‏حَالِقَةُ الدِّينِ لَا حَالِقَةُ الشَّعَرِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَا تُؤْمِنُوا حَتَّى تَحَابُّوا أَفَلَا أُنَبِّئُكُمْ بِشَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏","","",""],[1339,1339,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...যে কিনা আমার নিজের ভালবাসা নিয়ে এসেছে, তার জন্য আমি ঈশ্বরকে খুশি করতে বলেছি আমি ফিরে যাচ্ছি এবং আমি তার কাছ থেকে শুনেছি, কিন্তু আমি তার কাছ থেকে শুনেছি। আগুন.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا لِي لَا أَسْمَعُكَ تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا أَسْمَعُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏وَفُلَانًا وَفُلَانًا قَالَ أَمَا إِنِّي لَمْ أُفَارِقْهُ مُنْذُ أَسْلَمْتُ وَلَكِنِّي سَمِعْتُ مِنْهُ كَلِمَةً ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[1340,1340,"","আমরা বাবা-মা'র সাথে কথা বলেছি, বাবা, আমাদের সাথে খারাপ ছেলে ছিল। ঈশ্বরের ইচ্ছা, ঈশ্বর তা করেছেন এবং আমি তা করেছি, ঈশ্বরের আপনার সাথে থাকতে হবে, আমরা হতে পারব না, এমনকি সে যদি না হতও।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَدَّادٌ يَعْنِي ابْنَ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏غَيْلَانُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ ‏ ‏قُلْنَا ‏ ‏لِلزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏مَا جَاءَ بِكُمْ ضَيَّعْتُمْ الْخَلِيفَةَ حَتَّى قُتِلَ ثُمَّ جِئْتُمْ تَطْلُبُونَ بِدَمِهِ قَالَ ‏ ‏الزُّبَيْرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِنَّا قَرَأْنَاهَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ { ‏وَاتَّقُوا ‏ ‏فِتْنَةً ‏ ‏لَا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنْكُمْ خَاصَّةً ‏} ‏لَمْ نَكُنْ نَحْسَبُ أَنَّا أَهْلُهَا حَتَّى وَقَعَتْ مِنَّا حَيْثُ وَقَعَتْ ‏","","",""],[1341,1341,"","আমরা এমন এক ব্যক্তির কথা বলেছি, যে ভালোবাসার প্রতি প্রবল আগ্রহ প্রকাশ করেছে, ঈশ্বরকে প্রার্থনা করতে বলেছে, তাকে ভালোর হাত থেকে উদ্ধার করতে হবে না। প্রভু.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كُنَاسَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيِّرُوا الشَّيْبَ وَلَا تَشَبَّهُوا ‏ ‏بِالْيَهُودِ ‏","","",""],[1342,1342,"","আমাদের মধ্যে যদি এমন একটা রাত থাকে, তা হলে ঈশ্বর সেই রাত পর্যন্তই আত্মসমর্পণ করেছেন । ...আর সবচেয়ে অন্ধকার হল তার দৃষ্টি আমার কাছে বলতে বলা... ...আর যতক্ষণ না মানুষ রাজি হয় ততক্ষণ পর্যন্ত সে থেমে যায়. তার আর তার সাহায্যে... ...বারবারবে যাওয়ার আগে তোমার কলমে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏مَخْزُومِيٌّ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ إِنْسَانَ ‏ ‏قَالَ ‏ ‏وَأَثْنَى عَلَيْهِ خَيْرًا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ لَيْلَةٍ حَتَّى إِذَا كُنَّا عِنْدَ ‏ ‏السِّدْرَةِ ‏ ‏وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَرَفِ ‏ ‏الْقَرْنِ الْأَسْوَدِ ‏ ‏حَذْوَهَا ‏ ‏فَاسْتَقْبَلَ ‏ ‏نَخِبًا ‏ ‏بِبَصَرِهِ ‏ ‏يَعْنِي وَادِيًا ‏ ‏وَقَفَ حَتَّى اتَّفَقَ النَّاسُ كُلُّهُمْ ثُمَّ قَالَ ‏ ‏إِنَّ صَيْدَ ‏ ‏وَجٍّ ‏ ‏وَعِضَاهَهُ ‏ ‏حَرَمٌ مُحَرَّمٌ لِلَّهِ وَذَلِكَ قَبْلَ نُزُولِهِ ‏ ‏الطَّائِفَ ‏ ‏وَحِصَارِهِ ‏ ‏ثَقِيفَ ‏","","",""],[1343,1343,"","ঈশ্বর ঈশ্বর তাকে উদ্ধার করেছেন এবং তার শান্তি আমার কাছে আছে । যখন আমি প্রভুর অনুগ্রহের জন্য প্রার্থনা করলাম, ঈশ্বর তা দিয়েছেন এবং আমি আপনার টাক-কবগও করেছি, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তাঁর চেহারার জন্য তাকে ধন্যবাদ দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَوْمَئِذٍ ‏ ‏أَوْجَبَ ‏ ‏طَلْحَةُ ‏ ‏حِينَ صَنَعَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا صَنَعَ ‏ ‏يَعْنِي حِينَ بَرَكَ لَهُ ‏ ‏طَلْحَةُ ‏ ‏فَصَعِدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ظَهْرِهِ ‏","","",""],[1344,1344,"","আমরা দুটো উপায় নিয়ে কথা বলেছি, যা আমার বাবার মৃত্যুর ফলে আমরা বিশ্বাস করতে পারি যে আমাদের বাবার ছেলের আশীর্বাদ আছে। আমি আমার বাবাকে বলছি, আমার বাবা হতে হবে ভালো। মারা যান, তার ছেলেকে মেরে তাকে মেরে ফেলার নির্দেশ দেয়া হয়েছে। আমি শপথ করে বলছি, আমার মায়ের গ্রীষ্মের কথা বলছি, আমি তাকে জানি যে সে পারবে। তিনি তার সঙ্গে গিয়েছিলেন এবং বলেছিলেন যে, তিনি তার সঙ্গে বের হয়ে যান এবং এই কথাগুলো বলেন । আমি তার ভাইয়ের কাছে এসেছি, আসুন তাদের উপর একটা পতন ঘটে, তাই তাকে হত্যা করা হয়। অনেক সময় আমি আমার প্রাণ হারিয়েছি জয়ের জন্য। আমি মনে করি তারা আরো বড় হয়েছে। আমি যদি আমার জীবনের মূল্য বৃদ্ধি পায়, তাহলে আমি জানি, আমি কি, আমি কি এটা করতে পারি? আমি যদি আমার ভাই-বোনের কাছে ফিরে যাই, তাহলে আমি এটা করতে পারি, আমি জানি, আমি যদি আমি আমার জীবন ছেড়ে দেব। আমি আমার জীবন শেষ করতে চাই, আমি আমার জীবন, আমি আমার জীবন হারাতে চাই। আমি যদি আমার জীবনটা ঠিক করি, তাহলে আমি আমার জীবন শেষ করতে চাই, আমি যেন আমি আমার জীবন উপভোগ করি। আমি আমার জীবন উপভোগ করি, আমি আমার জীবন-------------------------------ও করি, আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি আমার জীবনও যেন আমি আমার জীবন পরিবর্তন করতে পারি। আমি আমার জীবন পরিবর্তন করতে পারি। আমি আমার জীবন পরিবর্তন করতে পারি। অন্য সবার চেয়ে, আমরা তাদের থামাতে সিদ্ধান্ত নিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏الزُّبَيْرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏أَقْبَلَتْ امْرَأَةٌ ‏ ‏تَسْعَى حَتَّى إِذَا كَادَتْ أَنْ تُشْرِفَ عَلَى الْقَتْلَى قَالَ فَكَرِهَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تَرَاهُمْ فَقَالَ ‏ ‏الْمَرْأَةَ الْمَرْأَةَ قَالَ ‏ ‏الزُّبَيْرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَتَوَسَّمْتُ أَنَّهَا أُمِّي ‏ ‏صَفِيَّةُ ‏ ‏قَالَ فَخَرَجْتُ ‏ ‏أَسْعَى إِلَيْهَا فَأَدْرَكْتُهَا قَبْلَ أَنْ تَنْتَهِيَ إِلَى الْقَتْلَى قَالَ ‏ ‏فَلَدَمَتْ ‏ ‏فِي صَدْرِي وَكَانَتْ امْرَأَةً ‏ ‏جَلْدَةً ‏ ‏قَالَتْ إِلَيْكَ لَا أَرْضَ لَكَ قَالَ فَقُلْتُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَزَمَ عَلَيْكِ قَالَ فَوَقَفَتْ وَأَخْرَجَتْ ثَوْبَيْنِ مَعَهَا فَقَالَتْ هَذَانِ ثَوْبَانِ جِئْتُ بِهِمَا لِأَخِي ‏ ‏حَمْزَةَ ‏ ‏فَقَدْ بَلَغَنِي مَقْتَلُهُ فَكَفِّنُوهُ فِيهِمَا قَالَ فَجِئْنَا بِالثَّوْبَيْنِ لِنُكَفِّنَ فِيهِمَا ‏ ‏حَمْزَةَ ‏ ‏فَإِذَا إِلَى جَنْبِهِ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَتِيلٌ قَدْ فُعِلَ بِهِ كَمَا فُعِلَ ‏ ‏بِحَمْزَةَ ‏ ‏قَالَ فَوَجَدْنَا ‏ ‏غَضَاضَةً ‏ ‏وَحَيَاءً أَنْ نُكَفِّنَ ‏ ‏حَمْزَةَ ‏ ‏فِي ثَوْبَيْنِ وَالْأَنْصَارِيُّ لَا كَفَنَ لَهُ فَقُلْنَا ‏ ‏لِحَمْزَةَ ‏ ‏ثَوْبٌ وَلِلْأَنْصَارِيِّ ثَوْبٌ فَقَدَرْنَاهُمَا فَكَانَ أَحَدُهُمَا أَكْبَرَ مِنْ الْآخَرِ فَأَقْرَعْنَا بَيْنَهُمَا فَكَفَّنَّا كُلَّ وَاحِدٍ مِنْهُمَا فِي الثَّوْبِ الَّذِي صَارَ لَهُ ‏","","",""],[1345,1345,"","আমরা ঐ গুরুর কথা বলেছিলাম যে মাখনটা পরতে বলেছে, সে বলছে যে সে একজন মানুষের রাজধানী ছিল... ...যে কিনা সম্ভবত লর্ডের প্রার্থনা আমার কাছে স্ট্যাচুর। আপনার প্রতিবেশী আমার জয় মিস করেছে এবং বলেছে, \"ঈশ্বর, আপনার ছেলে তাকে হত্যা করেছে\" আমাকে তার কাছে আমার পরিতৃপ্তি প্রদান করতে হবে, তারপর সে পর্যন্ত পানি অনুভব করতে হবে। কিন্তু ছেলেটি তার জন্য প্রার্থনা করেছিল আর আপনি দেখার আগে সে আত্মসমর্পণ করেছিল । ঈশ্বরের জয় হোক আর ঈশ্বরের কাছে, সে প্রভুর পক্ষে তার ভালোর পক্ষে আত্মসমর্পণ করেছে... ...যে বলেছে... এবং পাথর মারার পর আপনার মধ্যে এত গরমও নেই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏الزُّبَيْرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كَانَ يُحَدِّثُ أَنَّهُ خَاصَمَ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَدْ شَهِدَ ‏ ‏بَدْرًا ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏شِرَاجِ ‏ ‏الْحَرَّةِ ‏ ‏كَانَا يَسْتَقِيَانِ بِهَا كِلَاهُمَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اسْقِ ثُمَّ أَرْسِلْ إِلَى جَارِكَ فَغَضِبَ الْأَنْصَارِيُّ وَقَالَ يَا رَسُولَ اللَّهِ أَنْ كَانَ ابْنَ عَمَّتِكَ فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏لِلزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏اسْقِ ثُمَّ ‏ ‏احْبِسْ ‏ ‏الْمَاءَ حَتَّى يَرْجِعَ إِلَى ‏ ‏الْجَدْرِ ‏ ‏فَاسْتَوْعَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَئِذٍ ‏ ‏لِلزُّبَيْرِ ‏ ‏حَقَّهُ وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ ذَلِكَ أَشَارَ عَلَى ‏ ‏الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِرَأْيٍ أَرَادَ فِيهِ سَعَةً لَهُ وَلِلْأَنْصَارِيِّ فَلَمَّا أَحْفَظَ الْأَنْصَارِيُّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَوْعَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلزُّبَيْرِ ‏ ‏حَقَّهُ فِي صَرِيحِ الْحُكْمِ قَالَ ‏ ‏عُرْوَةُ ‏ ‏فَقَالَ ‏ ‏الزُّبَيْرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَاللَّهِ مَا أَحْسِبُ هَذِهِ الْآيَةَ أُنْزِلَتْ إِلَّا فِي ذَلِكَ ‏ { ‏فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنْفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا ‏}","","",""],[1346,1346,"","আমরা ঈশ্বরের ঈশ্বরের কথা বলেছি, আমরা সবচেয়ে খারাপের কথা বলেছি, আমার বাবার উপর বিজয় হচ্ছে প্রভুর অকুতোর যন্ত্রণা সম্পর্কে জানার জন্য। ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنِي ‏ ‏جُبَيْرُ بْنُ عَمْرٍو الْقُرَشِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعْدٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏مَوْلَى آلِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبِلَادُ بِلَادُ اللَّهِ وَالْعِبَادُ عِبَادُ اللَّهِ فَحَيْثُمَا أَصَبْتَ خَيْرًا فَأَقِمْ ‏","","",""],[1347,1347,"","বাবার বেঁচে থাকার চেয়ে বেশি কথা বলেছি, আমি শুনতে পেরে খুশি. ঈশ্বর বিচার সংক্রান্ত বিচারের প্রতি সমবেদনা দেখান এবং আমরা আপনার জন্য যা করেছি, সেটার প্রতি তিনি সমবেদনা দেখাননি । সাক্ষী, প্রভু।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنِي ‏ ‏جُبَيْرُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَعْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏مَوْلَى آلِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِعَرَفَةَ ‏ ‏يَقْرَأُ هَذِهِ الْآيَةَ ‏ { ‏شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُوا الْعِلْمِ قَائِمًا ‏ ‏بِالْقِسْطِ ‏ ‏لَا إِلَهَ إِلَّا هُوَ الْعَزِيزُ الْحَكِيمُ ‏} ‏وَأَنَا عَلَى ذَلِكَ مِنْ الشَّاهِدِينَ يَا رَبِّ ‏","","",""],[1348,1348,"","তার মা মাকে আমাদের কথা বলার সুযোগ করে দিয়েছিলেন আর ঈশ্বর দেখেছিলেন যে, ক্রেতাদের অতীত সম্বন্ধে রয়েছে । মা, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাঁর অনুগ্রহের জন্য প্রার্থনা করেছেন। তারা তিনটি জিনিস নিয়ে ব্যস্ত। আমি আমার বাবাকে বলেছি তুমি তার সাথে যা করতে, তা আমার বাবার কাছে করতে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَطَاءِ بْنِ إِبْرَاهِيمَ ‏ ‏مَوْلَى ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏وَجَدَّتِهِ ‏ ‏أُمِّ عَطَاءٍ ‏ ‏قَالَتَا ‏ ‏وَاللَّهِ لَكَأَنَّنَا نَنْظُرُ إِلَى ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حِينَ أَتَانَا عَلَى بَغْلَةٍ لَهُ بَيْضَاءَ فَقَالَ يَا ‏ ‏أُمَّ عَطَاءٍ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏نَهَى الْمُسْلِمِينَ أَنْ يَأْكُلُوا مِنْ لُحُومِ ‏ ‏نُسُكِهِمْ ‏ ‏فَوْقَ ثَلَاثٍ قَالَ فَقُلْتُ بِأَبِي أَنْتَ فَكَيْفَ نَصْنَعُ بِمَا أُهْدِيَ لَنَا فَقَالَ أَمَّا مَا أُهْدِيَ لَكُنَّ فَشَأْنَكُنَّ بِهِ ‏","","",""],[1349,1349,"","ঈশ্বর আমাকে আশীর্বাদ করেছেন বলে ঈশ্বর আমাকে আশীর্বাদ করেছেন । আমি বলেছি, ঈশ্বর যেমন এটা দেখেন, তিনি আত্মসমর্পণ করেছেন এবং আত্মসমর্পণ করেছেন, আমি তাদের বলেছি আমি তাকে ঈশ্বরের কাছে ফিরে আসতে দিতে পারি তার জন্য এবং তাকে বলতে","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَنْبَأَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كُنْتُ يَوْمَ الْأَحْزَابِ جُعِلْتُ أَنَا ‏ ‏وَعُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏مَعَ النِّسَاءِ فَنَظَرْتُ فَإِذَا أَنَا ‏ ‏بِالزُّبَيْرِ ‏ ‏عَلَى فَرَسِهِ يَخْتَلِفُ إِلَى ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثَةً ‏ ‏فَلَمَّا رَجَعَ قُلْتُ يَا ‏ ‏أَبَتِ رَأَيْتُكَ تَخْتَلِفُ قَالَ وَهَلْ رَأَيْتَنِي يَا بُنَيَّ قَالَ قُلْتُ نَعَمْ قَالَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ يَأْتِي ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَيَأْتِيَنِي بِخَبَرِهِمْ فَانْطَلَقْتُ فَلَمَّا رَجَعْتُ ‏ ‏جَمَعَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَوَيْهِ فَقَالَ فِدَاكَ أَبِي وَأُمِّي ‏","","",""],[1350,1350,"","ঈশ্বর আমাদের যথাসাধ্য চেষ্টা করেছিলেন । ঈশ্বরের কসম আমি কখনো শপথ করে বলব না, সে যা করেছে, তার জন্য সে কখনো তাকে বিভক্ত করেনি যতক্ষণ না পর্যন্ত সে ঈশ্বরের রাজকুমারের কাছে চিঠি লেখে। আমি তার লেখা পড়ার অনেক সময় পড়েছি যে, সে জয়ী হয়েছে। তার ভালবাসা থেকে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُقْبَةَ وَهُوَ عَبْدُ اللَّهِ بْنُ لَهِيعَةَ بْنِ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ الْمُغِيرَةِ بْنِ أَبِي بُرْدَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏سُفْيَانَ بْنَ وَهْبٍ الْخَوْلَانِيَّ ‏ ‏يَقُولُ ‏ ‏لَمَّا افْتَتَحْنَا ‏ ‏مِصْرَ ‏ ‏بِغَيْرِ عَهْدٍ قَامَ ‏ ‏الزُّبَيْرُ بْنُ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ يَا ‏ ‏عَمْرُو بْنَ الْعَاصِ ‏ ‏اقْسِمْهَا فَقَالَ ‏ ‏عَمْرٌو ‏ ‏لَا أَقْسِمُهَا فَقَالَ ‏ ‏الزُّبَيْرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَاللَّهِ لَتَقْسِمَنَّهَا كَمَا ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏وَاللَّهِ لَا أَقْسِمُهَا حَتَّى أَكْتُبَ إِلَى أَمِيرِ الْمُؤْمِنِينَ فَكَتَبَ إِلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَكَتَبَ إِلَيْهِ ‏ ‏عُمَرُ ‏ ‏أَنْ أَقِرَّهَا حَتَّى يَغْزُوَ مِنْهَا ‏ ‏حَبَلُ الْحَبَلَةِ ‏","","",""],[1351,1351,"","আমরা কথা বলেছি, আমার বাবা তার কাছে প্রার্থনা করেছেন আর ভালো কিছুর জন্য তার মায়ের ভালো আগ্রহ আর তার মায়ের কাছে ভালো কিছু আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَى ‏ ‏الزُّبَيْرَ ‏ ‏سَهْمًا وَأُمَّهُ سَهْمًا وَفَرَسَهُ ‏ ‏سَهْمَيْنِ ‏","","",""],[1352,1352,"","আমরা তোমার খেলা নিয়ে কথা বলেছি, আমরা বিয়ের আগে কারো সাথে বিয়ে করার চেয়ে ভাল কথা বলেছি, সে তাকে খুন করেনি, আর সে তাকে ছেড়ে দেয়নি, সে বলেছিল সে তোমার আত্মার বিশ্বাস নয়। আমরা তোমাকে ধরতে নিরাপদ, আমি সেই পাইলট যে তোমাকে খুন না করার জন্য লড়াই করছে আর তুমি কিভাবে ওকে মেরেছো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكٌ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏فَقَالَ أَقْتُلُ لَكَ ‏ ‏عَلِيًّا ‏ ‏قَالَ لَا وَكَيْفَ تَقْتُلُهُ وَمَعَهُ الْجُنُودُ قَالَ أَلْحَقُ بِهِ فَأَفْتِكُ بِهِ قَالَ لَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْإِيمَانَ ‏ ‏قَيْدُ ‏ ‏الْفَتْكِ ‏ ‏لَا يَفْتِكُ مُؤْمِنٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏مُبَارَكُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ ‏ ‏الزُّبَيْرَ بْنَ الْعَوَّامِ ‏ ‏فَقَالَ أَلَا أَقْتُلُ لَكَ ‏ ‏عَلِيًّا ‏ ‏قَالَ وَكَيْفَ تَسْتَطِيعُ قَتْلَهُ وَمَعَهُ النَّاسُ فَذَكَرَ مَعْنَاهُ ‏","","",""],[1353,1353,"","এক বছর ধরে আমরা এত নিষ্ঠুরভাবে কথা বলেছি যখন আমাদের হয়ত যেতে হবে। আমার বাবা আমার শ্বশুরকে আমার সাথে কথা বলতে বলেছিলেন, আমার পরিতৃপ্তি নিয়ে নয়, ঈশ্বরের সাথে কথা না বলতে। আত্মসমর্পণ কর কিন্তু আমি তার কথা শুনেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ لِأَبِي ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا لَكَ لَا تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَا فَارَقْتُهُ مُنْذُ أَسْلَمْتُ وَلَكِنِّي سَمِعْتُ مِنْهُ كَلِمَةً سَمِعْتُهُ يَقُولُ ‏ ‏مَنْ كَذَبَ عَلَيَّ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[1354,1354,"","আমরা অনেক সময় তার বাবার কথা বলেছি, তার বাবাকে একটা কুত্তির বাচ্চা খুঁজতে। ভগবান ঈশ্বরের কাছে প্রার্থনা করেছে যেন আমি তোমাদের একজনকে ভালবাসি। সে আমাকে কয়েকবার গান গায়।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَأْخُذَ أَحَدُكُمْ أَحْبُلَهُ فَيَأْتِيَ الْجَبَلَ فَيَجِيءَ بِحُزْمَةٍ مِنْ حَطَبٍ عَلَى ظَهْرِهِ فَيَبِيعَهَا فَيَسْتَغْنِيَ بِثَمَنِهَا خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ أَعْطَوْهُ أَوْ مَنَعُوهُ ‏","","",""],[1355,1355,"","আমরা আমাদের জীবনের চেয়ে সবচেয়ে ভাল লড়াই করেছি, কিন্তু আমাদের যুদ্ধ করার প্রয়োজন ছিল । আমি আপনাদের কাছে আপনাদের প্রমাণ করতে চাই যে, তারা আমাদের যে সালামকে কিভাবে খুঁজে পায়। আল-জাবির প্রতি অনুগত থাকার চেয়ে মহান হওয়ার চেয়েও বেশি কিছু ঘটেছে। আল-জাবির প্রতি অনুগত থাকার জন্য তিনি তার সাথে কথা বলেছিলেন যে, ঈশ্বর তাকে উদ্ধার করেছেন এবং তাকে উদ্ধার করেছেন। সে তোমাকে বলেছে, যখন আমরা তার সাথে কথা বলেছিলাম, আমার বাবা তার সাথে অনেক কথা বলেছে, সে তার সাথে থাকা অনেক কিছু একটা করে... মনে রেখ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَنَّ ‏ ‏يَعِيشَ بْنَ الْوَلِيدِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏مَوْلًى لِآلِ الزُّبَيْرِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏الزُّبَيْرَ بْنَ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَبَّ ‏ ‏إِلَيْكُمْ دَاءُ الْأُمَمِ قَبْلَكُمْ ‏ ‏الْحَسَدُ ‏ ‏وَالْبَغْضَاءُ ‏ ‏وَالْبَغْضَاءُ ‏ ‏هِيَ ‏ ‏الْحَالِقَةُ ‏ ‏لَا أَقُولُ تَحْلِقُ الشَّعْرَ وَلَكِنْ تَحْلِقُ الدِّينَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏أَوْ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَا تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا أَفَلَا أُنَبِّئُكُمْ بِمَا يُثَبِّتُ ذَلِكَ لَكُمْ أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ ‏ ‏أَنَّ ‏ ‏مَوْلًى لِآلِ الزُّبَيْرِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏الزُّبَيْرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَبَّ ‏ ‏إِلَيْكُمْ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِآلِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏الزُّبَيْرَ بْنَ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَبَّ ‏ ‏إِلَيْكُمْ ‏ ‏فَذَكَرَهُ ‏","","",""],[1356,1356,"","আমরা তোমাকে মারার ব্যাপারে কথা বলেছিলাম, সে বলল ঈশ্বর তার কাছে প্রার্থনা করেছেন আর সে তোমাকে আত্মসমর্পণ করবে.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ ‏ ‏لِلزُّبَيْرِ ‏ ‏أَلَا أَقْتُلُ لَكَ ‏ ‏عَلِيًّا ‏ ‏قَالَ كَيْفَ تَقْتُلُهُ قَالَ ‏ ‏أَفْتِكُ ‏ ‏بِهِ قَالَ لَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِيمَانُ ‏ ‏قَيْدُ ‏ ‏الْفَتْكِ ‏ ‏لَا ‏ ‏يَفْتِكُ ‏ ‏مُؤْمِنٌ ‏","","",""],[1357,1357,"","আমরা একটা ছেলের কথা বলেছিলাম যে সে কেন বলেছে সে এটা করেছে, তাহলে তুমি মারা যাবে, ঈশ্বরের অভিভাবক। আমি কখনোই ঘৃণা করি নি। আমরা অন্যদের কাছে ঋণী হয়ে পড়ি ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ السُّورَةُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ عِنْدَ رَبِّكُمْ ‏ ‏تَخْتَصِمُونَ ‏ } ‏قَالَ ‏ ‏الزُّبَيْرُ ‏ ‏أَيْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُكَرَّرُ عَلَيْنَا مَا كَانَ بَيْنَنَا فِي الدُّنْيَا مَعَ خَوَاصِّ الذُّنُوبِ قَالَ ‏ ‏نَعَمْ لَيُكَرَّرَنَّ عَلَيْكُمْ حَتَّى يُؤَدَّى إِلَى كُلِّ ذِي حَقٍّ حَقُّهُ فَقَالَ ‏ ‏الزُّبَيْرُ ‏ ‏وَاللَّهِ إِنَّ الْأَمْرَ لَشَدِيدٌ ‏","","",""],[1358,1358,"","আমরা কথা বলেছি কিভাবে আমরা সময় কাটাবো... ...জঙ্গলরা বলবে ভগবানের মাধ্যমে বিল্ডিংটা আল্লাহ্‌র নিকট দিয়ে হবে আর সে লর্ডের কাছে থাকবে বলেছেন দুই গ্রীষ্মের মধ্যে তাদের মধ্যে কেউ কেউ আগুন জ্বালায়।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏وَسَمِعْتُ ‏ ‏عِكْرِمَةَ ‏ { ‏وَإِذْ صَرَفْنَا إِلَيْكَ ‏} ‏وَقُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ { ‏نَفَرًا مِنْ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ ‏} ‏قَالَ ‏ ‏بِنَخْلَةَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْعِشَاءَ الْآخِرَةَ ‏ { ‏كَادُوا يَكُونُونَ عَلَيْهِ ‏ ‏لِبَدًا ‏ } ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏كَانَ ‏ ‏بَعْضُهُمْ عَلَى بَعْضٍ ‏ ‏كَاللِّبَدِ ‏ ‏بَعْضُهُ عَلَى بَعْضٍ ‏","","",""],[1359,1359,"","আমরা একটি ভালবাসা ছেলে কথা বলেছি যে বাবার সাথে কথা বলে আর সময় মত চলতে চেষ্টা করে। ঈশ্বর বললেন আমরা প্রভুর কাছে প্রার্থনা করছি তার কাছে এটা ঘটেছে এবং তিনি তা দিয়েছেন। আমাদের বুড়ো হওয়ার কথা অথবা বলে আমরা বুঝতে পারছি না কে আমাদের ভেতরে ঢুকতে দিচ্ছে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ جُنْدُبٍ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏الزُّبَيْرَ بْنَ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجُمُعَةَ ثُمَّ نُبَادِرُ فَمَا نَجِدُ مِنْ الظِّلِّ إِلَّا مَوْضِعَ أَقْدَامِنَا ‏ ‏أَوْ قَالَ فَلَا نَجِدُ مِنْ الظِّلِّ مَوْضِعَ أَقْدَامِنَا ‏","","",""],[1360,1360,"","আমরা আমার বাবার ব্যাপারে অনেক কথা বলেছি, কিন্তু ঈশ্বরের একটা স্বপ্ন আছে, আমি দুঃখিত, ঈশ্বরের দিন থেকে আমরা জানি তুমি তার মুখে কী আছো আর সে কিভাবে তোমার ভাগ্যের পাপী ছিল। এমনকি এটা উপর গণনা করা হয়নি.","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلِمَةَ ‏ ‏أَوْ ‏ ‏مَسْلَمَةَ ‏ ‏قَالَ ‏ ‏كَثِيرٌ ‏ ‏وَحِفْظِي ‏ ‏سَلِمَةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُنَا فَيُذَكِّرُنَا بِأَيَّامِ اللَّهِ حَتَّى نَعْرِفَ ذَلِكَ فِي وَجْهِهِ وَكَأَنَّهُ نَذِيرُ قَوْمٍ يُصَبِّحُهُمْ الْأَمْرُ ‏ ‏غُدْوَةً ‏ ‏وَكَانَ إِذَا كَانَ حَدِيثَ ‏ ‏عَهْدٍ ‏ ‏بِجِبْرِيلَ ‏ ‏لَمْ يَتَبَسَّمْ ضَاحِكًا حَتَّى يَرْتَفِعَ عَنْهُ ‏","","",""],[1361,1361,"","তারা ঈশ্বরের বার্তাবাহকের সাথে ঘুরে বেড়াত, সে প্রার্থনা করলো এবং একটা ছেলেকে অপমান করলো, যে কিনা কখনো ভুল বুঝেছে না। ভয় পেয়ে গেছি, এই দুর্গন্ধে আর মনে হচ্ছে শেষ বারের মত সে পড়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏قَالَ قَالَ ‏ ‏الزُّبَيْرُ بْنُ الْعَوَّامِ ‏ ‏نَزَلَتْ هَذِهِ الْآيَةُ وَنَحْنُ مُتَوَافِرُونَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَاتَّقُوا فِتْنَةً لَا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنْكُمْ خَاصَّةً ‏} ‏فَجَعَلْنَا نَقُولُ مَا هَذِهِ الْفِتْنَةُ وَمَا ‏ ‏نَشْعُرُ أَنَّهَا تَقَعُ حَيْثُ وَقَعَتْ ‏ ‏آخِرُ حَدِيثِ ‏ ‏الزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[1362,1362,"","আমরা আমার বাবার কথা বলেছিলাম যে হয়ত মারা যেতে পারে। ঘোড়াগুলো মারা গেছে। কয়েক বছর আগে ধরে অনুমান করা হচ্ছে যে আমি তাকে জিজ্ঞেস করবো এবং মনে করি সে শক্তিশালী। সে তোমার টাকা নিয়ে বের হয়ে যাবে, তারপর আমরা বসে দেখব আমরা কারা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏طَاوُسًا ‏ ‏عَنْ رَجُلٍ رَمَى الْجَمْرَةَ بِسِتِّ حَصَيَاتٍ ‏ ‏فَقَالَ ‏ ‏لِيُطْعِمْ قَبْضَةً مِنْ طَعَامٍ ‏ ‏قَالَ فَلَقِيتُ ‏ ‏مُجَاهِدًا ‏ ‏فَسَأَلْتُهُ وَذَكَرْتُ لَهُ قَوْلَ ‏ ‏طَاوُسٍ ‏ ‏فَقَالَ رَحِمَ اللَّهُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَمَا بَلَغَهُ قَوْلُ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏رَمَيْنَا الْجِمَارَ ‏ ‏أَوْ الْجَمْرَةَ ‏ ‏فِي حَجَّتِنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ جَلَسْنَا نَتَذَاكَرُ فَمِنَّا مَنْ قَالَ رَمَيْتُ بِسِتٍّ وَمِنَّا مَنْ قَالَ رَمَيْتُ بِسَبْعٍ وَمِنَّا مَنْ قَالَ رَمَيْتُ بِثَمَانٍ وَمِنَّا مَنْ قَالَ رَمَيْتُ بِتِسْعٍ فَلَمْ يَرَوْا بِذَلِكَ بَأْسًا ‏","","",""],[1363,1363,"","আমরা আমাদের সময় রক্ষা করেছি এবং সুখী ছেলেদের জন্য আমাদের সাথে ঘটতে যাচ্ছে, তার জন্য আমি একটি সুখী প্রতিজ্ঞা করেছি, তার শান্তি এবং তার শান্তি তার নিজের। আমি ভয় পাচ্ছি যে, তার মৃত্যুর জন্য আমি বেঁচে থাকতে ভয় পাচ্ছি। আমি তাকে সাহায্য করার জন্য তার সাথে লড়াই করছি। তিনি বললেন, \"ঈশ্বর, আমি খুশি হতে চাই, যেতে, বলতে চাই, প্রভু, আমার অনেক টাকা আছে। আমি আমার মেয়ে আমার টাকা সুপারিশ করছি, আমি যা বলেছি তা না করতে। আমি বললাম, আমি তাকে বলতে চাই, আমি তাকে সাহায্য করতে চাই। আমি এটা করতে চাই। আমি যদি আমার জীবনের জন্য অনেক টাকা চাই, আমি এটা করতে চাই। আমি এটা করতে চাই। আমি এটা করতে চাই। আমি তোমাকে বলবো। আমি যদি আমার কাছে বলি, আমি এটা করতে চাই, আমি এটা করতে চাই। আমি এটা করতে চাই। আমি শুধু আমার জন্য অনেক কিছু একটা বিষয় নিয়ে কথা বলি না। আমি যদি আমার মেয়ের সাথে লড়াই করি, আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি চাই, আমি চাই যে তুমি আমার মেয়েকে তোমার কাছে একটা ছোট কথা বলি না। সে যেভাবে বলে, বলো না। তৃতীয়টা অনেক বেশি তোমার টাকা খরচ করার সুযোগ আছে। আর তোমার ক্ষতির সুযোগ আছে তোমার হৃদয় ভেঙ্গে ফেলার। বাঁচা বা অন্য কাউকে বলে কাউকে বলে মানুষ বলা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ ‏ ‏عَنْ ‏ ‏ثَلَاثَةٍ مِنْ وَلَدِ ‏ ‏سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهِ ‏ ‏يَعُودُهُ ‏ ‏وَهُوَ مَرِيضٌ وَهُوَ ‏ ‏بِمَكَّةَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ قَدْ خَشِيتُ أَنْ أَمُوتَ بِالْأَرْضِ الَّتِي هَاجَرْتُ مِنْهَا كَمَا مَاتَ ‏ ‏سَعْدُ ابْنُ خَوْلَةَ ‏ ‏فَادْعُ اللَّهَ أَنْ يَشْفِيَنِي قَالَ اللَّهُمَّ اشْفِ ‏ ‏سَعْدًا ‏ ‏اللَّهُمَّ اشْفِ ‏ ‏سَعْدًا ‏ ‏اللَّهُمَّ اشْفِ ‏ ‏سَعْدًا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي مَالًا كَثِيرًا وَلَيْسَ لِي وَارِثٌ إِلَّا ابْنَةً ‏ ‏أَفَأُوصِي بِمَالِي كُلِّهِ قَالَ لَا قَالَ ‏ ‏أَفَأُوصِي بِثُلُثَيْهِ قَالَ لَا قَالَ ‏ ‏أَفَأُوصِي بِنِصْفِهِ قَالَ لَا قَالَ ‏ ‏أَفَأُوصِي بِالثُّلُثِ قَالَ ‏ ‏الثُّلُثُ وَالثُّلُثُ كَثِيرٌ إِنَّ نَفَقَتَكَ مِنْ مَالِكَ لَكَ ‏ ‏صَدَقَةٌ ‏ ‏وَإِنَّ نَفَقَتَكَ عَلَى عِيَالِكَ لَكَ ‏ ‏صَدَقَةٌ ‏ ‏وَإِنَّ نَفَقَتَكَ عَلَى أَهْلِكَ لَكَ ‏ ‏صَدَقَةٌ ‏ ‏وَإِنَّكَ أَنْ تَدَعَ أَهْلَكَ بِعَيْشٍ ‏ ‏أَوْ قَالَ بِخَيْرٍ ‏ ‏خَيْرٌ مِنْ أَنْ تَدَعَهُمْ ‏ ‏يَتَكَفَّفُونَ ‏ ‏النَّاسَ ‏","","",""],[1364,1364,"","আমরা আমার জীবনের মহান সময় অতিবাহিত হওয়ার পর আমার জীবনের মহিমা নিয়ে কথা বলেছি, একটি ভালো নাম খুঁজে পেতে সক্ষম হবার পর, একটি জীবন সীমা ছাড়িয়ে গেছে যা ধূসর থেকে বেরিয়ে এসেছে। আমি দুঃখিত যে তুমি তোমার ক্লাসে সৈনিক হতে পেরে খুশি এবং লোকজন তোমার বিশ্বাসে প্রতিদ্বন্দ্বিতা করছে। সে বলল, ঈশ্বর তার কাছে প্রার্থনা করেছেন যেন তিনি মুক্তির জন্য প্রার্থনা করেন এবং বললেন, ঈশ্বর তার প্রতি ভালোবাসা প্রকাশ করবেন। হালকা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ عَبْدُ الْكَبِيرِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ مِسْمَارٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏أَنَّ ‏ ‏أَخَاهُ ‏ ‏عُمَرَ ‏ ‏انْطَلَقَ إِلَى ‏ ‏سَعْدٍ ‏ ‏فِي غَنَمٍ لَهُ خَارِجًا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَلَمَّا رَآهُ ‏ ‏سَعْدٌ ‏ ‏قَالَ أَعُوذُ بِاللَّهِ مِنْ شَرِّ هَذَا الرَّاكِبِ فَلَمَّا أَتَاهُ قَالَ يَا ‏ ‏أَبَتِ أَرَضِيتَ أَنْ تَكُونَ أَعْرَابِيًّا فِي غَنَمِكَ وَالنَّاسُ يَتَنَازَعُونَ فِي الْمُلْكِ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَضَرَبَ ‏ ‏سَعْدٌ ‏ ‏صَدْرَ ‏ ‏عُمَرَ ‏ ‏وَقَالَ اسْكُتْ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ الْعَبْدَ التَّقِيَّ الْغَنِيَّ ‏ ‏الْخَفِيَّ ‏","","",""],[1365,1365,"","কিন্তু শোকের পর শোকের পর, শোকের পর আমি সেই অপরাধীর আদেশ পালন করব, যে - ব্যক্তি আপনার শান্তি কামনা করতে সাহায্য করবেন । বেন বেন থেকে আমার দুঃখ জনক বাবা তার কোন ক্ষতি করেনি. আর যদি এটা তার মৃত্যু পর্যন্ত তাকে আঘাত না করত, সে আমাকে দেখতে দেবে আমাকে কি করতে হবে এবং সে যা বলছে তা নিয়ে ঈশ্বরের কাছে যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ يَعْنِي ابْنَ مَعْمَرٍ ‏ ‏قَالَ حَدَّثَ ‏ ‏عَامِرُ بْنُ سَعْدٍ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏وَهُوَ أَمِيرٌ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَ سَبْعَ تَمَرَاتِ عَجْوَةٍ ‏ ‏مِنْ ‏ ‏بَيْنَ لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏عَلَى الرِّيقِ لَمْ يَضُرَّهُ يَوْمَهُ ذَلِكَ شَيْءٌ حَتَّى يُمْسِيَ ‏ ‏قَالَ ‏ ‏فُلَيْحٌ ‏ ‏وَأَظُنُّهُ قَالَ وَإِنْ أَكَلَهَا حِينَ يُمْسِي لَمْ يَضُرَّهُ شَيْءٌ حَتَّى يُصْبِحَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏انْظُرْ يَا ‏ ‏عَامِرُ ‏ ‏مَا تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَشْهَدُ مَا كَذَبْتُ عَلَى ‏ ‏سَعْدٍ ‏ ‏وَمَا كَذَبَ ‏ ‏سَعْدٌ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1366,1366,"","এক বছর আগে আমরা কীভাবে সাহায্য করতে চেষ্টা করেছিলাম, সে বিষয়ে আমরা কথা বলেছি । তাদের মুখ থেকে বলছি, আমি তার সাথে কিছু একটা করতে চাই, বাবা চায়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏رَكِبَ إِلَى قَصْرِهِ ‏ ‏بِالْعَقِيقِ ‏ ‏فَوَجَدَ غُلَامًا ‏ ‏يَخْبِطُ ‏ ‏شَجَرًا ‏ ‏أَوْ يَقْطَعُهُ ‏ ‏فَسَلَبَهُ ‏ ‏فَلَمَّا رَجَعَ ‏ ‏سَعْدٌ ‏ ‏جَاءَهُ أَهْلُ الْغُلَامِ فَكَلَّمُوهُ أَنْ يَرُدَّ مَا أَخَذَ مِنْ غُلَامِهِمْ فَقَالَ ‏ ‏مَعَاذَ اللَّهِ أَنْ أَرُدَّ شَيْئًا ‏ ‏نَفَّلَنِيهِ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَى أَنْ يَرُدَّ عَلَيْهِمْ ‏","","",""],[1367,1367,"","আমরা আমার বাবার সঙ্গে নির্দিষ্ট একটা বাধ্যতার দ্বারা বাপ্তাইজিত হওয়ার বিষয়ে কথা বলেছিলাম । আমি ঈশ্বর নির্বাচন করছি এবং একটি ছেলে যে তার দয়া এবং একটি ছেলের ক্ষমতা দ্বারা সন্তুষ্ট, যে তার জীবনের আনন্দ নিয়ে তাকে ছেড়ে চলে গেছে। আমি পরিকল্পনা করব যখন ঈশ্বর আসবে, তখন আমি তাকে খুঁজে বের করব। জিতে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏أَمْلَاهُ عَلَيْنَا ‏ ‏بِبَغْدَادَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حُمَيْدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سَعَادَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏اسْتِخَارَتُهُ اللَّهَ وَمِنْ سَعَادَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏رِضَاهُ بِمَا قَضَاهُ اللَّهُ وَمِنْ شِقْوَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏تَرْكُهُ اسْتِخَارَةَ اللَّهِ وَمِنْ شِقْوَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏سَخَطُهُ بِمَا قَضَى اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[1368,1368,"","আমরা আমার বাবার সঙ্গে আমার প্রেমের দ্বারা বাপ্তাইজিত হওয়ার বিষয়ে কথা বলেছিলাম । দুঃখময় মহিলা আর সূর্যের দুঃখের কথা হবে... ...আর খারাপ যাত্রা হবে.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سَعَادَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏ثَلَاثَةٌ وَمِنْ شِقْوَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏ثَلَاثَةٌ ‏ ‏مِنْ سَعَادَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏الْمَرْأَةُ الصَّالِحَةُ وَالْمَسْكَنُ الصَّالِحُ وَالْمَرْكَبُ الصَّالِحُ وَمِنْ شِقْوَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏الْمَرْأَةُ السُّوءُ وَالْمَسْكَنُ السُّوءُ وَالْمَرْكَبُ السُّوءُ ‏","","",""],[1369,1369,"","বাবার সাথে আমার উলকি নিয়ে আমাকে সাহায্য করার কথা উনি আমার বাবার কথা শুনেছেন। তিনি বলেছেন তুমি শপথের একটা ভালো শপথ হবে এবং আমি তাকে দেখছি, আর আমি তাকে বলছি, আমার বাবার সাথে আমার ছবি তোলার সময় তিনি আমাকে সাহায্য করেছেন। তিনি আমার বাবার কথা শুনেছেন। তিনি বললেন, আপনি শপথটা শোনার পর, আপনি একজন পরাজিত ব্যক্তি। এবং আমি তাকে বলেছিলাম, আমি বলেছিলাম, আমি আমার বাবার কাছে এটা নিয়ে কথা বলেছি। আমি বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি আমার বাবার কথা শুনেছি, আমি আমার বাবার কথা শুনেছি, আমি বলেছিলাম। আমি আমার বাবার কথা শুনেছি, আমি বলেছিলাম, আমি বলেছিলাম, আমি আমার বাবার কথা শুনেছি, আমি আমার বাবার কাছে যা শুনেছি, আমি বলেছিলাম, আমি তাকে বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি আমার বাবার কথা শুনেছি, আমি যদি আমার বাবার কাছ থেকে কিছু শুনতে চাই না, আর আমি আমার বাবার কাছে এটা একটা বড় কথা শুনেছি। আর আমি তোমার কাছে একটা শপথ নিতে চাই না। আর আমি জানি না। আর আমি তাকে আমি বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি জানি, আমি জানি, আমি জানি না যে তুমি আমার বাবার কাছে এটা একটা কথা বলতে চাই। আর আমি যা তুমি জানো না। আর আমি তোমার কাছে এটা একটা কথা বলতে চাই। আর আমি কি হয়েছে। আর আমি তোমার কাছে এটা একটা বড় সমস্যা হল নিয়মের আরেকটা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏حُسَيْنَ بْنَ عَبْدِ الرَحَّمَنِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَتَكُونُ فِتْنَةٌ الْقَاعِدُ فِيهَا خَيْرٌ مِنْ الْقَائِمِ وَالْقَائِمُ فِيهَا خَيْرٌ مِنْ الْمَاشِي وَيَكُونُ الْمَاشِي فِيهَا خَيْرًا مِنْ السَّاعِي ‏ ‏قَالَ وَأُرَاهُ قَالَ وَالْمُضْطَجِعُ فِيهَا خَيْرٌ مِنْ الْقَاعِدِ ‏","","",""],[1370,1370,"","আমরা আপনাদের নাম নিয়ে কথা বলেছি যে একজন ভাইয়ের ছেলে হতে আমাকে সাহায্য করেছে। তিনি আমার ছেলেকে উদ্ধার করতে বলেছেন যে আমরা তাদের একজন আর আমরা তাদের মধ্যে আছি আমার ভাই আপনার টাকা কামাবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَخٍ لِسَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِبَنِي نَاجِيَةَ ‏ ‏أَنَا مِنْهُمْ وَهُمْ مِنِّي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَذَكَرَ الْحَدِيثَ بِقِصَّةٍ فِيهِ ‏ ‏فَقَالَ ‏ ‏ابْنُ أَخِي سَعْدِ بْنِ مَالِكٍ ‏ ‏قَدْ ذَكَرُوا ‏ ‏بَنِي نَاجِيَةَ ‏ ‏عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هُمْ حَيٌّ مِنِّي ‏ ‏وَلَمْ يُذْكَرْ فِيهِ ‏ ‏سَعْدٌ ‏","","",""],[1371,1371,"","আমরা একটি ছেলে সম্পর্কে কথা বলেছি যে আমাদের সাথে এমন এক ছেলের সাথে এমন একটা ছেলের সাথে এমন হয়েছিল যে আমাকে সাহায্য করবে। আমার বাবার দাদা তার কাছে প্রার্থনা করেছিল আর তিনি বলতেন যে, যদি সে না বলে যে তাকে খুনের জন্য গ্রেফতার করা হয়েছে। অদ্ভুত ব্যাপার, নক্ষত্রের আলো স্পর্শ করে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ مَا ‏ ‏يُقِلُّ ‏ ‏ظُفُرٌ مِمَّا فِي الْجَنَّةِ بَدَا لَتَزَخْرَفَتْ لَهُ مَا بَيْنَ ‏ ‏خَوَافِقِ ‏ ‏السَّمَوَاتِ وَالْأَرْضِ وَلَوْ أَنَّ رَجُلًا مِنْ أَهْلِ الْجَنَّةِ اطَّلَعَ فَبَدَا سِوَارُهُ ‏ ‏لَطَمَسَ ‏ ‏ضَوْءُهُ ضَوْءَ الشَّمْسِ كَمَا تَطْمِسُ الشَّمْسُ ضَوْءَ النُّجُومِ ‏","","",""],[1372,1372,"","আমরা এক বছর আগে যে কথা শুনেছি, সে আমাকে আর আমার ছেলে বানিয়েছে যে ঈশ্বরকে রক্ষা করার জন্য, আর সে ছিল স্বপ্নের ছেলে। কথা বলার পর, ঈশ্বর একটা কুত্তার বাচ্চাকে তার মৃত্যুর পর দেখতে চেয়েছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏الْحَدُوا ‏ ‏لِي ‏ ‏لَحْدًا ‏ ‏وَانْصِبُوا ‏ ‏عَلَيَّ ‏ ‏اللَّبِنَ ‏ ‏نَصْبًا ‏ ‏كَمَا صُنِعَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏وَوَافَقَهُ ‏ ‏أَبُو سَعِيدٍ ‏ ‏عَلَى ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏كَمَا قَالَ ‏ ‏الْخُزَاعِيُّ ‏","","",""],[1373,1373,"","আমরা আমার ভয়কে খুঁজে পেয়েছি যে আমরা নিজের কথা দিয়ে আমাকে সাহায্য করার চেষ্টা করেছি। আমার বাবা আমার ছেলের একজন সন্তান আছে। তিনি আছে এবং তিনি এই কেলেঙ্কারের ব্যাপারে বলেছেন। তোমার নিজের মত না।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْمَسْحِ عَلَى الْخُفَّيْنِ لَا ‏ ‏بَأْسَ ‏ ‏بِذَلِكَ ‏","","",""],[1374,1374,"","আমি আমার বাবার কথা বলেছি একটি ভাল জীবনের জন্য আমাকে খুন করার চেষ্টা করার কথা। আমি আমার বাবা যা শুনেছি তা শুনেছি। তার জন্য প্রার্থনা করা এবং কিছু লোকের কাছে বলতে শুনেছি যে তিনি ঈশ্বরের ইচ্ছা পালন করতে চান। শালা কুত্তার বাচ্চা.","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ يَعْنِي ابْنَ أَنَسٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏مَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لِحَيٍّ مِنْ النَّاسِ يَمْشِي إِنَّهُ فِي الْجَنَّةِ إِلَّا ‏ ‏لِعَبْدِ اللَّهِ بْنِ سَلَامٍ ‏","","",""],[1375,1375,"","আমরা আমার বাবার অমরতা নিয়ে কথা বলেছি... ...যখন থেকে তিনি বললেন আমি কেন মেহমান হব? সে আমাকে ঈশ্বরের অনুগ্রহের কথা বলেছে, বাবা বলেছে সে এটা করবে না, ঈশ্বর তার কাছে প্রার্থনা করে আত্মসমর্পণ করে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ ‏ ‏لَمَّا ادُّعِيَ ‏ ‏زِيَادٌ ‏ ‏لَقِيتُ ‏ ‏أَبَا بَكْرَةَ ‏ ‏قَالَ فَقُلْتُ مَا هَذَا الَّذِي صَنَعْتُمْ إِنِّي ‏ ‏سَمِعْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُ ‏ ‏سَمِعَ أُذُنِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏مَنْ ادَّعَى أَبًا فِي الْإِسْلَامِ غَيْرَ أَبِيهِ وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏وَأَنَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1376,1376,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তিনি বলেছিলেন, আপনি পরের জনের হাতে হাত কেটে দেবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏وُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي وَاقِدٍ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُقْطَعُ الْيَدُ فِي ثَمَنِ ‏ ‏الْمِجَنِّ ‏","","",""],[1377,1377,"","আমি আমার বাবার হাত কথা বলেছিলাম আমাকে গোলাম বলে। সে আমাকে তার শিক্ষা দেয়ার জন্য ঈশ্বরের কাছে প্রার্থনা করতে বলেছিল এবং আমাকে ফোন করতে বলেছিল, যখন আমি সিনেমা হতে যাচ্ছি না, তখন আমাকে ফোন করতে হবে। সম্মানের দিন।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حُمَيْدٍ الْمَدَنِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُنَادِيَ أَيَّامَ ‏ ‏مِنًى ‏ ‏إِنَّهَا أَيَّامُ أَكْلٍ وَشُرْبٍ فَلَا صَوْمَ فِيهَا ‏ ‏يَعْنِي ‏ ‏أَيَّامَ التَّشْرِيقِ ‏","","",""],[1378,1378,"","আমরা আমাদের ভালোবাসায় বাপ্তাইজিত হয়েছি যে আমরা আগের চেয়ে ভাল করেছি, একটা সুখী ছেলে আমার বাবা আর একজন সাহায্যকারীকে ফিরে আসবে, যে বলেছে সে আমার নিরস্ত্রদের সাথে কি করছে তিনি তার আশীর্বাদ ও আশীর্বাদের আশীর্বাদকে কীভাবে আশীর্বাদ করে তা প্রত্যাখ্যান করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفُضَيْلُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏حَرَامٌ قَدْ حَرَّمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا حَرَّمَ ‏ ‏إِبْرَاهِيمُ ‏ ‏مَكَّةَ ‏ ‏اللَّهُمَّ اجْعَلْ الْبَرَكَةَ فِيهَا بَرَكَتَيْنِ وَبَارِكْ لَهُمْ فِي ‏ ‏صَاعِهِمْ ‏ ‏وَمُدِّهِمْ ‏","","",""],[1379,1379,"","আমরা যে বাপ্তিস্মের কথা বলেছি, আমাদের এক বছর কাজ করতে হবে, ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং আমি তার ভাগ্যকে আত্মসমর্পণ করব এবং তার ইচ্ছার কথা ভুলে যাবো। আমি আমার ভাইয়ের কাছে যাওয়ার জন্য চলে যাই ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ ‏ ‏بِقَصْعَةٍ ‏ ‏فَأَكَلَ مِنْهَا فَفَضَلَتْ فَضْلَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجِيءُ رَجُلٌ مِنْ هَذَا ‏ ‏الْفَجِّ ‏ ‏مِنْ أَهْلِ الْجَنَّةِ يَأْكُلُ هَذِهِ الْفَضْلَةَ قَالَ ‏ ‏سَعْدٌ ‏ ‏وَكُنْتُ تَرَكْتُ أَخِي ‏ ‏عُمَيْرًا ‏ ‏يَتَوَضَّأُ قَالَ فَقُلْتُ هُوَ ‏ ‏عُمَيْرٌ ‏ ‏قَالَ فَجَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ سَلَامٍ ‏ ‏فَأَكَلَهَا ‏","","",""],[1380,1380,"","আমার বাবা একজন আধুনিক রক্ষক ছিলেন, যিনি তার ভয়কে ধরে রেখেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا النَّضْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏حَدِيثًا رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْوُضُوءِ عَلَى الْخُفَّيْنِ أَنَّهُ لَا ‏ ‏بَأْسَ ‏ ‏بِهِ ‏","","",""],[1381,1381,"","বাবার দৃঢ় থাকার ব্যাপারে আমরা আমাদের কথোপকথনের কথা বলেছিলাম কিন্তু আমার ভালবাসা হয়তো আমার বাবা আর একজন মানুষ পরে গিয়েছিল যে Dame এর যুদ্ধে আটকা পড়ে ছিল, যাকে ঈশ্বর নিষেধ করেছেন। তারপর তিনি বললেন যে ঈশ্বর তার কাছে প্রার্থনা করেছেন যে তিনি একটি যুদ্ধ অস্বীকার করা হয়েছে। আমি এটা করবো। একবার আমি ভেবেছিলাম এটা এমন কিছু যা আমি তোমাকে দিতে পারবো এবং তারপর তারপর আমি তাকে দিবো। আমি তোমাকে দিলাম","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنِي ‏ ‏يَعْلَى بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ أَبِي عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏أَخَذَ رَجُلًا يَصِيدُ فِي حَرَمِ ‏ ‏الْمَدِينَةِ ‏ ‏الَّذِي حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَبَهُ ثِيَابَهُ فَجَاءَ مَوَالِيهِ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ هَذَا ‏ ‏الْحَرَمَ ‏ ‏وَقَالَ مَنْ رَأَيْتُمُوهُ يَصِيدُ فِيهِ شَيْئًا فَلَهُ سَلَبُهُ فَلَا أَرُدُّ عَلَيْكُمْ طُعْمَةً أَطْعَمَنِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ إِنْ شِئْتُمْ أَعْطَيْتُكُمْ ثَمَنَهُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً إِنْ شِئْتُمْ أَنْ أُعْطِيَكُمْ ثَمَنَهُ ‏ ‏أَعْطَيْتُكُمْ ‏","","",""],[1382,1382,"","বাবার ছেলে আমাকে ঈশ্বরের অনুগ্রহে রক্ষা করার চেষ্টা করে, সে আমার বাবার কাছে ফিরে যাওয়ার কথা বলেছিল আর একমাত্র কারণ হল সে শেষ ডিনারে প্রার্থনা করছিল তার মহিমা ছিল শেষ। কেউ তাকে বলতে পারবে না যে তার একটা শপথ আছে। ঈশ্বর তার কাছে প্রার্থনা করলেন আর বলবে যে, কে ঘুমোলো না যতক্ষণ না পর্যন্ত না সে ঘুমাতে যায়।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ الْحُصَيْنِ ‏ ‏أَنَّهُ حَدَّثَ عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي الْعِشَاءَ الْآخِرَةَ فِي ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏يُوتِرُ ‏ ‏بِوَاحِدَةٍ لَا يَزِيدُ عَلَيْهَا قَالَ فَيُقَالُ لَهُ أَتُوتِرُ بِوَاحِدَةٍ لَا تَزِيدُ عَلَيْهَا يَا ‏ ‏أَبَا إِسْحَاقَ ‏ ‏فَيَقُولُ نَعَمْ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الَّذِي لَا يَنَامُ حَتَّى ‏ ‏يُوتِرَ ‏ ‏حَازِمٌ ‏","","",""],[1383,1383,"","আমার বাবার সঙ্গে আমরা যেভাবে কথা বলেছিলাম, সেই বিষয়ে আমরা কথা বলেছিলাম । আদেশ করুন, কিন্তু আমি ভুল করেছি আমি বলেছিলাম আমি পরের বার যখন ফোন করেছি, সিঁড়ির সিঁড়ির কাছে বলেছিলাম সে তোমাকে কোন মূল্য দিতে চায়... তিনি বলেছিলেন যে আমি এমনকি বলতে চেষ্টা করেছি, তিনি বললেন যে তিনি বললেন, “সে বলল যে তিনি বললেন, তিনি বললেন । সে এটা করেছে, আমি আমার নিঃশ্বাসের কথা বলছি, আমি ঈশ্বরের অনুগ্রহ থেকে শুনেছি, ঈশ্বর তাকে এটা করতে বলেছেন। আমার দৃষ্টি ছিল যে তিনি খুশি ছিলেন যে, তিনি আপনাকে বলেছিলেন। ঈশ্বর সেটা দিয়েছেন আর তারপর বললেন যে তিনি এটা করেছেন, আমি তার সাথে লড়াই করছি যতক্ষণ না সে ঈশ্বরের কাছে যায়, তাকে তার বই উদ্ধার করতে হবে আর সে তার বই পৌঁছে দেবে। আমি ঈশ্বরকে জিজ্ঞেস করছি, তিনি কে? তিনি বলেছিলেন আমি ঈশ্বরকে বলি না, তুমি আমাদের প্রথম ফোনটা উল্লেখ করো নি, আর তারপর এটা শেষ হল, যদি তিনি ছায়ার দুর্দশায় থাকেন, সে আমার প্রভু হবে না, উত্তর দাও।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ الْهَمْدَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏وَالِدِي ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ ‏ ‏بِعُثْمَانَ بْنِ عَفَّانَ ‏ ‏فِي الْمَسْجِدِ فَسَلَّمْتُ عَلَيْهِ فَمَلَأَ عَيْنَيْهِ مِنِّي ثُمَّ لَمْ يَرُدَّ عَلَيَّ السَّلَامَ فَأَتَيْتُ أَمِيرَ الْمُؤْمِنِينَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ هَلْ حَدَثَ فِي الْإِسْلَامِ شَيْءٌ مَرَّتَيْنِ قَالَ لَا وَمَا ذَاكَ قَالَ قُلْتُ لَا إِلَّا أَنِّي مَرَرْتُ ‏ ‏بِعُثْمَانَ ‏ ‏آنِفًا ‏ ‏فِي الْمَسْجِدِ فَسَلَّمْتُ عَلَيْهِ فَمَلَأَ عَيْنَيْهِ مِنِّي ثُمَّ لَمْ يَرُدَّ عَلَيَّ السَّلَامَ قَالَ فَأَرْسَلَ ‏ ‏عُمَرُ ‏ ‏إِلَى ‏ ‏عُثْمَانَ ‏ ‏فَدَعَاهُ فَقَالَ مَا مَنَعَكَ أَنْ لَا تَكُونَ رَدَدْتَ عَلَى أَخِيكَ السَّلَامَ قَالَ ‏ ‏عُثْمَانُ ‏ ‏مَا فَعَلْتُ قَالَ ‏ ‏سَعْدٌ ‏ ‏قُلْتُ بَلَى قَالَ حَتَّى حَلَفَ وَحَلَفْتُ قَالَ ثُمَّ إِنَّ ‏ ‏عُثْمَانَ ‏ ‏ذَكَرَ فَقَالَ بَلَى وَأَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ إِنَّكَ مَرَرْتَ بِي ‏ ‏آنِفًا ‏ ‏وَأَنَا أُحَدِّثُ نَفْسِي بِكَلِمَةٍ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا وَاللَّهِ مَا ذَكَرْتُهَا قَطُّ إِلَّا تَغَشَّى بَصَرِي وَقَلْبِي غِشَاوَةٌ قَالَ قَالَ ‏ ‏سَعْدٌ ‏ ‏فَأَنَا أُنْبِئُكَ بِهَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ لَنَا أَوَّلَ دَعْوَةٍ ثُمَّ جَاءَ أَعْرَابِيٌّ فَشَغَلَهُ حَتَّى قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاتَّبَعْتُهُ فَلَمَّا أَشْفَقْتُ أَنْ يَسْبِقَنِي إِلَى مَنْزِلِهِ ضَرَبْتُ بِقَدَمِي الْأَرْضَ فَالْتَفَتَ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ هَذَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ قُلْتُ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏فَمَهْ ‏ ‏قَالَ قُلْتُ لَا وَاللَّهِ إِلَّا أَنَّكَ ذَكَرْتَ لَنَا أَوَّلَ دَعْوَةٍ ثُمَّ جَاءَ هَذَا الْأَعْرَابِيُّ فَشَغَلَكَ قَالَ نَعَمْ دَعْوَةُ ‏ ‏ذِي النُّونِ ‏ ‏إِذْ هُوَ فِي بَطْنِ الْحُوتِ ‏ { ‏لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنْ الظَّالِمِينَ ‏} ‏فَإِنَّهُ لَمْ يَدْعُ بِهَا مُسْلِمٌ رَبَّهُ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ لَهُ ‏","","",""],[1384,1384,"","বাবা আমাকে সাহায্য করার কথা বলেছিলাম, তুমি তার বাবার সাথে বাইরে যেতে পেরে খুশি যে তার জন্য প্রার্থনা করেছে আর তাকে আমার বুকে ফিরে আসার আগ পর্যন্ত পৌঁছে দেয়া হবে। বাবা বলেন তুমি আমার সাথে এমন ভয় নিয়ে এসেছ... ...নাকির সাথে তোমার বিয়ে হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏الْجُعَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏خَرَجَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى جَاءَ ‏ ‏ثَنِيَّةَ الْوَدَاعِ ‏ ‏وَعَلِيٌّ ‏ ‏يَبْكِي يَقُولُ تُخَلِّفُنِي مَعَ الْخَوَالِفِ فَقَالَ ‏ ‏أَوَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏إِلَّا النُّبُوَّةَ ‏","","",""],[1385,1385,"","আমরা একজন প্রবীনকের কথা বলেছিলাম যিনি আমার সাথে একজন বয়স্ক ছেলে হিসেবে কথা বলেছিলেন, যিনি আমার বাবার সাথে এক ছেলের সাথে থাকার কথা বলেছিলেন। আমি মনে করেছিলাম যে, আমার মা যিহোবার কাছে প্রার্থনা করবেন । পাঁচ বছর আগে।","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏لَا تَعْجِزُ أُمَّتِي عِنْدَ رَبِّي أَنْ يُؤَخِّرَهَا نِصْفَ يَوْمٍ ‏ ‏وَسَأَلْتُ ‏ ‏رَاشِدًا ‏ ‏هَلْ بَلَغَكَ مَاذَا النِّصْفُ يَوْمٍ ‏ ‏قَالَ ‏ ‏خَمْسُ مِائَةِ سَنَةٍ ‏","","",""],[1386,1386,"","আমরা বাবার মৃত্যুর কথা বলেছিলাম, ঈশ্বর এটা উদ্ধার করতে হবে আর তিনি বললেন যে আমার তাকে ছেড়ে যাওয়া উচিৎ নয়.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنِّي لَأَرْجُو أَنْ لَا يَعْجِزَ أُمَّتِي عِنْدَ رَبِّي أَنْ يُؤَخِّرَهُمْ نِصْفَ يَوْمٍ ‏ ‏فَقِيلَ ‏ ‏لِسَعْدٍ ‏ ‏وَكَمْ نِصْفُ يَوْمٍ ‏ ‏قَالَ ‏ ‏خَمْسُ مِائَةِ سَنَةٍ ‏","","",""],[1387,1387,"","আমরা বাবার মৃত্যুর পর বাবার সাথে কথা বলেছিলাম, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর এই পাপের জন্য আমি তোমাকে আত্মসমর্পণ করব... ...তার জন্য ঈশ্বর তাঁর কাছে প্রার্থনা করে, আর তিনি তার জন্য প্রার্থনা করবেন হয় এটা একটা মেয়ে হিসেবে পৌঁছে দিয়ে দেবে যে আর কথা বলতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ هَذِهِ الْآيَةِ ‏ { ‏هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنَّهَا ‏ ‏كَائِنَةٌ ‏ ‏وَلَمْ يَأْتِ ‏ ‏تَأْوِيلُهَا ‏ ‏بَعْدُ ‏","","",""],[1388,1388,"","আমরা কথা বলেছিলাম যে ঈশ্বর আমাদের আমার ভালবাসার কথা বলেছেন, কিন্তু আমি আমার বাবার কাছে প্রতিজ্ঞা করছি যে তিনি কি? সূর্যের আলো যেভাবে নক্ষত্রগুলোর জ্যোতিকে স্পর্শ করে","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ مَا ‏ ‏يُقِلُّ ‏ ‏ظُفُرٌ مِمَّا فِي الْجَنَّةِ بَدَا لَتَزَخْرَفَتْ لَهُ ‏ ‏خَوَافِقُ ‏ ‏السَّمَوَاتِ وَالْأَرْضِ وَلَوْ أَنَّ رَجُلًا مِنْ أَهْلِ الْجَنَّةِ اطَّلَعَ فَبَدَتْ أَسَاوِرُهُ ‏ ‏لَطَمَسَ ‏ ‏ضَوْءُهُ ضَوْءَ الشَّمْسِ كَمَا تَطْمِسُ الشَّمْسُ ضَوْءَ النُّجُومِ ‏","","",""],[1389,1389,"","আমরা দুটো উপায় নিয়ে কথা বলেছি, বাবাকে সাহায্য করার জন্য। সে আমাকে লর্ডকে তার একমাত্র শান্তি দিয়েছে। এটা আমার দেখা সবচেয়ে বেশি হত্যা।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُ عَنْ يَمِينِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ يَسَارِهِ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏رَجُلَيْنِ عَلَيْهِمَا ثِيَابٌ بِيضٌ يُقَاتِلَانِ عَنْهُ كَأَشَدِّ الْقِتَالِ مَا رَأَيْتُهُمَا قَبْلُ وَلَا بَعْدُ ‏","","",""],[1390,1390,"","আমরা আমার বাবাকে \"ঈশ্বর\" বলে ফোন করে চুরি করার চেষ্টা করেছি। একজন সাহায্যকারী বলেছেন, আমি ভাববাদীর কাছে প্রার্থনা করেছি এবং তাকে ছেড়ে দেব। এমনকি সূর্যও আমার এক লোককে নিয়ে কথা বলেছিল। আমার বাবা, একজন রক্ষক, লর্ডের প্রার্থনা শুনলো... ...আর সে তার আদর্শে আত্মসমর্পণ করলো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُعَاذٍ التَّيْمِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاتَانِ لَا يُصَلَّى بَعْدَهُمَا الصُّبْحُ حَتَّى تَطْلُعَ الشَّمْسُ وَالْعَصْرُ حَتَّى تَغْرُبَ الشَّمْسُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ عَنْ أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي تَيْمٍ ‏ ‏يُقَالُ لَهُ ‏ ‏مُعَاذٌ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[1391,1391,"","আমরা তার দাদার কথা বলেছিলাম তিনি এটা নিয়ে কথা বলতে পেরে খুশি হবেন। তিনি আমাকে আমার বাবা আর একজন রক্ষকের কাছে যেতে শুনেছেন যে কে তার শান্তি দিবে আর হবে তার শান্তি, আমি এমন একজন মানুষ যে কিনা ভালো খেলাটা করেছে... ...যে তাদের সামনে যেভাবে দেখেছি সেভাবে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏وَسَعْدٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُ عَنْ يَمِينِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ يَسَارِهِ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏رَجُلَيْنِ عَلَيْهِمَا ثِيَابٌ بِيضٌ يُقَاتِلَانِ عَنْهُ كَأَشَدِّ الْقِتَالِ مَا رَأَيْتُهُمَا قَبْلُ وَلَا بَعْدُ ‏","","",""],[1392,1392,"","বাবা আমার বাবাকে খুব ভালো করেই জানতেন । কে তা করতে বলেছে, সে তার কবর থেকে নারীদের পাবে যারা কথা বলবে এবং সে আর খুঁজে পাবে না। ঈশ্বর তার জন্য প্রার্থনা করুন, আর তিনি আপনাকে সাহায্য করবেন। ঈশ্বর তার কাছে প্রার্থনা করেছেন যেন আমি আত্মসমর্পণ করি, প্রেম বড় হয়ে গেছে, তুমি যাবে, ঈশ্বরের কাছে যাও, সে ছেড়ে দেবে, আর সে এটা ছেড়ে দেবে ঈশ্বরের কাছে। তার কাছে প্রার্থনা করো আর সে আত্মসমর্পণ করবে, আর আমার আত্মা কখনো তোমার শয়তানকে হারাবে না। সে বলেছিল সে তাকে থামিয়ে দেবে আমি যা শুনেছি তা হল, আমি যা শুনেছি তা তার মুখ বন্ধ করে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْحَمِيدِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ زَيْدٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏عُمَرُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ نِسَاءٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُكَلِّمْنَهُ وَيَسْتَكْثِرْنَهُ عَالِيَةٌ أَصْوَاتُهُنَّ فَلَمَّا اسْتَأْذَنَ قُمْنَ يَبْتَدِرْنَ الْحِجَابَ فَأَذِنَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي فَدَخَلَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَضْحَكُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَضْحَكَ اللَّهُ سِنَّكَ يَا رَسُولَ اللَّهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِبْتُ مِنْ هَؤُلَاءِ اللَّاتِي كُنَّ عِنْدِي فَلَمَّا سَمِعْنَ صَوْتَكَ ابْتَدَرْنَ الْحِجَابَ قَالَ ‏ ‏عُمَرُ ‏ ‏فَأَنْتَ يَا رَسُولَ اللَّهِ كُنْتَ أَحَقَّ أَنْ يَهَبْنَ ثُمَّ قَالَ ‏ ‏عُمَرُ ‏ ‏أَيْ عَدُوَّاتِ أَنْفُسِهِنَّ أَتَهَبْنَنِي وَلَا تَهَبْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْنَ نَعَمْ أَنْتَ أَغْلَظُ وَأَفَظُّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا لَقِيَكَ الشَّيْطَانُ قَطُّ سَالِكًا ‏ ‏فَجًّا ‏ ‏إِلَّا سَلَكَ ‏ ‏فَجًّا ‏ ‏غَيْرَ فَجِّكَ ‏ ‏و قَالَ ‏ ‏يَعْقُوبُ ‏ ‏مَا أُحْصِي مَا سَمِعْتُهُ يَقُولُ حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏","","",""],[1393,1393,"","আমরা দুজন খুশি সাক্ষীর কথা বলেছি, বাবা বলেছিলেন আমার বাবা একটা কুত্তার ছেলে, আমি আমার বাবা আর একজন রক্ষককে শাসন করবো। হাঙ্গর হলো ঈশ্বরের প্রিয় এবং কাপুরুষ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏وَسَعْدٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي سُفْيَانَ بْنِ جَارِيَةَ ‏ ‏أَنَّ ‏ ‏يُوسُفَ بْنَ الْحَكَمِ أَبَا الْحَجَّاجِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يُرِدْ هَوَانَ ‏ ‏قُرَيْشٍ ‏ ‏أَهَانَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[1394,1394,"","আমি আমার টাকা আর টাকা দিয়ে সুপারিশ করছি। আমি তৃতীয় জনের জন্য যাচ্ছি, আমি তোমাকে বলছি না যে আমি তোমাকে অর্ধেক বলছি আর আমি তোমাকে যেতে বলছি না। ৩ বার আমি চলে যাচ্ছি। ঈশ্বর জানেন কিভাবে সাহায্য করতে হয়, এবং আমি মনে করি আমি বরং তোমাকে সাহায্য করব। আমি যদি বলি, আমি তিন বার তার হাত খুঁজে বের করতে পারি, তাহলে আমি তোমাকে বলছি, তাকে খুঁজে বের করো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏الْجَعْدِ بْنِ أَوْسٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ بِنْتُ سَعْدٍ ‏ ‏قَالَتْ قَالَ ‏ ‏سَعْدٌ ‏ ‏اشْتَكَيْتُ شَكْوًى لِي ‏ ‏بِمَكَّةَ ‏ ‏فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُنِي قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي قَدْ تَرَكْتُ مَالًا وَلَيْسَ لِي إِلَّا ابْنَةٌ وَاحِدَةٌ ‏ ‏أَفَأُوصِي بِثُلُثَيْ مَالِي وَأَتْرُكُ لَهَا الثُّلُثَ قَالَ لَا قَالَ ‏ ‏أَفَأُوصِي بِالنِّصْفِ وَأَتْرُكُ لَهَا النِّصْفَ قَالَ لَا قَالَ ‏ ‏أَفَأُوصِي بِالثُّلُثِ وَأَتْرُكُ لَهَا الثُّلُثَيْنِ قَالَ الثُّلُثُ وَالثُّلُثُ كَثِيرٌ ثَلَاثَ مِرَارٍ قَالَ فَوَضَعَ يَدَهُ عَلَى جَبْهَتِهِ فَمَسَحَ وَجْهِي وَصَدْرِي وَبَطْنِي وَقَالَ ‏ ‏اللَّهُمَّ اشْفِ ‏ ‏سَعْدًا ‏ ‏وَأَتِمَّ لَهُ هِجْرَتَهُ فَمَا زِلْتُ يُخَيَّلُ إِلَيَّ بِأَنِّي أَجِدُ بَرْدَ يَدِهِ عَلَى كَبِدِي حَتَّى السَّاعَةِ ‏","","",""],[1395,1395,"","আমরা এমন একটা ছেলের কথা বলেছিলাম যে আগে আমার বাবার কথা শুনেছিলো. সে তোমাকে অনেক কষ্ট দিয়েছে, কিন্তু আমরা ঈশ্বরের বার্তাবাহকের সাথে ছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏سَعْدًا ‏ ‏سَمِعَ رَجُلًا يَقُولُ لَبَّيْكَ ذَا الْمَعَارِجِ فَقَالَ ‏ ‏إِنَّهُ لَذُو الْمَعَارِجِ وَلَكِنَّا كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَقُولُ ذَلِكَ ‏","","",""],[1396,1396,"","আমরা ইতিমধ্যে একে অপরের সাথে কথা বলেছি, আমার ভালোবাসার সবচেয়ে ভালোটা পেয়ে আমরা খুশি হব। আমার বাবা ঈশ্বরের কাছে প্রার্থনা করলেন, আর আমাদের মধ্যে কেউ যেন আপনার গান না শোনে মন, সে আমাকে গানও শোনে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ حَسَّانَ الْمَخْزُومِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي نَهِيكٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنَّا مَنْ لَمْ ‏ ‏يَتَغَنَّ ‏ ‏بِالْقُرْآنِ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏يَعْنِي ‏ ‏يَسْتَغْنِي بِهِ ‏","","",""],[1397,1397,"","আমরা অনেকবার কথা বলেছি যখন আমার বাবা ঈশ্বরের অনুগ্রহে আশীর্বাদ পেয়েছে, ঈশ্বরের ইচ্ছার জন্য প্রার্থনা করবে, আর তিনি আমার ছেলের দুঃখের আলো নিয়ে মন দান করবেন। আমার বাবা আমাকে বলেছিলেন যে, তিনি আমার বাবাকেও বলেছিলেন এবং তিনি আমাকে বলেছিলেন যে, আমিও যেন সেই দেশের জন্য বাপ্তিস্ম নিই ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَبِيبَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ الذِّكْرِ الْخَفِيُّ وَخَيْرُ الرِّزْقِ مَا يَكْفِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَبِيبَةَ ‏ ‏أَخْبَرَهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و قَالَ ‏ ‏يَحْيَى يَعْنِي الْقَطَّانَ ‏ ‏ابْنَ أَبِي لَبِيبَةَ ‏ ‏أَيْضًا إِلَّا أَنَّهُ ‏ ‏قَالَ عَنْ ‏ ‏أُسَامَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ابْنِ لَبِيبَةَ ‏","","",""],[1398,1398,"","আমরা তার বাবার কাছে প্রার্থনা করার ব্যাপারে চিন্তিত ছিলাম, আমি বলতে গেলে অসুস্থ, প্রভু, আমি আমার টাকা সুপারিশ করছি না, যেমনটা তিনি বলেছিলেন.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهِ يَعُودُهُ وَهُوَ مَرِيضٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَلَا أُوصِي بِمَالِي كُلِّهِ قَالَ لَا قَالَ ‏ ‏فَبِالشَّطْرِ ‏ ‏قَالَ لَا قَالَ فَبِالثُّلُثِ قَالَ الثُّلُثُ وَالثُّلُثُ كَثِيرٌ ‏ ‏أَوْ كَبِيرٌ ‏","","",""],[1399,1399,"","আমরা অনেক বছর ধরে বেনকে তার লর্ডশিপে ফিরে যেতে পেরে খুশির সাথে কথা বলেছি, তাকে এমন এক পরিস্থিতি থেকে তোমাকে আত্মসমর্পণ করতে হবে, যা তোমাকে পালাতে বাধ্য করা হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ إِنَّكَ ‏ ‏مَهْمَا أَنْفَقْتَ عَلَى أَهْلِكَ مِنْ نَفَقَةٍ فَإِنَّكَ تُؤْجَرُ فِيهَا حَتَّى اللُّقْمَةَ تَرْفَعُهَا إِلَى ‏ ‏فِي امْرَأَتِكَ ‏","","",""],[1400,1400,"","আমরা রাজধানী বেনের মৃত্যুর অনেক বছর আগে এক সুখী ছেলের জন্য কথা বলেছি যে ঈশ্বরকে বলে, মানুষ মানুষের প্রতি অনুগত থাকে আত্মার প্রতি. তার কঠোর পরিশ্রমে তিনি লাক্সের ছায়ায় ছিলেন এবং তিনি যা করবেন ও তিনি যা করবেন, তা - ই করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيُّ النَّاسِ أَشَدُّ بَلَاءً قَالَ ‏ ‏الْأَنْبِيَاءُ ثُمَّ الصَّالِحُونَ ثُمَّ الْأَمْثَلُ فَالْأَمْثَلُ مِنْ النَّاسِ ‏ ‏يُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِينِهِ فَإِنْ كَانَ فِي دِينِهِ صَلَابَةٌ زِيدَ فِي بَلَائِهِ وَإِنْ كَانَ فِي دِينِهِ رِقَّةٌ خُفِّفَ عَنْهُ وَمَا يَزَالُ الْبَلَاءُ بِالْعَبْدِ حَتَّى يَمْشِيَ عَلَى ظَهْرِ الْأَرْضِ لَيْسَ عَلَيْهِ خَطِيئَةٌ ‏","","",""]];
